/* ============================================================
   LEHJA AI — START OR RESUME PLACEMENT
============================================================ */

const webhookJson = $("Webhook1").first().json;
const body = webhookJson.body ?? webhookJson ?? {};

/* ============================================================
   HELPERS
============================================================ */

function normalizeLanguage(value) {
  const language = String(value ?? "")
    .trim()
    .toLowerCase();

  if (
    language === "english" ||
    language === "en"
  ) {
    return "English";
  }

  return "MSA";
}

function parseJsonArray(value) {
  if (Array.isArray(value)) {
    return value.map(String);
  }

  if (
    value === null ||
    value === undefined ||
    value === ""
  ) {
    return [];
  }

  try {
    const parsed = JSON.parse(value);

    return Array.isArray(parsed)
      ? parsed.map(String)
      : [];
  } catch {
    return [];
  }
}

function shuffle(array) {
  const copy = [...array];

  for (
    let index = copy.length - 1;
    index > 0;
    index -= 1
  ) {
    const randomIndex = Math.floor(
      Math.random() * (index + 1)
    );

    [
      copy[index],
      copy[randomIndex],
    ] = [
      copy[randomIndex],
      copy[index],
    ];
  }

  return copy;
}

function makeOptions(question) {
  const options = [
    question.Option_A,
    question.Option_B,
    question.Option_C,
    question.Option_D,
  ]
    .filter((option) => {
      return (
        option !== null &&
        option !== undefined &&
        String(option).trim() !== ""
      );
    })
    .map((option) =>
      String(option).trim()
    );

  return shuffle(options).map(
    (option) => ({
      value: option,
      label: option,
    })
  );
}

/* ============================================================
   USER DATA
============================================================ */

const email = String(
  body.email ?? "guest@example.com"
).trim();

const userId = String(
  body.user_id ??
    `user-${email.toLowerCase()}`
).trim();

const requestedLanguage =
  normalizeLanguage(
    body.test_language ??
      body.interface_language ??
      body.preferred_language
  );

/* ============================================================
   QUESTION BANK
============================================================ */

const questionBank = $input
  .all()
  .map((item) => item.json)
  .filter((row) => {
    return (
      row &&
      row.Question_ID &&
      row.Question_Text &&
      row.Interface_Language &&
      row.Learning_Level
    );
  });

if (!questionBank.length) {
  throw new Error(
    "No valid questions were returned from Question_Bank."
  );
}

const availableLevels = [
  ...new Set(
    questionBank
      .map((row) =>
        Number(row.Learning_Level)
      )
      .filter((level) =>
        Number.isFinite(level)
      )
  ),
].sort((a, b) => a - b);

if (!availableLevels.length) {
  throw new Error(
    "No valid Learning_Level values were found."
  );
}

const minLevel = availableLevels[0];
const maxLevel =
  availableLevels[
    availableLevels.length - 1
  ];

/* ============================================================
   READ EXISTING ACTIVE SESSION
============================================================ */

const activeSessions =
  $("Get Active Session")
    .all()
    .map((item) => item.json)
    .filter((row) => {
      return (
        row &&
        row.session_id &&
        String(row.status) ===
          "in_progress"
      );
    });

const existingSession =
  activeSessions[0] ?? null;

const now =
  new Date().toISOString();

let session;
let dbOperation;

/* ============================================================
   CREATE OR RESUME SESSION
============================================================ */

if (existingSession) {
  dbOperation = "update";

  session = {
    sessionId: String(
      existingSession.session_id
    ),

    userId: String(
      existingSession.user_id ??
        userId
    ),

    email: String(
      existingSession.email ??
        email
    ),

    interfaceLanguage:
      normalizeLanguage(
        existingSession.interface_language
      ),

    status: "in_progress",

    currentLevel:
      Number(
        existingSession.current_level
      ) || minLevel,

    highestPassedLevel:
      Number(
        existingSession.highest_passed_level
      ) || minLevel,

    questionsAnswered:
      Number(
        existingSession.questions_answered
      ) || 0,

    totalCorrect:
      Number(
        existingSession.total_correct
      ) || 0,

    roundAnswered:
      Number(
        existingSession.round_answered
      ) || 0,

    roundCorrect:
      Number(
        existingSession.round_correct
      ) || 0,

    stableRounds:
      Number(
        existingSession.stable_rounds
      ) || 0,

    currentQuestionId: String(
      existingSession.current_question_id ??
        ""
    ).trim(),

    usedQuestionIds:
      parseJsonArray(
        existingSession.used_question_ids
      ),

    usedSourceIds:
      parseJsonArray(
        existingSession.used_source_ids
      ),

    usedPairIds:
      parseJsonArray(
        existingSession.used_pair_ids
      ),

    roundQuestionTypes:
      parseJsonArray(
        existingSession.round_question_types
      ),

    roundTopics:
      parseJsonArray(
        existingSession.round_topics
      ),

    finalLevel:
      Number(
        existingSession.final_level
      ) || 0,

    finishReason: String(
      existingSession.finish_reason ??
        ""
    ),

    createdAt: String(
      existingSession.created_at ??
        now
    ),

    updatedAt: now,

    finishedAt: String(
      existingSession.finished_at ??
        ""
    ),
  };
} else {
  dbOperation = "insert";

  const requestedSessionId = String(
    body.placement_session_id ??
      body.session_id ??
      ""
  ).trim();

  const sessionId =
    requestedSessionId ||
    `placement_${Date.now()}_${Math.random()
      .toString(36)
      .slice(2, 8)}`;

  session = {
    sessionId,

    userId,
    email,

    interfaceLanguage:
      requestedLanguage,

    status: "in_progress",

    currentLevel:
      minLevel,

    highestPassedLevel:
      minLevel,

    questionsAnswered: 0,
    totalCorrect: 0,

    roundAnswered: 0,
    roundCorrect: 0,

    stableRounds: 0,

    currentQuestionId: "",

    usedQuestionIds: [],
    usedSourceIds: [],
    usedPairIds: [],

    roundQuestionTypes: [],
    roundTopics: [],

    finalLevel: 0,
    finishReason: "",

    createdAt: now,
    updatedAt: now,
    finishedAt: "",
  };
}

/* ============================================================
   QUESTION SELECTION
============================================================ */

function registerQuestion(question) {
  const questionId = String(
    question.Question_ID
  ).trim();

  const sourceId = String(
    question.Source_ID ?? ""
  ).trim();

  const pairId = String(
    question.Pair_ID ?? ""
  ).trim();

  if (
    questionId &&
    !session.usedQuestionIds.includes(
      questionId
    )
  ) {
    session.usedQuestionIds.push(
      questionId
    );
  }

  if (
    sourceId &&
    !session.usedSourceIds.includes(
      sourceId
    )
  ) {
    session.usedSourceIds.push(
      sourceId
    );
  }

  if (
    pairId &&
    !session.usedPairIds.includes(
      pairId
    )
  ) {
    session.usedPairIds.push(
      pairId
    );
  }

  const questionType = String(
    question.Question_Type ?? ""
  ).trim();

  const topic = String(
    question.Topic ?? ""
  ).trim();

  if (
    questionType &&
    !session.roundQuestionTypes.includes(
      questionType
    )
  ) {
    session.roundQuestionTypes.push(
      questionType
    );
  }

  if (
    topic &&
    !session.roundTopics.includes(
      topic
    )
  ) {
    session.roundTopics.push(topic);
  }

  session.currentQuestionId =
    questionId;
}

function selectRandomQuestion(level) {
  let candidates =
    questionBank.filter((row) => {
      const sameLanguage =
        normalizeLanguage(
          row.Interface_Language
        ) ===
        session.interfaceLanguage;

      const sameLevel =
        Number(row.Learning_Level) ===
        Number(level);

      const questionId = String(
        row.Question_ID
      ).trim();

      const sourceId = String(
        row.Source_ID ?? ""
      ).trim();

      const pairId = String(
        row.Pair_ID ?? ""
      ).trim();

      const questionUnused =
        !session.usedQuestionIds.includes(
          questionId
        );

      const sourceUnused =
        !sourceId ||
        !session.usedSourceIds.includes(
          sourceId
        );

      const pairUnused =
        !pairId ||
        !session.usedPairIds.includes(
          pairId
        );

      return (
        sameLanguage &&
        sameLevel &&
        questionUnused &&
        sourceUnused &&
        pairUnused
      );
    });

  // Fallback: prevent only exact question repetition.
  if (!candidates.length) {
    candidates =
      questionBank.filter((row) => {
        return (
          normalizeLanguage(
            row.Interface_Language
          ) ===
            session.interfaceLanguage &&
          Number(
            row.Learning_Level
          ) === Number(level) &&
          !session.usedQuestionIds.includes(
            String(
              row.Question_ID
            ).trim()
          )
        );
      });
  }

  if (!candidates.length) {
    throw new Error(
      `No unused questions are available for Level ${level} and language ${session.interfaceLanguage}.`
    );
  }

  const scoredCandidates =
    candidates.map((question) => {
      const questionType = String(
        question.Question_Type ?? ""
      ).trim();

      const topic = String(
        question.Topic ?? ""
      ).trim();

      let score = Math.random();

      if (
        questionType &&
        !session.roundQuestionTypes.includes(
          questionType
        )
      ) {
        score += 2;
      }

      if (
        topic &&
        !session.roundTopics.includes(
          topic
        )
      ) {
        score += 1;
      }

      return {
        question,
        score,
      };
    });

  scoredCandidates.sort(
    (first, second) =>
      second.score - first.score
  );

  return scoredCandidates[0].question;
}

/* ============================================================
   RESUME CURRENT QUESTION OR SELECT NEW QUESTION
============================================================ */

let selectedQuestion = null;

if (session.currentQuestionId) {
  selectedQuestion =
    questionBank.find((row) => {
      return (
        String(
          row.Question_ID
        ).trim() ===
          session.currentQuestionId &&
        normalizeLanguage(
          row.Interface_Language
        ) ===
          session.interfaceLanguage
      );
    });
}

if (!selectedQuestion) {
  selectedQuestion =
    selectRandomQuestion(
      session.currentLevel
    );

  registerQuestion(
    selectedQuestion
  );
}

/* ============================================================
   SESSION ROW FOR DATA TABLE
============================================================ */

const sessionRow = {
  session_id:
    session.sessionId,

  user_id:
    session.userId,

  email:
    session.email,

  interface_language:
    session.interfaceLanguage,

  status:
    session.status,

  current_level:
    session.currentLevel,

  highest_passed_level:
    session.highestPassedLevel,

  questions_answered:
    session.questionsAnswered,

  total_correct:
    session.totalCorrect,

  round_answered:
    session.roundAnswered,

  round_correct:
    session.roundCorrect,

  stable_rounds:
    session.stableRounds,

  current_question_id:
    session.currentQuestionId,

  used_question_ids:
    JSON.stringify(
      session.usedQuestionIds
    ),

  used_source_ids:
    JSON.stringify(
      session.usedSourceIds
    ),

  used_pair_ids:
    JSON.stringify(
      session.usedPairIds
    ),

  round_question_types:
    JSON.stringify(
      session.roundQuestionTypes
    ),

  round_topics:
    JSON.stringify(
      session.roundTopics
    ),

  final_level:
    session.finalLevel,

  finish_reason:
    session.finishReason,

  created_at:
    session.createdAt,

  updated_at:
    session.updatedAt,

  finished_at:
    session.finishedAt,
};

/* ============================================================
   RESPONSE FOR FRONTEND
============================================================ */

const response = {
  ok: true,
  finished: false,

  sessionId:
    session.sessionId,

  session_id:
    session.sessionId,

  placement_session_id:
    session.sessionId,

  email:
    session.email,

  interfaceLanguage:
    session.interfaceLanguage,

  test_language:
    session.interfaceLanguage,

  currentLevel:
    session.currentLevel,

  current_level:
    session.currentLevel,

  questionId:
    String(
      selectedQuestion.Question_ID
    ),

  question_id:
    String(
      selectedQuestion.Question_ID
    ),

  questionNumber:
    session.questionsAnswered + 1,

  question_number:
    session.questionsAnswered + 1,

  totalQuestions: 20,
  total_questions: 20,

  question:
    String(
      selectedQuestion.Question_Text
    ),

  options:
    makeOptions(
      selectedQuestion
    ),

  resumed:
    Boolean(existingSession),

  minLevel,
  maxLevel,
};

return [
  {
    json: {
      db_operation:
        dbOperation,

      session_row:
        sessionRow,

      response,
    },
  },
];

const body =
  $("Webhook1").first().json.body ?? {};

const sessionOutput =
  $("Get Session By ID").first().json ?? {};

// يدعم الحالتين: بيانات الجلسة مباشرة أو داخل session_row
const session =
  sessionOutput.session_row ?? sessionOutput;

const questionBank =
  $input.all().map((item) => item.json);

const QUESTIONS_PER_LEVEL = 2;
const MAX_LEVEL = 6;
const MAX_QUESTIONS =
  QUESTIONS_PER_LEVEL * MAX_LEVEL;

/* ============================================================
   Helpers
============================================================ */

function text(value) {
  return String(value ?? "").trim();
}

function number(value, fallback = 0) {
  const result = Number(value);

  return Number.isFinite(result)
    ? result
    : fallback;
}

function parseArray(value) {
  if (Array.isArray(value)) {
    return value;
  }

  if (
    value === null ||
    value === undefined ||
    value === ""
  ) {
    return [];
  }

  try {
    const parsed = JSON.parse(value);

    return Array.isArray(parsed)
      ? parsed
      : [];
  } catch {
    return [];
  }
}

function normalize(value) {
  return text(value).toLowerCase();
}

function normalizeLanguage(value) {
  return normalize(value) === "english"
    ? "English"
    : "MSA";
}

function getQuestionId(row) {
  return text(row.Question_ID);
}

function getQuestionLevel(row) {
  return number(
    row.Learning_Level,
    1
  );
}

function getQuestionLanguage(row) {
  return normalizeLanguage(
    row.Interface_Language
  );
}

function buildOptions(row) {
  return ["A", "B", "C", "D"]
    .map((letter) => ({
      value: letter,

      label: text(
        row[`Option_${letter}`]
      ),
    }))
    .filter(
      (option) => option.label
    );
}

function getCorrectValues(row) {
  const correctOption =
    text(
      row.Correct_Option
    ).toUpperCase();

  const correctAnswer =
    text(row.Correct_Answer);

  const values = [
    correctOption,
    correctAnswer,
  ];

  if (
    ["A", "B", "C", "D"].includes(
      correctOption
    )
  ) {
    values.push(
      text(
        row[
          `Option_${correctOption}`
        ]
      )
    );
  }

  return values
    .map(normalize)
    .filter(Boolean);
}

function chooseRandom(items) {
  if (!items.length) {
    return null;
  }

  const index =
    Math.floor(
      Math.random() * items.length
    );

  return items[index];
}

/* ============================================================
   Select next question
============================================================ */

function selectQuestion({
  level,
  language,
  usedQuestionIds,
  usedSourceIds,
  usedPairIds,
  avoidTypes = [],
  avoidTopics = [],
}) {
  /*
    أول فلتر:
    - نفس المستوى
    - نفس لغة الاختبار
    - السؤال غير مستخدم
  */
  const basePool =
    questionBank.filter((row) => {
      const questionId =
        getQuestionId(row);

      return (
        getQuestionLevel(row) ===
          level &&
        getQuestionLanguage(row) ===
          language &&
        questionId &&
        !usedQuestionIds.includes(
          questionId
        )
      );
    });

  /*
    نحاول أيضًا عدم تكرار:
    Source_ID
    Pair_ID
    Question_Type
    Topic
  */
  let pool =
    basePool.filter((row) => {
      const sourceId =
        text(row.Source_ID);

      const pairId =
        text(row.Pair_ID);

      const questionType =
        text(row.Question_Type);

      const topic =
        text(row.Topic);

      const sourceAllowed =
        !sourceId ||
        !usedSourceIds.includes(
          sourceId
        );

      const pairAllowed =
        !pairId ||
        !usedPairIds.includes(
          pairId
        );

      const typeAllowed =
        !questionType ||
        !avoidTypes.includes(
          questionType
        );

      const topicAllowed =
        !topic ||
        !avoidTopics.includes(
          topic
        );

      return (
        sourceAllowed &&
        pairAllowed &&
        typeAllowed &&
        topicAllowed
      );
    });

  /*
    لو ما لقينا سؤالًا، نسمح بتكرار
    النوع أو الموضوع، لكن لا نكرر
    Source_ID أو Pair_ID.
  */
  if (!pool.length) {
    pool =
      basePool.filter((row) => {
        const sourceId =
          text(row.Source_ID);

        const pairId =
          text(row.Pair_ID);

        const sourceAllowed =
          !sourceId ||
          !usedSourceIds.includes(
            sourceId
          );

        const pairAllowed =
          !pairId ||
          !usedPairIds.includes(
            pairId
          );

        return (
          sourceAllowed &&
          pairAllowed
        );
      });
  }

  /*
    آخر حل:
    أي سؤال غير مستخدم من نفس
    المستوى واللغة.
  */
  if (!pool.length) {
    pool = basePool;
  }

  const selected =
    chooseRandom(pool);

  if (!selected) {
    throw new Error(
      `No unused question found for Level ${level} and language ${language}.`
    );
  }

  return selected;
}

/* ============================================================
   Resolve session
============================================================ */

const resolvedSessionId =
  text(
    session.session_id ||
      body.placement_session_id ||
      body.session_id
  );

if (!resolvedSessionId) {
  throw new Error(
    "Placement session ID is missing."
  );
}

const interfaceLanguage =
  normalizeLanguage(
    session.interface_language ||
      body.test_language ||
      body.interface_language
  );

/* ============================================================
   Current stored state
============================================================ */

const originalLevel =
  Math.max(
    1,
    number(
      session.current_level,
      1
    )
  );

let currentLevel =
  originalLevel;

let highestPassedLevel =
  Math.max(
    0,
    number(
      session.highest_passed_level,
      0
    )
  );

let questionsAnswered =
  number(
    session.questions_answered,
    0
  ) + 1;

let totalCorrect =
  number(
    session.total_correct,
    0
  );

let roundAnswered =
  number(
    session.round_answered,
    0
  ) + 1;

let roundCorrect =
  number(
    session.round_correct,
    0
  );

let roundQuestionTypes =
  parseArray(
    session.round_question_types
  );

let roundTopics =
  parseArray(
    session.round_topics
  );

const usedQuestionIds =
  parseArray(
    session.used_question_ids
  );

const usedSourceIds =
  parseArray(
    session.used_source_ids
  );

const usedPairIds =
  parseArray(
    session.used_pair_ids
  );

/* ============================================================
   Find answered question
============================================================ */

const currentQuestionId =
  text(
    body.question_id ||
      session.current_question_id
  );

if (!currentQuestionId) {
  throw new Error(
    "Current question ID is missing."
  );
}

const currentQuestion =
  questionBank.find(
    (row) =>
      getQuestionId(row) ===
      currentQuestionId
  );

if (!currentQuestion) {
  throw new Error(
    `Question ${currentQuestionId} was not found in the question bank.`
  );
}

/* ============================================================
   Check answer
============================================================ */

const selectedAnswer =
  text(
    body.answer ||
      body.selected_option ||
      body.selected_answer
  );

if (!selectedAnswer) {
  throw new Error(
    "Selected answer is missing."
  );
}

const correctValues =
  getCorrectValues(
    currentQuestion
  );

const isCorrect =
  correctValues.includes(
    normalize(selectedAnswer)
  );

if (isCorrect) {
  totalCorrect += 1;
  roundCorrect += 1;
}

/* ============================================================
   Mark current question as used
============================================================ */

const sourceId =
  text(
    currentQuestion.Source_ID
  );

const pairId =
  text(
    currentQuestion.Pair_ID
  );

const questionType =
  text(
    currentQuestion.Question_Type
  );

const topic =
  text(
    currentQuestion.Topic
  );

if (
  !usedQuestionIds.includes(
    currentQuestionId
  )
) {
  usedQuestionIds.push(
    currentQuestionId
  );
}

if (
  sourceId &&
  !usedSourceIds.includes(
    sourceId
  )
) {
  usedSourceIds.push(
    sourceId
  );
}

if (
  pairId &&
  !usedPairIds.includes(
    pairId
  )
) {
  usedPairIds.push(
    pairId
  );
}

if (
  questionType &&
  !roundQuestionTypes.includes(
    questionType
  )
) {
  roundQuestionTypes.push(
    questionType
  );
}

if (
  topic &&
  !roundTopics.includes(topic)
) {
  roundTopics.push(topic);
}

/* ============================================================
   Adaptive placement logic
============================================================ */

let finished = false;
let finalLevel = 0;
let finishReason = "";
let nextQuestion = null;

/*
  بعد السؤال الأول:
  نختار السؤال الثاني من نفس المستوى.
*/
if (
  roundAnswered <
  QUESTIONS_PER_LEVEL
) {
  nextQuestion =
    selectQuestion({
      level:
        currentLevel,

      language:
        interfaceLanguage,

      usedQuestionIds,
      usedSourceIds,
      usedPairIds,

      avoidTypes:
        roundQuestionTypes,

      avoidTopics:
        roundTopics,
    });
}

/*
  بعد السؤالين:
  2/2 صح = ينتقل للمستوى التالي.
*/
else if (
  roundCorrect ===
  QUESTIONS_PER_LEVEL
) {
  highestPassedLevel =
    Math.max(
      highestPassedLevel,
      currentLevel
    );

  /*
    نجح بالمستوى السادس:
    ينتهي الاختبار.
  */
  if (
    currentLevel >= MAX_LEVEL
  ) {
    finished = true;

    finalLevel =
      MAX_LEVEL;

    finishReason =
      "completed_all_levels";
  } else {
    /*
      الانتقال إلى المستوى التالي.
    */
    currentLevel += 1;

    roundAnswered = 0;
    roundCorrect = 0;

    roundQuestionTypes = [];
    roundTopics = [];

    nextQuestion =
      selectQuestion({
        level:
          currentLevel,

        language:
          interfaceLanguage,

        usedQuestionIds,
        usedSourceIds,
        usedPairIds,
      });
  }
}

/*
  بعد السؤالين:
  0/2 أو 1/2 = ينتهي الاختبار.
*/
else {
  finished = true;

  /*
    إذا لم ينجح حتى بالمستوى الأول،
    يبقى مستوى المستخدم Level 1.
  */
  finalLevel =
    Math.max(
      1,
      highestPassedLevel
    );

  finishReason =
    `did_not_pass_level_${originalLevel}`;
}

/* ============================================================
   Build answer row
============================================================ */

const now =
  new Date().toISOString();

const randomPart =
  globalThis.crypto &&
  typeof globalThis.crypto.randomUUID ===
    "function"
    ? globalThis.crypto.randomUUID()
    : `${Date.now()}-${Math.random()
        .toString(16)
        .slice(2)}`;

const answerRow = {
  answer_id:
    `answer-${randomPart}`,

  session_id:
    resolvedSessionId,

  user_id:
    text(
      session.user_id ||
        body.user_id
    ),

  email:
    text(
      session.email ||
        body.email
    ).toLowerCase(),

  question_id:
    currentQuestionId,

  interface_language:
    interfaceLanguage,

  level:
    originalLevel,

  question_number:
    questionsAnswered,

  selected_answer:
    selectedAnswer,

  correct_answer:
    text(
      currentQuestion.Correct_Option ||
        currentQuestion.Correct_Answer
    ),

  is_correct:
    isCorrect,

  answered_at:
    now,
};

/* ============================================================
   Build updated session row
============================================================ */

const sessionRow = {
  session_id:
    resolvedSessionId,

  user_id:
    text(
      session.user_id ||
        body.user_id
    ),

  email:
    text(
      session.email ||
        body.email
    ).toLowerCase(),

  interface_language:
    interfaceLanguage,

  status:
    finished
      ? "finished"
      : "in_progress",

  current_level:
    currentLevel,

  highest_passed_level:
    highestPassedLevel,

  questions_answered:
    questionsAnswered,

  total_correct:
    totalCorrect,

  round_answered:
    roundAnswered,

  round_correct:
    roundCorrect,

  stable_rounds:
    0,

  current_question_id:
    finished
      ? ""
      : getQuestionId(
          nextQuestion
        ),

  used_question_ids:
    JSON.stringify(
      usedQuestionIds
    ),

  used_source_ids:
    JSON.stringify(
      usedSourceIds
    ),

  used_pair_ids:
    JSON.stringify(
      usedPairIds
    ),

  round_question_types:
    JSON.stringify(
      roundQuestionTypes
    ),

  round_topics:
    JSON.stringify(
      roundTopics
    ),

  final_level:
    finished
      ? finalLevel
      : 0,

  finish_reason:
    finishReason,

  created_at:
    text(
      session.created_at
    ) || now,

  updated_at:
    now,

  finished_at:
    finished
      ? now
      : "",
};

/* ============================================================
   Build frontend response
============================================================ */

let response;

if (finished) {
  response = {
    finished: true,

    sessionId:
      resolvedSessionId,

    session_id:
      resolvedSessionId,

    placement_session_id:
      resolvedSessionId,

    level:
      finalLevel,

    placement_level:
      finalLevel,

    score:
      totalCorrect,

    questionNumber:
      questionsAnswered,

    question_number:
      questionsAnswered,

    totalQuestions:
      MAX_QUESTIONS,

    total_questions:
      MAX_QUESTIONS,

    finish_reason:
      finishReason,
  };
} else {
  const nextQuestionId =
    getQuestionId(
      nextQuestion
    );

  response = {
    finished: false,

    sessionId:
      resolvedSessionId,

    session_id:
      resolvedSessionId,

    placement_session_id:
      resolvedSessionId,

    questionId:
      nextQuestionId,

    question_id:
      nextQuestionId,

    questionNumber:
      questionsAnswered + 1,

    question_number:
      questionsAnswered + 1,

    totalQuestions:
      MAX_QUESTIONS,

    total_questions:
      MAX_QUESTIONS,

    question:
      text(
        nextQuestion.Question_Text
      ),

    options:
      buildOptions(
        nextQuestion
      ),

    level:
      currentLevel,

    current_level:
      currentLevel,

    interface_language:
      interfaceLanguage,

    test_language:
      interfaceLanguage,
  };
}

/* ============================================================
   Output
============================================================ */

return [
  {
    json: {
      answer_row:
        answerRow,

      session_row:
        sessionRow,

      response,

      finished,

      is_correct:
        isCorrect,
    },
  },
];

