parameters.jsCode:
/*
  Prepare learning start

  المسؤوليات:
  - قراءة قرار الـAgent
  - قراءة نتائج Chroma
  - فلترة النتائج حسب current_level فقط
  - استخدام current_micro_level كمرحلة داخل التطبيق فقط
  - استبعاد العناصر المستخدمة
  - إنهاء العنصر السابق عند الانتقال لعنصر جديد
  - تحديث progress
  - تجهيز العنصر الجديد
  - عند إكمال 20/20 تجهيز امتحان المستوى الفرعي
*/


/* =========================
   Read Nodes
========================= */

const context =
  $("Build Agent Context").first().json ?? {};

const decision =
  $("Validate Agent Decision").first().json ?? {};

const chromaItems =
  $input.all();

const session = {
  ...(context.session_row ?? {}),
};


/* =========================
   Helpers
========================= */

function toText(value, fallback = "") {
  if (
    value === null ||
    value === undefined
  ) {
    return fallback;
  }

  const result =
    String(value).trim();

  return result || fallback;
}


function toNumber(value, fallback = 0) {
  const result =
    Number(value);

  return Number.isFinite(result)
    ? result
    : fallback;
}


function toBoolean(value, fallback = false) {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value === "number") {
    return value === 1;
  }

  const normalized =
    toText(value)
      .toLowerCase();

  if (
    [
      "true",
      "1",
      "yes",
    ].includes(normalized)
  ) {
    return true;
  }

  if (
    [
      "false",
      "0",
      "no",
    ].includes(normalized)
  ) {
    return false;
  }

  return fallback;
}


function parseList(value) {
  if (Array.isArray(value)) {
    return [
      ...new Set(
        value
          .map((item) => toText(item))
          .filter(Boolean)
      ),
    ];
  }

  const raw =
    toText(value);

  if (
    !raw ||
    raw.toLowerCase() === "null"
  ) {
    return [];
  }

  try {
    const parsed =
      JSON.parse(raw);

    if (Array.isArray(parsed)) {
      return [
        ...new Set(
          parsed
            .map((item) => toText(item))
            .filter(Boolean)
        ),
      ];
    }
  } catch {
    // نحاول الفصل بالفواصل.
  }

  return [
    ...new Set(
      raw
        .split(",")
        .map((item) => item.trim())
        .filter(Boolean)
    ),
  ];
}


function escapeRegex(value) {
  return String(value).replace(
    /[.*+?^${}()|[\]\\]/g,
    "\\$&"
  );
}


function readValueFromContent(
  content,
  labels
) {
  const source =
    toText(content);

  if (!source) {
    return "";
  }

  for (const label of labels) {
    const escapedLabel =
      escapeRegex(label);

    const pattern =
      new RegExp(
        `(?:^|\\n)\\s*${escapedLabel}\\s*[:：-]\\s*(.+?)(?=\\n|$)`,
        "i"
      );

    const match =
      source.match(pattern);

    if (match) {
      return toText(
        match[1]
      );
    }
  }

  return "";
}


/* =========================
   Current Learning State
========================= */

const preferredLanguage =
  toText(
    context.preferred_language,
    "MSA"
  );

const isEnglish =
  preferredLanguage
    .toLowerCase() === "english";


const currentLevel =
  Math.max(
    1,
    toNumber(
      context.current_level ??
      session.current_level,
      1
    )
  );


/*
  هذا هو Stage داخل التطبيق فقط.

  لا نستخدمه لفلترة Chroma،
  لأن micro levels داخل dataset
  لا تطابق تقسيم التطبيق 1–4.
*/
const currentMicroLevel =
  Math.max(
    1,
    toNumber(
      context.current_micro_level ??
      session.current_micro_level,
      1
    )
  );


const previousStep =
  toText(
    session.current_step
  );


const action =
  toText(
    decision.action,
    "teach_new"
  );


const reasonCode =
  toText(
    decision.reason_code,
    "continue_learning"
  );


/* =========================
   Progress
========================= */

let wordsCompleted =
  Math.max(
    0,
    toNumber(
      session.words_completed,
      0
    )
  );


const wordsTotal =
  Math.max(
    1,
    toNumber(
      session.words_total,
      20
    )
  );


let completedItemIds =
  parseList(
    session.completed_item_ids
  );


let difficultItemIds =
  parseList(
    session.difficult_item_ids
  );


let usedItemIds =
  parseList(
    session.used_item_ids ??
    session.seen_item_ids
  );


/* =========================
   Complete Previous Item
========================= */

/*
  نعتبر العنصر السابق مكتملًا فقط عندما:
  - كان المستخدم فعليًا في teach
  - والـAgent قرر الانتقال لعنصر جديد
*/

const previousItemId =
  toText(
    session.current_item_id
  );


const shouldCompletePrevious =
  previousStep === "teach" &&
  [
    "teach_new",
    "move_harder",
  ].includes(action) &&
  Boolean(previousItemId);


if (shouldCompletePrevious) {
  if (
    !completedItemIds.includes(
      previousItemId
    )
  ) {
    completedItemIds.push(
      previousItemId
    );

    wordsCompleted += 1;
  }

  if (
    !usedItemIds.includes(
      previousItemId
    )
  ) {
    usedItemIds.push(
      previousItemId
    );
  }
}


/* =========================
   Check Micro-Level Completion
========================= */

/*
  كل Stage داخل التطبيق يحتوي 20 عنصرًا.
*/

const microLevelCompleted =
  wordsCompleted >=
  wordsTotal;


const now =
  new Date().toISOString();


/* =========================
   Quiz Ready
========================= */

if (microLevelCompleted) {
  const quizReply =
    isEnglish
      ? (
          `Excellent work! You completed all ${wordsTotal} learning items ` +
          `in Learning Level ${currentLevel}, Stage ${currentMicroLevel}. ` +
          `You are now ready for the micro-level quiz.`
        )
      : (
          `أحسنت! أكملت ${wordsTotal} من ${wordsTotal} عبارة ` +
          `في المستوى الرئيسي ${currentLevel}، ` +
          `المرحلة ${currentMicroLevel}. ` +
          `أصبحت الآن جاهزًا لامتحان المستوى الفرعي.`
        );


  const updatedSession = {
    ...session,

    current_level:
      currentLevel,

    current_micro_level:
      currentMicroLevel,

    words_completed:
      wordsTotal,

    completed_item_ids:
      JSON.stringify(
        completedItemIds
      ),

    difficult_item_ids:
      JSON.stringify(
        difficultItemIds
      ),

    used_item_ids:
      JSON.stringify(
        usedItemIds
      ),

    current_step:
      "quiz_ready",

    review_active:
      false,

    review_recommended:
      false,

    last_agent_action:
      "level_quiz_ready",

    last_agent_reason:
      "micro_level_learning_completed",

    updated_at:
      now,

    last_activity_at:
      now,
  };


  return [
    {
      json: {
        session_row:
          updatedSession,

        response: {
          success:
            true,

          mode:
            "learning",

          action:
            "level_quiz_ready",

          reply:
            quizReply,

          suggested_actions:
            [],

          level_quiz_ready:
            true,

          micro_level_quiz_ready:
            true,

          current_level:
            currentLevel,

          current_micro_level:
            currentMicroLevel,

          words_completed:
            wordsTotal,

          words_total:
            wordsTotal,

          words_remaining:
            0,

          preferred_language:
            preferredLanguage,

          learning_session_id:
            toText(
              session.learning_session_id
            ),
        },
      },
    },
  ];
}


/* =========================
   Convert Chroma Results
========================= */

function candidate(inputItem) {
  const raw =
    inputItem?.json ??
    inputItem ??
    {};

  const document =
    raw.document ??
    {};

  const metadata =
    document.metadata ??
    raw.metadata ??
    {};


  const pageContent =
    toText(
      document.pageContent ??
      document.content ??
      raw.pageContent ??
      raw.content ??
      raw.text
    );


  /*
    ver6 يحتوي original_id.
  */
  const itemId =
    toText(
      metadata.item_id ??
      metadata.original_id ??
      metadata.source_id ??
      raw.item_id ??
      raw.original_id ??
      raw.id
    );


  const sourceId =
    toText(
      metadata.source_id ??
      metadata.original_id ??
      metadata.item_id,
      itemId
    );


  const stageFromContent =
    readValueFromContent(
      pageContent,
      [
        "المستوى",
        "Learning Level",
        "Level",
      ]
    );


  const stage =
    Math.max(
      1,
      toNumber(
        metadata.stage ??
        metadata.learning_level ??
        stageFromContent,
        1
      )
    );


  /*
    نقرأ Dataset Micro Level لأغراض debug فقط.

    لا نستخدمه في اختيار العنصر،
    لأن تقسيم dataset micro levels
    لا يطابق Stage 1–4 في التطبيق.
  */
  const datasetMicroLevelFromContent =
    readValueFromContent(
      pageContent,
      [
        "المستوى الفرعي",
        "Micro Level",
        "micro_level",
      ]
    );


  const datasetMicroLevel =
    Math.max(
      1,
      toNumber(
        metadata.micro_level ??
        metadata.microLevel ??
        metadata.micro ??
        datasetMicroLevelFromContent,
        1
      )
    );


  const msa =
    toText(
      metadata.msa ??
      readValueFromContent(
        pageContent,
        [
          "الفصحى",
          "MSA",
          "Modern Standard Arabic",
        ]
      )
    );


  const levantine =
    toText(
      metadata.levantine ??
      readValueFromContent(
        pageContent,
        [
          "الشامية",
          "Levantine",
          "Levantine Arabic",
        ]
      )
    );


  const english =
    toText(
      metadata.english ??
      readValueFromContent(
        pageContent,
        [
          "الإنجليزية",
          "English",
        ]
      )
    );


  const topic =
    toText(
      metadata.topic ??
      readValueFromContent(
        pageContent,
        [
          "الموضوع",
          "Topic",
        ]
      )
    );


  return {
    itemId,
    sourceId,

    stage,

    /*
      هذه قيمة dataset فقط.
    */
    datasetMicroLevel,

    msa,

    levantine,

    english,

    topic,

    score:
      toNumber(
        raw.score,
        999
      ),

    metadata,

    pageContent,
  };
}


/* =========================
   Parse All Chroma Items
========================= */

const allCandidates =
  chromaItems
    .map(candidate)
    .filter(
      (item) =>
        item.itemId &&
        item.levantine
    );


/* =========================
   Filter Main Learning Level
========================= */

/*
  مهم جدًا:

  نفلتر حسب المستوى الرئيسي فقط.

  Stage داخل التطبيق:
    currentMicroLevel = 1..4

  لكنه لا يساوي micro_level
  الموجود داخل dataset.

  الـ20 عنصر لكل Stage يتم تحديدهم
  من خلال used/completed IDs وليس
  من خلال dataset micro_level.
*/

const correctLevelCandidates =
  allCandidates.filter(
    (item) =>
      item.stage ===
      currentLevel
  );


/* =========================
   Remove Used Items
========================= */

const alreadyUsedIds =
  new Set([
    ...usedItemIds,
    ...completedItemIds,
  ]);


const unusedCandidates =
  correctLevelCandidates.filter(
    (item) =>
      !alreadyUsedIds.has(
        item.itemId
      )
  );


/* =========================
   Select Item
========================= */

/*
  Chroma يرجع النتائج مرتبة حسب similarity.
  نأخذ أول عنصر غير مستخدم
  من نفس المستوى الرئيسي.
*/

const selectedItem =
  unusedCandidates[0] ??
  null;


/* =========================
   No Valid Item
========================= */

if (!selectedItem) {
  throw new Error(
    `لم يتم العثور على عنصر جديد غير مستخدم في Learning Level ${currentLevel}. ` +
    `App Stage: ${currentMicroLevel}. ` +
    `Chroma returned ${allCandidates.length} items, ` +
    `${correctLevelCandidates.length} matched Learning Level ${currentLevel}, ` +
    `and ${unusedCandidates.length} were unused.`
  );
}


/* =========================
   Mark Selected Item Used
========================= */

if (
  !usedItemIds.includes(
    selectedItem.itemId
  )
) {
  usedItemIds.push(
    selectedItem.itemId
  );
}


/* =========================
   Adaptation Counters
========================= */

let consecutiveUnderstood =
  Math.max(
    0,
    toNumber(
      session.consecutive_understood,
      0
    )
  );


let confusionCount =
  Math.max(
    0,
    toNumber(
      session.confusion_count,
      0
    )
  );


let exampleCount =
  Math.max(
    0,
    toNumber(
      session.example_count,
      0
    )
  );


if (
  [
    "teach_new",
    "move_harder",
  ].includes(action)
) {
  consecutiveUnderstood += 1;

  confusionCount = 0;

  exampleCount = 0;
}


/* =========================
   Update Session
========================= */

const updatedSession = {
  ...session,

  current_level:
    currentLevel,

  /*
    App Stage يبقى كما هو.
  */
  current_micro_level:
    currentMicroLevel,

  current_item_id:
    selectedItem.itemId,

  current_source_id:
    selectedItem.sourceId,

  current_levantine:
    selectedItem.levantine,

  current_msa:
    selectedItem.msa,

  current_english:
    selectedItem.english,

  current_topic:
    selectedItem.topic,

  words_completed:
    wordsCompleted,

  words_total:
    wordsTotal,

  completed_item_ids:
    JSON.stringify(
      completedItemIds
    ),

  difficult_item_ids:
    JSON.stringify(
      difficultItemIds
    ),

  used_item_ids:
    JSON.stringify(
      usedItemIds
    ),

  consecutive_understood:
    consecutiveUnderstood,

  confusion_count:
    confusionCount,

  example_count:
    exampleCount,

  current_step:
    "teach",

  review_active:
    false,

  review_recommended:
    false,

  last_agent_action:
    action,

  last_agent_reason:
    reasonCode,

  updated_at:
    now,

  last_activity_at:
    now,
};


/* =========================
   Suggested Actions
========================= */

const suggestedActions =
  isEnglish
    ? [
        "Got it",
        "I don't understand",
        "Give me an example",
        "I want to review",
      ]
    : [
        "فهمت",
        "لم أفهم",
        "أعطني مثالًا",
        "أريد المراجعة",
      ];


/* =========================
   Base Response
========================= */

const response = {
  success:
    true,

  mode:
    "learning",

  action:
    "teach",

  reply:
    "",

  suggested_actions:
    suggestedActions,

  current_level:
    currentLevel,

  current_micro_level:
    currentMicroLevel,

  words_completed:
    wordsCompleted,

  words_total:
    wordsTotal,

  words_remaining:
    Math.max(
      0,
      wordsTotal -
      wordsCompleted
    ),

  current_item_id:
    selectedItem.itemId,

  preferred_language:
    preferredLanguage,

  learning_session_id:
    toText(
      session.learning_session_id
    ),
};


/* =========================
   Debug Information
========================= */

const debug = {
  chroma_returned:
    allCandidates.length,

  correct_learning_level_candidates:
    correctLevelCandidates.length,

  unused_candidates:
    unusedCandidates.length,

  app_stage:
    currentMicroLevel,

  selected_stage:
    selectedItem.stage,

  selected_dataset_micro_level:
    selectedItem.datasetMicroLevel,

  selected_item_id:
    selectedItem.itemId,
};


/* =========================
   Output
========================= */

return [
  {
    json: {
      session_row:
        updatedSession,

      response,

      selected_item: {
        item_id:
          selectedItem.itemId,

        source_id:
          selectedItem.sourceId,

        levantine:
          selectedItem.levantine,

        msa:
          selectedItem.msa,

        english:
          isEnglish
            ? selectedItem.english
            : "",

        topic:
          selectedItem.topic,

        learning_level:
          selectedItem.stage,

        /*
          هذا Stage التطبيق،
          مش dataset micro level.
        */
        micro_level:
          currentMicroLevel,

        dataset_micro_level:
          selectedItem.datasetMicroLevel,
      },

      debug,
    },
  },
];

const body =
  $("Webhook1").first().json.body ?? {};

const agentResult =
  $input.first().json ?? {};


/* =========================
   Helpers
========================= */

function text(value) {
  return value === null || value === undefined
    ? ""
    : String(value).trim();
}


/* =========================
   User Language
========================= */

const preferredLanguage = text(
  body.preferred_language ??
  body.interface_language ??
  "MSA"
);

const isEnglishInterface =
  preferredLanguage
    .toLowerCase() === "english";

const userMessage = text(
  body.message ??
  body.question ??
  ""
);


/* =========================
   Explicit English Request
========================= */

const explicitlyRequestedEnglish =
  /(?:بالإنجليزية|إلى الإنجليزية|للإنجليزية|ترجمة إنجليزية|english|in english|to english)/i
    .test(userMessage);


/* =========================
   Agent Answer
========================= */

let answer = text(
  agentResult.output ??
  agentResult.reply ??
  agentResult.answer ??
  agentResult.text ??
  agentResult.message
);


/* =========================
   Detect Model Fallback
========================= */

const fallbackMarker =
  "[[FALLBACK]]";

const usedModelFallback =
  answer.includes(
    fallbackMarker
  );


/*
  نحذف العلامة الداخلية قبل إرسال الرد للمستخدم.
*/
answer = answer
  .replace(
    /\[\[FALLBACK\]\]/g,
    ""
  )
  .trim();


/* =========================
   MSA Language Protection
========================= */

if (
  !isEnglishInterface &&
  !explicitlyRequestedEnglish
) {
  /*
