/* =========================
   Helpers
========================= */

function toText(value, fallback = "") {
  if (
    value === null ||
    value === undefined
  ) {
    return fallback;
  }

  if (Array.isArray(value)) {
    const firstValidValue =
      value.find(
        (item) =>
          item !== null &&
          item !== undefined &&
          String(item).trim()
      );

    return firstValidValue === undefined
      ? fallback
      : String(firstValidValue).trim();
  }

  const result =
    String(value).trim();

  return result || fallback;
}

function toNumber(value, fallback = 0) {
  const result =
    Number(value);

  return Number.isFinite(result)
    ? result
    : fallback;
}

function toBoolean(value, fallback = false) {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value === "number") {
    return value === 1;
  }

  const normalized =
    toText(value)
      .toLowerCase();

  if (
    [
      "true",
      "1",
      "yes",
      "on",
    ].includes(normalized)
  ) {
    return true;
  }

  if (
    [
      "false",
      "0",
      "no",
      "off",
      "",
    ].includes(normalized)
  ) {
    return false;
  }

  return fallback;
}

function parseList(value) {
  if (Array.isArray(value)) {
    return [
      ...new Set(
        value
          .map((item) => toText(item))
          .filter(Boolean)
      ),
    ];
  }

  const raw =
    toText(value);

  if (
    !raw ||
    raw.toLowerCase() === "null"
  ) {
    return [];
  }

  try {
    const parsed =
      JSON.parse(raw);

    if (Array.isArray(parsed)) {
      return [
        ...new Set(
          parsed
            .map((item) => toText(item))
            .filter(Boolean)
        ),
      ];
    }
  } catch {
    // نحاول فصل القيمة بالفواصل.
  }

  return [
    ...new Set(
      raw
        .split(",")
        .map((item) => item.trim())
        .filter(Boolean)
    ),
  ];
}

function firstRow(value) {
  if (!value) {
    return {};
  }

  if (Array.isArray(value)) {
    return value[0] ?? {};
  }

  if (
    Array.isArray(value.data)
  ) {
    return value.data[0] ?? {};
  }

  if (
    value.data &&
    typeof value.data === "object"
  ) {
    return value.data;
  }

  if (
    Array.isArray(value.rows)
  ) {
    return value.rows[0] ?? {};
  }

  if (
    value.row &&
    typeof value.row === "object"
  ) {
    return value.row;
  }

  if (
    value.result &&
    typeof value.result === "object"
  ) {
    return firstRow(
      value.result
    );
  }

  if (typeof value === "object") {
    return value;
  }

  return {};
}


