========================= */

function toText(value, fallback = "") {
  if (
    value === null ||
    value === undefined
  ) {
    return fallback;
  }

  const result =
    String(value).trim();

  return result || fallback;
}


function normalizeArabic(value) {
  return toText(value)
    .toLowerCase()
    .replace(/[ًٌٍَُِّْـ]/g, "")
    .replace(/[أإآ]/g, "ا")
    .replace(/ى/g, "ي")
    .replace(/ة/g, "ه")
    .replace(/[؟?!.,،؛:]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}


function parseAgentOutput(input) {
  let raw =
    input?.output ??
    input?.text ??
    input?.response ??
    input;

  if (
    raw &&
    typeof raw === "object" &&
    !Array.isArray(raw)
  ) {
    /*
      بعض الـAgent nodes ترجع:
      { output: "{...}" }

      وبعضها ممكن ترجع JSON مباشرة.
    */
    if (
      raw.action ||
      raw.reason_code
    ) {
      return {
        parsed: raw,
        raw:
          JSON.stringify(raw),
      };
    }
  }

  raw =
    toText(raw);

  if (!raw) {
    return {
      parsed: {},
      raw: "",
    };
  }

  let cleaned =
    raw
      .replace(/^```json\s*/i, "")
      .replace(/^```\s*/i, "")
      .replace(/```$/i, "")
      .trim();

  try {
    return {
      parsed:
        JSON.parse(cleaned),

      raw,
    };
  } catch {
    // محاولة استخراج JSON من النص.
  }

  const firstBrace =
    cleaned.indexOf("{");

  const lastBrace =
    cleaned.lastIndexOf("}");

  if (
    firstBrace !== -1 &&
    lastBrace !== -1 &&
    lastBrace > firstBrace
  ) {
    try {
      return {
        parsed:
          JSON.parse(
            cleaned.slice(
              firstBrace,
              lastBrace + 1
            )
          ),

        raw,
      };
    } catch {
      // fallback تحت.
    }
  }

  return {
    parsed: {},
    raw,
  };
}


