  "عيد",
  "كرر",
  "كررها",
  "مرة ثانية",
  "مره ثانيه",
  "أعد العبارة",
  "اعد العباره",
];


const repeatEnglish = [
  "repeat",
  "say it again",
  "again please",
  "repeat the phrase",
  "repeat the word",
];


const understoodArabic = [
  "فهمت",
  "واضح",
  "صار واضح",
  "تمام فهمت",
  "اوكي فهمت",
  "أوكي فهمت",
];


const understoodEnglish = [
  "got it",
  "i understand",
  "understood",
  "makes sense",
  "clear",
  "okay got it",
];


const dontKnowArabic = [
  "لا أعلم",
  "لا اعلم",
  "لا أعرف",
  "لا اعرف",
  "ما بعرف",
  "ما أعرف",
  "ما اعرف",
  "مش عارف",
  "مش عارفة",
  "لا أدري",
  "لا ادري",
];


const dontKnowEnglish = [
  "i don't know",
  "i dont know",
  "don't know",
  "dont know",
  "not sure",
  "i'm not sure",
  "im not sure",
];


/* =========================
   Determine Override
========================= */

let overrideAction = "";
let overrideReason = "";


/*
  0. Final assessment

  أي طلب واضح من المستخدم لإنهاء التعلم
  يبدأ الـPost-Test مباشرة.

  لا نشترط currentStep === "learning_completed"
  لأن المستخدم يمكنه إنهاء التعلم بنفسه.
*/

if (
  matchesArabic(
    finishLearningArabic
  ) ||
  containsArabic(
    finishLearningArabic
  ) ||
  matchesEnglish(
    finishLearningEnglish
  ) ||
  containsEnglish(
    finishLearningEnglish
  )
) {
  overrideAction =
    "finish_learning";

  overrideReason =
    "learner_requested_final_post_test";
}


/*
  1. Retry quiz
  أعلى أولوية لأنه لازم ما يتحول لـteach_new.
*/

else if (
  matchesArabic(
    retryQuizArabic
  ) ||
  containsArabic(
    retryQuizArabic
  ) ||
  matchesEnglish(
    retryQuizEnglish
  ) ||
  containsEnglish(
    retryQuizEnglish
  )
) {
  overrideAction =
    "retry_quiz";

  overrideReason =
    "learner_requested_quiz_retry";
}


/*
  2. Continue review
*/

else if (
  matchesArabic(
    reviewArabic
  ) ||
  matchesEnglish(
    reviewEnglish
  )
) {
  overrideAction =
    "review_difficult";

  overrideReason =
    "learner_requested_review";
}


/*
  3. Continue learning
*/

else if (
  matchesArabic(
    continueLearningArabic
  ) ||
  matchesEnglish(
    continueLearningEnglish
  )
) {
  overrideAction =
    "teach_new";

  overrideReason =
    "learner_requested_continue_learning";
}


/*
  4. Example
*/

else if (
  matchesArabic(
    exampleArabic
  ) ||
  matchesEnglish(
    exampleEnglish
  )
) {
  overrideAction =
    "give_example";

  overrideReason =
    "learner_requested_example";
}


/*
  5. Repeat
*/

else if (
  matchesArabic(
    repeatArabic
  ) ||
  matchesEnglish(
    repeatEnglish
  )
) {
  overrideAction =
    "repeat_current";

  overrideReason =
    "learner_requested_repeat";
}


/*
  6. Confusion
*/

else if (
  containsArabic(
    confusedArabic
  ) ||
  containsEnglish(
    confusedEnglish
  )
) {
  overrideAction =
    "explain_simple";

  overrideReason =
    "learner_confused";
}


/*
  7. "I don't know"

  في quiz/review المفروض ما يوصل هون أصلًا.

  لو وصل أثناء teaching:
  نفسّره كصعوبة، مش طلب عنصر جديد.
*/

else if (
  matchesArabic(
    dontKnowArabic
  ) ||
  matchesEnglish(
    dontKnowEnglish
  )
) {
  overrideAction =
    "explain_simple";

  overrideReason =
    "learner_does_not_know";
}


/*
  8. User understood
*/

else if (
  matchesArabic(
    understoodArabic
  ) ||
  matchesEnglish(
    understoodEnglish
  )
) {
  /*
    إذا الـAgent اختار move_harder بشكل صالح
    نسمح له.

    غير ذلك teach_new.
  */

  if (
    originalAgentAction ===
    "move_harder"
  ) {
    overrideAction =
      "move_harder";

    overrideReason =
      originalReasonCode ||
      "consecutive_understood_and_no_confusion";
  } else {
    overrideAction =
      "teach_new";

    overrideReason =
      "user_understood";
  }
}


/* =========================
   Learning Completed Protection
========================= */

/*
  بعد إنهاء Level 6 / Micro 4:
  أي رسالة لاحقة في Learning Mode يجب أن تتجه للتقييم النهائي،
  ولا نسمح بالرجوع إلى teach_new أو Level 7.
*/

if (
  !overrideAction &&
  currentStep === "learning_completed"
) {
  overrideAction =
    "finish_learning";

  overrideReason =
    "learning_program_completed_requires_post_test";
}


/* =========================
   Failed Quiz Protection
========================= */

/*
  بعد الرسوب:

  أي رسالة مبهمة مثل "تابع" ما لازم ترجع المستخدم
  للتعلم الجديد إذا ما زال بحاجة مراجعة.
*/

if (
  !overrideAction &&
  currentStep === "quiz_failed" &&
  !quizPassed &&
  reviewRecommended
) {
  overrideAction =
    "review_difficult";

  overrideReason =
    "failed_quiz_requires_review";
}


/* =========================
   Review Protection
========================= */

if (
  !overrideAction &&
  reviewActive
) {
  /*
    لو المراجعة active والرسالة ما كانت command واضح،
    نخليها بالمراجعة بدل ما تقفز للتعلم.
  */

  overrideAction =
    "review_difficult";

  overrideReason =
    "review_session_active";
}


/* =========================
   Validate Agent Action
========================= */

const agentDecisionValid =
  allowedActions.has(
    originalAgentAction
  );


/* =========================
   Fallback
========================= */

let fallbackAction =
  "teach_new";


if (
  currentStep === "learning_completed"
) {
  fallbackAction =
    "finish_learning";
} else if (
  currentStep === "quiz_failed" &&
  reviewRecommended
) {
  fallbackAction =
    "review_difficult";
} else if (
  reviewActive
) {
  fallbackAction =
    "review_difficult";
}


/* =========================
   Final Action
========================= */

let finalAction =
  overrideAction ||
  (
    agentDecisionValid
      ? originalAgentAction
      : fallbackAction
  );


let finalReason =
  overrideReason ||
  (
    agentDecisionValid
      ? (
          originalReasonCode ||
          "agent_decision"
        )
      : (
          fallbackAction ===
            "review_difficult"
            ? "fallback_continue_review"
            : "fallback_continue_learning"
        )
  );


/* =========================
   Final Safety Validation
========================= */

if (
  !allowedActions.has(
    finalAction
  )
) {
  finalAction =
    fallbackAction;

  finalReason =
    "invalid_action_fallback";
}


/* =========================
   Output
========================= */

return [
  {
    json: {
      action:
        finalAction,

      reason_code:
        finalReason,

      /*
        Decision Agent لا يكتب الرد النهائي.
      */
      reply:
        "",

      user_message:
        userMessage,

      current_step:
        currentStep,

      agent_decision_valid:
        agentDecisionValid,

      original_agent_action:
        originalAgentAction,

      fallback_action:
        fallbackAction,

      override_applied:
        Boolean(
          overrideAction
        ),

      parsed_agent_decision: {
        action:
          originalAgentAction,

        reason_code:
          originalReasonCode,

        reply:
          originalReply,
      },

      raw_agent_output:
        raw,
    },
  },
];

const decision =
  $("Validate Agent Decision").first().json ?? {};

const context =
  $("Build Agent Context").first().json ?? {};

const session = {
  ...(context.session_row ?? {}),
};


/* =========================
   Helpers
========================= */

function toText(value, fallback = "") {
  if (
    value === null ||
    value === undefined
  ) {
    return fallback;
  }

  const result =
    String(value).trim();

  return result || fallback;
}


function toNumber(value, fallback = 0) {
  const result =
    Number(value);

  return Number.isFinite(result)
    ? result
    : fallback;
}


function parseList(value) {
  if (Array.isArray(value)) {
    return [
      ...new Set(
        value
          .map(String)
          .map((item) => item.trim())
          .filter(Boolean)
      ),
    ];
  }

  if (!value) {
    return [];
  }

  try {
    const parsed =
      JSON.parse(String(value));

    return Array.isArray(parsed)
      ? [
          ...new Set(
            parsed
              .map(String)
              .map((item) => item.trim())
              .filter(Boolean)
          ),
        ]
      : [];
  } catch {
    return [
      ...new Set(
        String(value)
          .split(",")
          .map((item) => item.trim())
          .filter(Boolean)
      ),
    ];
  }
}


/* =========================
   Language
========================= */

const preferredLanguage =
  toText(
    context.preferred_language ??
    context.user_row?.preferred_language ??
    session.preferred_language,
    "MSA"
  );

const isEnglish =
  preferredLanguage
    .toLowerCase() === "english";


/* =========================
   Difficult Items
========================= */

const difficultItemIds =
  parseList(
    session.difficult_item_ids
  );

const currentItemId =
  toText(
    session.current_item_id
  );

if (
  currentItemId &&
  !difficultItemIds.includes(
    currentItemId
  )
) {
  difficultItemIds.push(
    currentItemId
  );
}


/* =========================
   Time
========================= */

const now =
  new Date().toISOString();


/* =========================
   Updated Session
========================= */

const updatedSession = {
  ...session,

  difficult_item_ids:
    JSON.stringify(
      difficultItemIds
    ),

  confusion_count:
    toNumber(
      session.confusion_count,
      0
    ) + 1,

