      "learner_did_not_understand"
    ),

  updated_at:
    now,

  last_activity_at:
    now,
};


/* =========================
   Reply
========================= */

const reply =
  toText(
    decision.reply,
    isEnglish
      ? "I'll explain it in a simpler way."
      : "سأشرح العبارة بطريقة أبسط."
  );


/* =========================
   Suggested Actions
========================= */

const suggestedActions =
  isEnglish
    ? [
        "Got it",
        "I don't understand",
        "Give me an example",
        "I want to review",
      ]
    : [
        "فهمت",
        "لم أفهم",
        "أعطني مثالًا",
        "أريد المراجعة",
      ];


/* =========================
   Progress
========================= */

const wordsCompleted =
  Math.max(
    0,
    toNumber(
      updatedSession.words_completed,
      0
    )
  );

const wordsTotal =
  Math.max(
    1,
    toNumber(
      updatedSession.words_total,
      20
    )
  );


/* =========================
   Response
========================= */

const response = {
  success:
    true,

  mode:
    "learning",

  action:
    "explain_simple",

  reply,

  suggested_actions:
    suggestedActions,

  current_level:
    Math.max(
      1,
      toNumber(
        updatedSession.current_level,
        1
      )
    ),

  current_micro_level:
    Math.max(
      1,
      toNumber(
        updatedSession.current_micro_level,
        1
      )
    ),

  words_completed:
    wordsCompleted,

  words_total:
    wordsTotal,

  words_remaining:
    Math.max(
      0,
      wordsTotal -
      wordsCompleted
    ),

  current_item_id:
    currentItemId,

  preferred_language:
    preferredLanguage,

  learning_session_id:
    toText(
      updatedSession.learning_session_id
    ),
};


/* =========================
   Output
========================= */

return [
  {
    json: {
      session_row:
        updatedSession,

      response,
    },
  },
];

/*
  Prepare Learning Welcome

  للمستخدم الجديد:
  - بعد الـPlacement مباشرة، نعرض مقدمة Baseline Test من 10 أسئلة.
  - لا نشرح Learning Mode قبل إنهاء الـBaseline.

  للمستخدم الذي بدأ التعلّم مسبقًا:
  - نستمر بسلوك Welcome Back المعتاد.
*/

const body =
  $("Webhook1").first().json.body ?? {};

const user =
  $("Get Learning User").first().json ?? {};

const existingSession =
