  );

const isEnglish =
  preferredLanguage
    .toLowerCase() === "english";

const displayName =
  toText(
    user.name ??
    user.full_name ??
    user.display_name ??
    body.name,
    email
      ? email.split("@")[0]
      : ""
  );


/* =========================
   Existing Session
========================= */

