    )
  );

const learningSessionId =
  hasExistingSession
    ? toText(
        existingSession.learning_session_id
      )
    : createId("learning");

const chatSessionId =
  toText(
    existingSession.chat_session_id ??
    body.chat_session_id ??
    body.session_id,
    createId("chat")
  );


/* =========================
   Level Information
========================= */

const userPlacementLevel =
  Math.max(
    1,
    toNumber(
      user.placement_level,
      1
    )
  );

const storedSessionLevel =
  toNumber(
    existingSession.current_level,
    0
