    toNumber(
      existingSession.current_micro_level,
      1
    )
  );


/* =========================
   Learning Progress
========================= */

const wordsCompleted =
  Math.max(
    0,
    toNumber(
      existingSession.words_completed,
      0
    )
  );

const wordsTotal =
  Math.max(
    1,
    toNumber(
      existingSession.words_total,
      20
    )
  );

const wordsRemaining =
  Math.max(
    0,
    wordsTotal -
    wordsCompleted
  );

