      existingSession.baseline_completed_at
    )
  );

/*
  نطلب Baseline فقط:
  1. للمستخدم الجديد
  2. أو إذا كانت جلسته أصلًا في مرحلة الـBaseline.

  بهذا الشكل لا نفرض Baseline بأثر رجعي
  على جلسات تعليم قديمة بدأت قبل إضافة النظام.
*/
const baselineStep =
  [
    "baseline_intro",
    "baseline_loading",
    "baseline_question",
    "baseline_completed",
  ].includes(existingStep);

const shouldShowBaselineIntro =
  !hasExistingSession ||
  (
    baselineStep &&
    !baselineCompleted
  );


/* =========================
   Reply
========================= */

let reply;
let suggestedActions;
let responseAction;
let nextCurrentStep;


