   New learner → Baseline
------------------------- */

if (shouldShowBaselineIntro) {
  if (isEnglish) {
    reply =
      `Welcome${displayName ? `, ${displayName}` : ""}! ` +
      `Your current level is Level ${currentLevel}.\n\n` +

      `Before you begin your learning journey, you'll take a short assessment with 10 questions based on your current level.\n\n` +

      `This assessment is not pass or fail. ` +
      `It helps us measure what you know now so we can compare your progress before and after learning.\n\n` +

      `Answer from memory. After the 10 questions, you'll begin your learning journey.\n\n` +

      `Ready to begin the assessment?`;

    suggestedActions = [
      "Start assessment",
      "Not now",
    ];
  } else {
    reply =
      `مرحبًا${displayName ? ` يا ${displayName}` : ""}! ` +
      `مستواك الحالي هو المستوى ${currentLevel}.\n\n` +

      `قبل أن تبدأ رحلة التعلّم، ستجيب عن تقييم قصير مكوّن من 10 أسئلة مناسبة لمستواك الحالي.\n\n` +

      `هذا التقييم ليس للنجاح أو الرسوب، بل يساعدنا على قياس معرفتك الحالية ومقارنة تقدّمك قبل التعلّم وبعده.\n\n` +

      `أجب من ذاكرتك، وبعد إكمال الأسئلة العشرة ستبدأ رحلة التعلّم.\n\n` +

      `هل أنت مستعد لبدء التقييم؟`;

    suggestedActions = [
      "ابدأ التقييم",
      "ليس الآن",
    ];
  }

  responseAction =
    "baseline_intro";

  nextCurrentStep =
    "baseline_intro";
}


/* -------------------------
   Returning learner
------------------------- */

else {
  if (isEnglish) {
    reply =
      `Welcome back${displayName ? `, ${displayName}` : ""}! ` +
      `You are currently at Level ${currentLevel}, Stage ${currentMicroLevel}, ` +
      `and you have completed ${wordsCompleted} of ${wordsTotal} items. ` +
      `Shall we continue your learning journey?`;

