      `مرحبًا بعودتك${displayName ? ` يا ${displayName}` : ""}! ` +
      `أنت حاليًا في المستوى ${currentLevel}، المرحلة ${currentMicroLevel}، ` +
      `وقد أنجزت ${wordsCompleted} من ${wordsTotal} عبارة. ` +
      `هل نكمل رحلة التعلّم؟`;

    suggestedActions = [
      "يلا نكمل",
      "أريد المراجعة",
    ];
  }

  responseAction =
    "learning_welcome";

  nextCurrentStep =
    "awaiting_continue";
}


/* =========================
   Time
========================= */

const now =
  new Date().toISOString();


/* =========================
   Session Row
