        mode:
          "learning",

        action:
          "repeat_current",

        reply,

        suggested_actions:
          isEnglish
            ? [
                "Got it",
                "I don't understand",
                "Give me an example",
              ]
            : [
                "فهمت",
                "لم أفهم",
                "أعطني مثالًا",
              ],

        current_item_id:
          toText(
            updatedSession.current_item_id
          ),

        current_level:
          toNumber(
            updatedSession.current_level,
            1
          ),

        words_completed:
          toNumber(
            updatedSession.words_completed,
            0
          ),

        words_total:
          toNumber(
            updatedSession.words_total,
            20
          ),

        preferred_language:
          preferredLanguage,
      },
