  },
];

const decision =
  $("Validate Agent Decision").first().json ?? {};

const context =
  $("Build Agent Context").first().json ?? {};

const session = {
  ...(context.session_row ?? {}),
};

function toText(value, fallback = "") {
  if (value === null || value === undefined) {
    return fallback;
  }

  const result = String(value).trim();
  return result || fallback;
}

function toNumber(value, fallback = 0) {
  const result = Number(value);

  return Number.isFinite(result)
    ? result
    : fallback;
}

const preferredLanguage = toText(
  context.preferred_language ??
  context.user_row?.preferred_language,
  "MSA"
);

const isEnglish =
  preferredLanguage.toLowerCase() === "english";

const now =
  new Date().toISOString();

const updatedSession = {
  ...session,

  review_recommended:
    true,

  review_active:
    false,

  last_agent_action:
    "recommend_review",

  last_agent_reason:
    toText(
      decision.reason_code,
      "difficult_items_detected"
    ),

  updated_at:
    now,

  last_activity_at:
    now,
};

const fallbackReply = isEnglish
  ? "I noticed that some phrases needed extra explanation. Would you like a short review of the difficult items?"
  : "لاحظت أن بعض العبارات احتاجت إلى شرح إضافي. هل ترغب في مراجعة قصيرة للعناصر الصعبة؟";

const reply =
  toText(decision.reply) ||
  fallbackReply;

return [
  {
    json: {
      session_row:
        updatedSession,

      response: {
        success: true,

        mode:
          "learning",

        action:
          "recommend_review",

        reply,

        suggested_actions:
          isEnglish
            ? [
                "Start review",
                "Continue learning",
              ]
            : [
                "ابدأ المراجعة",
                "أكمل التعلّم",
              ],

        current_level:
          toNumber(
            updatedSession.current_level,
            1
          ),

        words_completed:
          toNumber(
            updatedSession.words_completed,
            0
          ),

        words_total:
          toNumber(
            updatedSession.words_total,
            20
          ),

        preferred_language:
          preferredLanguage,
      },
    },
  },
];

/*
  Prepare Review Request

  نوعان من المراجعة:

  1) Optional Review أثناء التعلّم:
     - يراجع جميع العناصر المكتملة حتى الآن.
     - نستخدم difficult_item_ids كقائمة مراجعة مؤقتة.
     - كل إجابة صحيحة تشيل العنصر من القائمة.
     - عند انتهاء القائمة يرجع المستخدم للتعلّم.

  2) Review بعد الرسوب في Quiz:
     - يراجع فقط difficult_item_ids الناتجة عن أخطاء الكويز.
     - عند انتهاء القائمة يصبح المستخدم جاهزًا لإعادة الاختبار.

  يتم تجاهل IDs القديمة التي تبدأ بـ content-.
*/

const decision =
  $("Validate Agent Decision").first().json ?? {};

const context =
  $("Build Agent Context").first().json ?? {};

const session = {
  ...(context.session_row ?? {}),
};


/* =========================
   Helpers
========================= */

function toText(value, fallback = "") {
  if (
    value === null ||
    value === undefined
  ) {
    return fallback;
  }

  const result =
    String(value).trim();

  return result || fallback;
}


function toNumber(value, fallback = 0) {
  const result =
    Number(value);

  return Number.isFinite(result)
    ? result
    : fallback;
}


function toBoolean(value, fallback = false) {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value === "number") {
    return value === 1;
  }

  const normalized =
    toText(value)
      .toLowerCase();

  if (
    [
      "true",
      "1",
      "yes",
    ].includes(normalized)
  ) {
    return true;
  }

  if (
    [
      "false",
      "0",
      "no",
    ].includes(normalized)
  ) {
    return false;
  }

  return fallback;
}


function parseList(value) {
  if (Array.isArray(value)) {
    return [
      ...new Set(
        value
          .map((item) => toText(item))
          .filter(Boolean)
      ),
    ];
  }

  const raw =
    toText(value);

  if (
    !raw ||
    raw.toLowerCase() === "null"
  ) {
    return [];
  }

  try {
    const parsed =
      JSON.parse(raw);

    if (Array.isArray(parsed)) {
      return [
        ...new Set(
          parsed
            .map((item) => toText(item))
            .filter(Boolean)
        ),
      ];
    }
  } catch {
    // continue
  }

  return [
    ...new Set(
      raw
        .split(",")
        .map((item) => item.trim())
        .filter(Boolean)
    ),
  ];
}


function validIds(value) {
  return parseList(value)
    .filter((id) => {
      const normalized =
        toText(id);

      return (
        normalized &&
        !normalized.startsWith(
          "content-"
        )
      );
    });
}


function firstItem(items) {
  if (
    !Array.isArray(items) ||
    items.length === 0
  ) {
    return "";
  }

  return toText(
    items[0]
  );
}


/* =========================
   Language
========================= */

const preferredLanguage =
  toText(
    context.preferred_language ??
    context.user_row?.preferred_language,
    "MSA"
  );

const isEnglish =
  preferredLanguage
    .toLowerCase() === "english";


/* =========================
   Current State
========================= */

const currentStep =
  toText(
    session.current_step
  );

const previousReviewItemId =
  toText(
    session.current_item_id
  );


/*
  بعد الإجابة عن عنصر مراجعة،
  Prepare Review Result يجعل current_step = review_result.
*/
const continuingReview =
  currentStep ===
  "review_result";


/* =========================
   Detect Review Type
========================= */

/*
  إذا دخلنا المراجعة مباشرة بعد Quiz failed،
  فهي مراجعة أخطاء الاختبار.

  أي مراجعة أخرى أثناء التعلم تعتبر Optional Review.
*/

const quizPassed =
  toBoolean(
    session.quiz_passed,
    false
  );

const reviewAfterFailedQuiz =
  currentStep === "quiz_failed" ||
  (
    toBoolean(
      session.review_recommended,
      false
    ) &&
    quizPassed === false
  );


/* =========================
   Existing Lists
========================= */

const difficultItemIds =
  validIds(
    session.difficult_item_ids
  );

const completedItemIds =
  validIds(
    session.completed_item_ids
  );


/* =========================
   Build Review Queue
========================= */

let reviewQueueIds = [];


/*
  عند Continue Review:
  القائمة الحالية الموجودة في difficult_item_ids
  هي نفسها الـqueue بعد ما Prepare Review Result
  شال منها العناصر الصحيحة.
*/

if (continuingReview) {

  reviewQueueIds =
    [...difficultItemIds];

} else if (reviewAfterFailedQuiz) {

  /*
    بعد الرسوب:
    فقط أخطاء الكويز.
  */
  reviewQueueIds =
    [...difficultItemIds];

} else {

  /*
    Optional Review أثناء التعلم:
    نراجع جميع العناصر المكتملة.

    نضيف difficult أيضًا احتياطًا،
    ثم نزيل التكرار.
  */
  reviewQueueIds = [
    ...new Set([
      ...completedItemIds,
      ...difficultItemIds,
    ]),
  ];
}


/* =========================
   Avoid Immediate Repeat
========================= */

/*
  عادة Prepare Review Result يشيل العنصر الصحيح
  من difficult_item_ids بالفعل.

  هاي حماية إضافية حتى لا يعيد نفس العنصر مباشرة.
*/

if (
  continuingReview &&
  reviewQueueIds.length > 1
) {
  reviewQueueIds =
    reviewQueueIds.filter(
      (id) =>
        toText(id) !==
        previousReviewItemId
    );
}


/* =========================
   Select Review Target
========================= */

const reviewTargetId =
  firstItem(
    reviewQueueIds
  );

const hasReviewItem =
  Boolean(
    reviewTargetId
  );


/* =========================
   Review Origin Marker
========================= */

const reviewOriginReason =
  reviewAfterFailedQuiz
    ? "quiz_failed_review"
    : "optional_learning_review";


/* =========================
   Time
========================= */

const now =
  new Date().toISOString();


/* =========================
   Update Session
========================= */

const updatedSession = {
  ...session,

  /*
    نخزن قائمة المراجعة الحالية هنا.
    Prepare Review Result سيزيل منها
    العناصر التي تمت الإجابة عنها بشكل صحيح.
  */
  difficult_item_ids:
    JSON.stringify(
      reviewQueueIds
    ),

  review_active:
    hasReviewItem,

  /*
    تبقى true فقط لمراجعة أخطاء Quiz.
  */
  review_recommended:
    reviewAfterFailedQuiz,

  current_step:
    hasReviewItem
      ? "review_loading"
      : (
          reviewAfterFailedQuiz
            ? "review_completed"
            : "awaiting_continue"
        ),

  last_agent_action:
    "review_difficult",

  /*
    مهم:
    Prepare Review Item يحافظ على هذا السبب،
    فنقدر نعرف لاحقًا نوع المراجعة.
  */
  last_agent_reason:
    reviewOriginReason,

  updated_at:
    now,

  last_activity_at:
    now,
};


/* =========================
   Empty Review Response
========================= */

let emptyReply;
let emptySuggestedActions;


if (reviewAfterFailedQuiz) {

  if (isEnglish) {
    emptyReply =
      "You have reviewed all of the items you missed on the quiz. You're ready to try the quiz again.";

    emptySuggestedActions = [
      "Retry quiz",
    ];
  } else {
    emptyReply =
      "راجعت جميع العبارات التي أخطأت فيها في الاختبار. أصبحت جاهزًا لإعادة الاختبار.";

    emptySuggestedActions = [
      "أعد الاختبار",
    ];
  }

} else {

  if (isEnglish) {
    emptyReply =
      completedItemIds.length
        ? "Your review is complete. You can continue learning from where you left off."
        : "You do not have any completed learning items to review yet.";

    emptySuggestedActions = [
      "Continue learning",
    ];
  } else {
    emptyReply =
      completedItemIds.length
        ? "أنهيت المراجعة. يمكنك متابعة التعلّم من حيث توقفت."
        : "لم تُكمل أي عبارات يمكن مراجعتها حتى الآن.";

    emptySuggestedActions = [
      "تابع التعلّم",
    ];
  }
}


const emptyResponse = {
  success:
    true,

  mode:
    "learning",

  action:
    reviewAfterFailedQuiz
      ? "review_completed"
      : "review_completed_learning",

  reply:
    emptyReply,

  suggested_actions:
    emptySuggestedActions,

  review_active:
    false,

  review_after_failed_quiz:
    reviewAfterFailedQuiz,

  current_level:
    toNumber(
      session.current_level,
      1
    ),

  current_micro_level:
    toNumber(
      session.current_micro_level,
      1
    ),

  words_completed:
    toNumber(
      session.words_completed,
      0
    ),

  words_total:
    toNumber(
      session.words_total,
      20
    ),

  words_remaining:
    Math.max(
      0,
      toNumber(
        session.words_total,
        20
      ) -
      toNumber(
        session.words_completed,
        0
      )
    ),

  preferred_language:
    preferredLanguage,

  learning_session_id:
    toText(
      session.learning_session_id
    ),
};


/* =========================
   Output
========================= */

return [
  {
    json: {
      review_target_id:
        reviewTargetId,

      has_review_item:
        hasReviewItem,

      previous_review_item_id:
        previousReviewItemId,

      continuing_review:
        continuingReview,

      review_after_failed_quiz:
        reviewAfterFailedQuiz,

      review_origin:
        reviewOriginReason,

      review_queue_ids:
        reviewQueueIds,

      difficult_item_ids:
        difficultItemIds,

      completed_item_ids:
        completedItemIds,

      preferred_language:
        preferredLanguage,

      session_row:
        updatedSession,

      response:
        hasReviewItem
          ? null
          : emptyResponse,
    },
  },
];

parameters.prompt:
={{
  `Retrieve the Levantine learning item with ID ${
