  }.`
}}

parameters.jsCode:
/*
  Prepare Review Item

  يأخذ العنصر الذي جلبته Chroma
  ويحوّله إلى سؤال مراجعة بدون كشف الإجابة.

  مهم:
  يحافظ أيضًا على:
  - review_queue_ids
  - review_origin
  القادمين من Prepare Review Request.
*/


const reviewRequest =
  $("Prepare Review Request").first().json ?? {};

const session = {
  ...(reviewRequest.session_row ?? {}),
};

const chromaResult =
  $input.first().json ?? {};


/* =========================
   Helpers
========================= */

function toText(value, fallback = "") {
  if (
    value === null ||
    value === undefined
  ) {
    return fallback;
  }

  if (Array.isArray(value)) {
    const firstValue =
      value.find((item) => {
        return (
          item !== null &&
          item !== undefined &&
          String(item).trim()
        );
      });

    return firstValue === undefined
      ? fallback
      : String(firstValue).trim();
  }

  const result =
    String(value).trim();

  return result || fallback;
}


function toNumber(value, fallback = 0) {
  const result =
    Number(value);

  return Number.isFinite(result)
    ? result
    : fallback;
}


function escapeRegex(value) {
  return String(value).replace(
    /[.*+?^${}()|[\]\\]/g,
    "\\$&"
  );
}


/* =========================
   Read Chroma structure
========================= */

function findMetadata(result) {
  if (
    result.document?.metadata &&
    typeof result.document.metadata === "object"
  ) {
    return result.document.metadata;
  }

  if (
    result.metadata &&
    typeof result.metadata === "object"
  ) {
    return result.metadata;
  }

  if (
    Array.isArray(result.metadatas) &&
    result.metadatas[0]
  ) {
    return result.metadatas[0];
  }

  return {};
}


function findContent(result) {
  return toText(
    result.document?.pageContent ??
    result.document?.content ??
    result.pageContent ??
    result.content ??
    result.text ??
    result.documents?.[0]
  );
}


function valueFromContent(
  content,
  labels
) {
  const source =
    toText(content);

  if (!source) {
    return "";
  }

  for (const label of labels) {
    const escapedLabel =
      escapeRegex(label);

    const pattern =
      new RegExp(
        `(?:^|\\n)\\s*${escapedLabel}\\s*[:：-]\\s*(.+?)(?=\\n|$)`,
        "i"
      );

    const match =
      source.match(pattern);

    if (match) {
      return toText(
        match[1]
      );
    }
  }

  return "";
}


/* =========================
   Extract current review item
========================= */

const metadata =
  findMetadata(chromaResult);

const content =
  findContent(chromaResult);


const itemId =
  toText(
    metadata.item_id ??
    metadata.original_id ??
    metadata.source_id ??
    reviewRequest.review_target_id
  );


const sourceId =
  toText(
    metadata.source_id ??
    metadata.original_id ??
    itemId
  );


const levantine =
  toText(
    metadata.levantine ??
    valueFromContent(
      content,
      [
        "الشامية",
        "Levantine",
        "Levantine Arabic",
      ]
    )
  );


const msa =
  toText(
    metadata.msa ??
    valueFromContent(
      content,
      [
        "الفصحى",
        "MSA",
        "Modern Standard Arabic",
      ]
    )
  );


const english =
  toText(
    metadata.english ??
    valueFromContent(
      content,
      [
        "الإنجليزية",
        "English",
        "Meaning",
      ]
    )
  );


const topic =
  toText(
    metadata.topic ??
    valueFromContent(
      content,
      [
        "الموضوع",
        "Topic",
      ]
    )
  );


/* =========================
   Review State
========================= */

/*
  مهم جدًا:
  نقرأهم من TOP LEVEL
  في Prepare Review Request،
  مش من session_row القديمة.
*/

const reviewQueueIds =
  Array.isArray(
    reviewRequest.review_queue_ids
  )
    ? reviewRequest.review_queue_ids
    : [];


const reviewOrigin =
  toText(
    reviewRequest.review_origin,
    "optional_learning_review"
  );


/* =========================
   Interface language
========================= */

const preferredLanguage =
  toText(
    reviewRequest.preferred_language,
    "MSA"
  );

const isEnglish =
  preferredLanguage
    .toLowerCase() === "english";


/* =========================
   Build review question
========================= */

const isPhrase =
  levantine
    .split(/\s+/)
    .filter(Boolean)
    .length > 1;


let reply;


if (!levantine) {

  reply =
    isEnglish
      ? "I could not load the review item. Please continue learning and try reviewing again later."
      : "لم أتمكن من تحميل عنصر المراجعة. تابع التعلّم ثم حاول المراجعة مرة أخرى.";

} else if (isEnglish) {

  reply =
    isPhrase
      ? `Quick review: What does the phrase «${levantine}» mean in English?`
      : `Quick review: What does the word «${levantine}» mean in English?`;

} else {

  reply =
    isPhrase
      ? `مراجعة سريعة: ما معنى العبارة «${levantine}» بالفصحى؟`
      : `مراجعة سريعة: ما معنى كلمة «${levantine}» بالفصحى؟`;
}


/* =========================
   Update session
========================= */

const now =
  new Date().toISOString();


const updatedSession = {
  ...session,

  current_item_id:
    itemId,

  current_source_id:
    sourceId,

  current_levantine:
    levantine,

  current_msa:
    msa,

  current_english:
    english,

  current_topic:
    topic,

  /*
    أهم تعديل:
    نحفظ queue و origin الجديدين داخل session_row.
  */
  review_queue_ids:
    JSON.stringify(
      reviewQueueIds
    ),

  review_origin:
    reviewOrigin,

  current_step:
    "review_question",

  review_active:
    true,

  review_recommended:
    reviewOrigin ===
      "quiz_failed_review",

  last_agent_action:
    "review_difficult",

  last_agent_reason:
    reviewOrigin,

  updated_at:
    now,

  last_activity_at:
    now,
};


/* =========================
   Frontend response
========================= */

const response = {
  success:
    Boolean(
      itemId &&
      levantine
    ),

  mode:
    "learning",

  action:
    "review_question",

  reply,

  suggested_actions:
    [],

  review_active:
    true,

  review_origin:
    reviewOrigin,

  remaining_review_items:
    reviewQueueIds.length,

  current_item_id:
    itemId,

  current_level:
    toNumber(
      updatedSession.current_level,
      1
    ),

  current_micro_level:
    toNumber(
      updatedSession.current_micro_level,
      1
    ),

  words_completed:
    toNumber(
      updatedSession.words_completed,
      0
    ),

  words_total:
    toNumber(
      updatedSession.words_total,
      20
    ),

  words_remaining:
    Math.max(
      0,
      toNumber(
        updatedSession.words_total,
        20
      ) -
      toNumber(
        updatedSession.words_completed,
        0
      )
    ),

  preferred_language:
    preferredLanguage,

  learning_session_id:
    toText(
      updatedSession.learning_session_id
    ),
};


/* =========================
   Output
========================= */

return [
  {
    json: {
      session_row:
        updatedSession,

      response,

      review_item: {
        item_id:
          itemId,

        levantine,

        msa,

        english,

        topic,
      },

      review_queue_ids:
        reviewQueueIds,

      review_origin:
        reviewOrigin,
    },
  },
];

const teachingResult =
  $input.first().json ?? {};

const prepared =
  $("Prepare learning start").first().json ?? {};

function toText(value, fallback = "") {
  if (value === null || value === undefined) {
    return fallback;
  }

  const result = String(value).trim();

  return result || fallback;
}


/* =========================
   Teaching Reply
========================= */

const teachingReply = toText(
  teachingResult.output ??
  teachingResult.reply ??
  teachingResult.text ??
  teachingResult.message
);


/* =========================
   Original Response
========================= */

const originalResponse = {
  ...(prepared.response ?? {}),
};


/* =========================
   Language
========================= */

const preferredLanguage = toText(
  originalResponse.preferred_language ??
  prepared.session_row?.preferred_language ??
  $("Build Agent Context").first().json?.preferred_language,
  "MSA"
);

const isEnglish =
  preferredLanguage.toLowerCase() === "english";


/* =========================
   Suggested Actions
========================= */

const defaultSuggestedActions =
  isEnglish
    ? [
        "Got it",
        "I don't understand",
        "Give me an example",
        "I want to review",
      ]
    : [
        "فهمت",
        "لم أفهم",
        "أعطني مثالًا",
        "أريد المراجعة",
      ];

const existingSuggestedActions =
  Array.isArray(originalResponse.suggested_actions)
    ? originalResponse.suggested_actions.filter(Boolean)
    : [];

const suggestedActions =
  existingSuggestedActions.length
    ? existingSuggestedActions
    : defaultSuggestedActions;


/* =========================
   Final Response
========================= */

const finalResponse = {
  ...originalResponse,

  reply:
    teachingReply ||
    originalResponse.reply ||
    "",

  suggested_actions:
    suggestedActions,

  preferred_language:
    preferredLanguage,
};


/* =========================
   Output
========================= */

return [
  {
    json: {
      session_row:
        prepared.session_row ?? {},

      response:
        finalResponse,

      teaching_reply:
        teachingReply,

      teaching_raw_output:
        teachingResult,
    },
  },
];

