parameters.jsCode:
/*
  Prepare Review Result

  المسؤوليات:
  - تقييم إجابة المراجعة
  - التعامل مع "لا أعلم / I don't know"
  - تحديث review_queue_ids
  - عدم خلط Optional Review مع difficult_item_ids
  - إذا كانت مراجعة بعد Quiz failed:
      correct  -> إزالة العنصر من difficult_item_ids
      incorrect -> إبقاؤه
  - إذا كانت Optional Review:
      difficult_item_ids تبقى كما هي
  - عند انتهاء queue:
      Optional Review -> Continue learning
      Quiz Failed Review -> Retry quiz
*/


/* =========================
   Read Nodes
========================= */

const context =
  $("Build Agent Context").first().json ?? {};

const session = {
  ...(context.session_row ?? {}),
};

const evaluatorInput =
  $input.first()?.json ?? {};


/* =========================
   Helpers
========================= */

function toText(value, fallback = "") {
  if (
    value === null ||
    value === undefined
  ) {
    return fallback;
  }

  const result =
    String(value).trim();

  return result || fallback;
}


function toNumber(value, fallback = 0) {
  const result =
    Number(value);

  return Number.isFinite(result)
    ? result
    : fallback;
}


function toBoolean(value, fallback = false) {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value === "number") {
    return value === 1;
  }

  const normalized =
    toText(value)
      .toLowerCase();

  if (
    [
      "true",
      "1",
      "yes",
      "correct",
    ].includes(normalized)
  ) {
    return true;
  }

  if (
    [
      "false",
      "0",
      "no",
      "incorrect",
    ].includes(normalized)
  ) {
    return false;
  }

  return fallback;
}


function parseList(value) {
  if (Array.isArray(value)) {
    return [
      ...new Set(
        value
          .map((item) => toText(item))
          .filter(Boolean)
      ),
    ];
  }

  const raw =
    toText(value);

  if (
    !raw ||
    raw.toLowerCase() === "null"
  ) {
    return [];
  }

  try {
    const parsed =
      JSON.parse(raw);

    if (Array.isArray(parsed)) {
      return [
        ...new Set(
          parsed
            .map((item) => toText(item))
            .filter(Boolean)
        ),
      ];
    }
  } catch {
    // continue
  }

  return [
    ...new Set(
      raw
        .split(",")
        .map((item) => item.trim())
        .filter(Boolean)
    ),
  ];
}


function parseEvaluator(input) {
  let raw =
    input?.output ??
    input?.text ??
    input?.response ??
    input;

  if (
    raw &&
    typeof raw === "object"
  ) {
    return raw;
  }

  raw =
    toText(raw);

  if (!raw) {
    return {};
  }

  raw = raw
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/```$/i, "")
    .trim();

  try {
    return JSON.parse(raw);
  } catch {
    const firstBrace =
      raw.indexOf("{");

    const lastBrace =
      raw.lastIndexOf("}");

    if (
      firstBrace !== -1 &&
      lastBrace !== -1 &&
      lastBrace > firstBrace
    ) {
      try {
        return JSON.parse(
          raw.slice(
            firstBrace,
            lastBrace + 1
          )
        );
      } catch {
        return {};
      }
    }

    return {};
  }
}


function normalizeArabic(value) {
  return toText(value)
    .toLowerCase()
    .replace(/[ًٌٍَُِّْـ]/g, "")
    .replace(/[أإآ]/g, "ا")
    .replace(/ى/g, "ي")
    .replace(/ة/g, "ه")
    .replace(/[؟?!.,،؛:]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}


/* =========================
   Language
========================= */

const preferredLanguage =
  toText(
    context.preferred_language,
    "MSA"
  );

const isEnglish =
  preferredLanguage
    .toLowerCase() === "english";


/* =========================
   Review Origin
========================= */

const reviewOrigin =
  toText(
    session.review_origin,
    "optional_learning_review"
  );

const reviewAfterFailedQuiz =
  reviewOrigin ===
  "quiz_failed_review";


/* =========================
   Evaluation
========================= */

const evaluation =
  parseEvaluator(
    evaluatorInput
  );

const evaluatorCorrect =
  toBoolean(
    evaluation.correct ??
    evaluation.is_correct ??
    evaluation.semantic_correct,
    false
  );


/* =========================
   Learner Answer
========================= */

const learnerAnswer =
  toText(
    context.user_message
  );

const normalizedAnswer =
  normalizeArabic(
    learnerAnswer
  );


const dontKnowArabic = [
  "لا أعلم",
  "لا اعلم",
  "لا أعرف",
  "لا اعرف",
  "ما بعرف",
  "ما أعرف",
  "ما اعرف",
  "مش عارف",
  "مش عارفة",
  "مش عارفه",
  "لا أدري",
  "لا ادري",
  "مش متأكد",
  "مش متاكد",
  "مش متأكدة",
  "مش متاكده",
];


const dontKnowEnglish = [
  "i don't know",
  "i dont know",
  "don't know",
  "dont know",
  "not sure",
  "i'm not sure",
  "im not sure",
];


const learnerDoesNotKnow =
  dontKnowArabic.some(
    (phrase) =>
      normalizedAnswer ===
      normalizeArabic(phrase)
  ) ||
  dontKnowEnglish.some(
    (phrase) =>
      learnerAnswer
        .toLowerCase()
        .trim() === phrase
  );


const finalCorrect =
  learnerDoesNotKnow
    ? false
    : evaluatorCorrect;


/* =========================
   Current Review Item
========================= */

const currentItemId =
  toText(
    session.current_item_id
  );

const currentLevantine =
  toText(
    session.current_levantine
  );

const correctAnswer =
  isEnglish
    ? toText(
        session.current_english ??
        evaluation.canonical_answer ??
        evaluation.correct_answer
      )
    : toText(
        session.current_msa ??
        evaluation.canonical_answer ??
        evaluation.correct_answer
      );


/* =========================
   Review Queue
========================= */

let reviewQueueIds =
  parseList(
    session.review_queue_ids
  );


/*
  إذا الإجابة صحيحة:
  نشيل العنصر الحالي نهائيًا من queue.

  إذا الإجابة خاطئة:
  يبقى ضمن queue،
  لكن ننقله للنهاية حتى لا يتكرر مباشرة
  قبل مراجعة بقية العناصر.
*/

if (currentItemId) {

  reviewQueueIds =
    reviewQueueIds.filter(
      (id) =>
        id !== currentItemId
    );

  if (!finalCorrect) {
    reviewQueueIds.push(
      currentItemId
    );
  }
}


/* =========================
   Difficult Items
========================= */

let difficultItemIds =
  parseList(
    session.difficult_item_ids
  );


/*
  مهم جدًا:

  Optional Review:
  لا نغيّر difficult_item_ids نهائيًا.

  Quiz Failed Review:
  - صح: نشيل العنصر من difficult
  - خطأ: نخليه / نضيفه
*/

if (
  reviewAfterFailedQuiz &&
  currentItemId
) {

  if (finalCorrect) {

    difficultItemIds =
      difficultItemIds.filter(
        (id) =>
          id !== currentItemId
      );

  } else {

    if (
      !difficultItemIds.includes(
        currentItemId
      )
    ) {
      difficultItemIds.push(
        currentItemId
      );
    }
  }
}


/* =========================
   Review Finished?
========================= */

const remainingReviewItems =
  reviewQueueIds.length;

const reviewFinished =
  remainingReviewItems === 0;


/* =========================
   Counters
========================= */

let correctAnswers =
  Math.max(
    0,
    toNumber(
      session.correct_answers,
      0
    )
  );

let wrongAnswers =
  Math.max(
    0,
    toNumber(
      session.wrong_answers,
      0
    )
  );


if (finalCorrect) {
  correctAnswers += 1;
} else {
  wrongAnswers += 1;
}


/* =========================
   Feedback Reply
========================= */

let reply = "";


if (isEnglish) {

  if (reviewFinished) {

    if (reviewAfterFailedQuiz) {

      reply =
        "Great — you've reviewed all the items you missed on the quiz. You're ready to try the quiz again.";

    } else {

      reply =
        "Great — your review is complete. You can continue learning from where you left off.";
    }

  } else if (finalCorrect) {

    reply =
      `Correct ✅ "${currentLevantine}" means "${correctAnswer}". You have ${remainingReviewItems} ${
        remainingReviewItems === 1
          ? "item"
          : "items"
      } left to review.`;

  } else if (learnerDoesNotKnow) {

    reply =
      `No problem. "${currentLevantine}" means "${correctAnswer}". We'll review it again after the other items.`;

  } else {

    reply =
      `Not quite. "${currentLevantine}" means "${correctAnswer}". We'll review it again after the other items.`;
  }

} else {

  if (reviewFinished) {

    if (reviewAfterFailedQuiz) {

      reply =
        "ممتاز، راجعت جميع العبارات التي أخطأت فيها في الاختبار. أصبحت جاهزًا لإعادة الاختبار.";

    } else {

      reply =
        "ممتاز، أنهيت المراجعة. يمكنك الآن متابعة التعلّم من حيث توقفت.";
    }

  } else if (finalCorrect) {

    reply =
      `إجابة صحيحة ✅ «${currentLevantine}» تعني «${correctAnswer}». بقي ${
        remainingReviewItems === 1
          ? "عنصر واحد"
          : `${remainingReviewItems} عناصر`
      } للمراجعة.`;

  } else if (learnerDoesNotKnow) {

    reply =
      `لا بأس. «${currentLevantine}» تعني «${correctAnswer}». سنعود إليها مرة أخرى بعد مراجعة بقية العناصر.`;

  } else {

    reply =
      `الإجابة ليست صحيحة تمامًا. «${currentLevantine}» تعني «${correctAnswer}». سنعود إليها مرة أخرى بعد مراجعة بقية العناصر.`;
  }
}


/* =========================
   Suggested Actions
========================= */

let suggestedActions = [];


if (reviewFinished) {

  if (reviewAfterFailedQuiz) {

    suggestedActions =
      isEnglish
        ? [
            "Retry quiz",
          ]
        : [
            "أعد الاختبار",
          ];

  } else {

    suggestedActions =
      isEnglish
        ? [
            "Continue learning",
          ]
        : [
            "تابع التعلّم",
          ];
  }

} else {

  if (reviewAfterFailedQuiz) {

    /*
      بعد الرسوب:
      لازم يكمل مراجعة الأخطاء.
    */
    suggestedActions =
      isEnglish
        ? [
            "Continue review",
          ]
        : [
            "تابع المراجعة",
          ];

  } else {

    /*
      مراجعة اختيارية:
      يقدر يكمل مراجعة أو يرجع للتعلّم.
    */
    suggestedActions =
      isEnglish
        ? [
            "Continue review",
            "Continue learning",
          ]
        : [
            "تابع المراجعة",
            "تابع التعلّم",
          ];
  }
}


/* =========================
   Time
========================= */

const now =
  new Date().toISOString();


/* =========================
   Updated Session
========================= */

const updatedSession = {
  ...session,

  review_queue_ids:
    JSON.stringify(
      reviewQueueIds
    ),

  review_origin:
    reviewFinished
      ? ""
      : reviewOrigin,

  difficult_item_ids:
