          reviewAfterFailedQuiz
            ? "quiz_mistakes_review_completed"
            : "optional_learning_review_completed"
        )
      : finalCorrect
        ? "review_answer_correct"
        : learnerDoesNotKnow
          ? "review_answer_unknown"
          : "review_answer_incorrect",

  updated_at:
    now,

  last_activity_at:
    now,
};


/* =========================
   Response
========================= */

const response = {
  success:
    true,

  mode:
    "learning",

  action:
    reviewFinished
      ? (
          reviewAfterFailedQuiz
            ? "review_completed"
            : "review_completed_learning"
        )
      : "review_result",

