  suggested_actions:
    suggestedActions,

  answer_correct:
    finalCorrect,

  learner_does_not_know:
    learnerDoesNotKnow,

  remaining_review_items:
    remainingReviewItems,

  review_completed:
    reviewFinished,

  review_origin:
    reviewOrigin,

  review_after_failed_quiz:
    reviewAfterFailedQuiz,

  current_level:
    Math.max(
      1,
      toNumber(
        session.current_level,
        1
      )
    ),

  current_micro_level:
    Math.max(
      1,
      toNumber(
        session.current_micro_level,
        1
      )
    ),

  words_completed:
    Math.max(
      0,
      toNumber(
        session.words_completed,
        0
      )
    ),

  words_total:
    Math.max(
      1,
      toNumber(
        session.words_total,
        20
      )
    ),

  preferred_language:
    preferredLanguage,

  learning_session_id:
    toText(
      session.learning_session_id
    ),
};


/* =========================
   Output
========================= */

return [
  {
    json: {
      session_row:
        updatedSession,

      response,

      answer_correct:
        finalCorrect,

      learner_does_not_know:
        learnerDoesNotKnow,

      review_queue_ids:
        reviewQueueIds,

      difficult_item_ids:
        difficultItemIds,

      remaining_review_items:
        remainingReviewItems,

      review_completed:
