/*
  Prepare Quiz Start

  يعمل في حالتين:
  1) أول Quiz بعد إكمال المرحلة
  2) Retry Quiz بعد الرسوب والمراجعة

  الهدف:
  - تجهيز 5 أسئلة دائمًا متى كان لدينا 5 عناصر صالحة
  - في Retry نحاول اختيار أسئلة جديدة غير أسئلة المحاولة السابقة
  - إذا لم توجد 5 أسئلة جديدة، نكمّل العدد من أسئلة المحاولة السابقة
  - تصفير نتيجة المحاولة السابقة
  - تصفير difficult_item_ids حتى نسجل أخطاء المحاولة الجديدة فقط
*/


/* =========================
   Read Inputs
========================= */

const incoming =
  $input.first()?.json ?? {};

const context =
  $("Build Agent Context").first().json ?? {};


const incomingHasSession =
  Boolean(
    incoming.session_row &&
    typeof incoming.session_row === "object"
  );


const session = {
  ...(
    incomingHasSession
      ? incoming.session_row
      : context.session_row ?? {}
  ),
};


/* =========================
   Helpers
========================= */

function toText(value, fallback = "") {
  if (
    value === null ||
    value === undefined
  ) {
    return fallback;
  }

  const result =
    String(value).trim();

  return result || fallback;
}


function toNumber(value, fallback = 0) {
  const result =
    Number(value);

  return Number.isFinite(result)
    ? result
    : fallback;
}


function parseList(value) {
  if (Array.isArray(value)) {
    return [
      ...new Set(
        value
          .map((item) => toText(item))
          .filter(Boolean)
      ),
    ];
  }

  const raw =
    toText(value);

  if (!raw) {
    return [];
  }

  try {
    const parsed =
      JSON.parse(raw);

    if (Array.isArray(parsed)) {
      return [
        ...new Set(
          parsed
            .map((item) => toText(item))
            .filter(Boolean)
        ),
      ];
    }
  } catch {
    // continue
  }

  return [
    ...new Set(
      raw
        .split(",")
        .map((item) => item.trim())
        .filter(Boolean)
    ),
  ];
}


function shuffle(array) {
  const copy = [...array];

  for (
    let i = copy.length - 1;
    i > 0;
    i--
  ) {
    const j =
      Math.floor(
        Math.random() * (i + 1)
      );

    [
      copy[i],
      copy[j],
    ] = [
      copy[j],
      copy[i],
    ];
  }

  return copy;
}


function validIds(value) {
  return parseList(value)
    .filter(
      (id) =>
        id &&
        !id.startsWith("content-")
    );
}


/* =========================
   Detect Retry
========================= */

const incomingAction =
  toText(
    incoming.action
  );


const isRetryQuiz =
  incomingAction === "retry_quiz";


/* =========================
   Language
========================= */

const preferredLanguage =
  toText(
    incoming.response?.preferred_language ??
    context.preferred_language,
    "MSA"
  );


const isEnglish =
  preferredLanguage
    .toLowerCase() === "english";


/* =========================
   Current Level
========================= */

const currentLevel =
  Math.max(
    1,
    toNumber(
      session.current_level ??
      context.current_level,
      1
    )
  );


const currentMicroLevel =
  Math.max(
    1,
    toNumber(
      session.current_micro_level ??
      context.current_micro_level,
      1
    )
  );


/* =========================
   Available Learning Items
========================= */

/*
  completed = العناصر المكتملة رسميًا.
*/

const completedItemIds =
  validIds(
    session.completed_item_ids
  );


/*
  used = عناصر ظهرت للمستخدم خلال التعلم.

  نستخدمها لتوسيع مجموعة الأسئلة المتاحة.
*/

const usedItemIds =
  validIds(
    session.used_item_ids
  );


/*
  أسئلة الامتحان السابق.

  في Retry سنحاول استبعادها واختيار أسئلة جديدة أولًا.
*/

const previousQuizQuestionIds =
  validIds(
    session.quiz_question_ids
  );


/* =========================
   Build Learning Pool
========================= */

/*
  جميع العناصر التي يمكن استخدامها في الاختبار
  من العناصر المكتملة أو التي ظهرت أثناء التعلم.
*/

const learningPool = [
  ...new Set([
    ...completedItemIds,
    ...usedItemIds,
  ]),
];


/*
  نحفظ candidatePool أيضًا للـdebug
  وللاختبار الأول.
*/

const candidatePool =
  [...learningPool];


/* =========================
   Retry Alternatives
========================= */

/*
  في Retry نستبعد جميع أسئلة المحاولة السابقة
  ونبحث أولًا عن أسئلة جديدة.
*/

const previousQuestionSet =
  new Set(
    previousQuizQuestionIds
  );


const retryAlternativeIds =
  learningPool.filter(
    (id) =>
      !previousQuestionSet.has(id)
  );


/* =========================
   Need 5 Questions
========================= */

const REQUIRED_QUIZ_QUESTIONS = 5;


let quizQuestionIds = [];


/*
  Retry policy:

  1) نختار من الأسئلة الجديدة أولًا.
  2) إذا عندنا 5 أو أكثر، لا نستخدم أي سؤال قديم.
  3) إذا البدائل أقل من 5، نأخذها كلها
     ثم نكمّل فقط العدد الناقص من الأسئلة السابقة.
*/

if (isRetryQuiz) {

  const shuffledAlternatives =
    shuffle(
      retryAlternativeIds
    );


  quizQuestionIds =
    shuffledAlternatives.slice(
      0,
      REQUIRED_QUIZ_QUESTIONS
    );


  const questionsStillNeeded =
    REQUIRED_QUIZ_QUESTIONS -
    quizQuestionIds.length;


  if (questionsStillNeeded > 0) {

    const selectedSet =
      new Set(
        quizQuestionIds
      );


    const fallbackPreviousQuestions =
      shuffle(
        previousQuizQuestionIds.filter(
          (id) =>
            !selectedSet.has(id)
        )
      );


    quizQuestionIds.push(
      ...fallbackPreviousQuestions.slice(
        0,
        questionsStillNeeded
      )
    );
  }

} else {

  /*
    أول محاولة:
    نختار 5 عشوائيًا من العناصر التي تعلّمها المستخدم.
  */

  quizQuestionIds =
    shuffle(
      candidatePool
    )
      .slice(
        0,
        REQUIRED_QUIZ_QUESTIONS
      );
}


/*
  حماية إضافية من أي تكرار غير مقصود.
*/

quizQuestionIds = [
  ...new Set(
    quizQuestionIds
  ),
];


/* =========================
   Quiz Availability
========================= */

const quizTotalQuestions =
  quizQuestionIds.length;


const firstQuestionId =
  quizQuestionIds[0] ?? "";


const hasQuizQuestions =
  quizTotalQuestions ===
    REQUIRED_QUIZ_QUESTIONS &&
  Boolean(firstQuestionId);


/* =========================
   Time
========================= */

const now =
  new Date().toISOString();


/* =========================
   Quiz Unavailable
========================= */

if (!hasQuizQuestions) {

  const reply =
    isEnglish
      ? (
          `I couldn't prepare the quiz yet. ` +
          `I found only ${quizTotalQuestions} valid learning items, ` +
          `but the quiz requires 5.`
        )
      : (
          `لم أتمكن من تجهيز الاختبار حاليًا. ` +
          `وجدت ${quizTotalQuestions} عناصر تعليمية صالحة فقط، ` +
          `بينما يحتاج الاختبار إلى 5 عناصر.`
        );


  const unavailableSession = {
    ...session,

    current_level:
      currentLevel,

    current_micro_level:
      currentMicroLevel,

    quiz_active:
      false,

    quiz_question_index:
      0,

    quiz_total_questions:
      0,

    quiz_score:
      0,

    quiz_correct_answers:
      0,

    quiz_wrong_answers:
      0,

    quiz_question_ids:
      JSON.stringify([]),

    quiz_answered_item_ids:
      JSON.stringify([]),

    quiz_current_item_id:
      "",

    quiz_current_levantine:
      "",

    quiz_current_msa:
      "",

    quiz_current_english:
      "",

    quiz_passed:
      false,

    current_step:
      "quiz_unavailable",

    last_agent_action:
      "quiz_unavailable",

    last_agent_reason:
      "not_enough_valid_quiz_items",

    updated_at:
      now,

    last_activity_at:
      now,
  };


  return [
    {
      json: {
        has_quiz_questions:
          false,

        is_retry_quiz:
          isRetryQuiz,

        quiz_target_id:
          "",

        quiz_question_ids:
          [],

        quiz_total_questions:
          0,

        session_row:
          unavailableSession,

        response: {
          success:
            false,

          mode:
            "learning",

          action:
            "quiz_unavailable",

          reply,

          suggested_actions:
            [],

          current_level:
            currentLevel,

          current_micro_level:
            currentMicroLevel,
        },

        debug: {
          completed_valid:
            completedItemIds.length,

          previous_quiz_valid:
            previousQuizQuestionIds.length,

          used_valid:
            usedItemIds.length,

          candidate_pool:
            candidatePool.length,

          retry_alternatives:
            retryAlternativeIds.length,
        },
      },
    },
  ];
}


/* =========================
   Start New Quiz Attempt
========================= */

const updatedSession = {
  ...session,

  current_level:
    currentLevel,

  current_micro_level:
    currentMicroLevel,

  /*
    نمسح أخطاء المحاولة السابقة.

    Prepare Quiz Answer Result
    سيضيف أخطاء المحاولة الجديدة.
  */
  difficult_item_ids:
    JSON.stringify([]),

  quiz_active:
    true,

  quiz_question_index:
    0,

  quiz_total_questions:
    REQUIRED_QUIZ_QUESTIONS,

  quiz_score:
    0,

  quiz_correct_answers:
    0,

  quiz_wrong_answers:
    0,

  quiz_question_ids:
    JSON.stringify(
      quizQuestionIds
    ),

  quiz_answered_item_ids:
    JSON.stringify([]),

  quiz_current_item_id:
    "",

  quiz_current_levantine:
    "",

  quiz_current_msa:
    "",

  quiz_current_english:
    "",

  quiz_started_at:
    now,

  quiz_passed:
    false,

  current_step:
    "quiz_loading",

  review_active:
    false,

  review_recommended:
    false,

  last_agent_action:
    isRetryQuiz
      ? "retry_quiz"
      : "quiz_start",

  last_agent_reason:
    isRetryQuiz
      ? "learner_requested_quiz_retry"
      : "micro_level_learning_completed",

  updated_at:
    now,

  last_activity_at:
    now,
};


/* =========================
   Intro
========================= */

const introReply =
  isEnglish
    ? (
        isRetryQuiz
          ? (
              "You're ready to try the quiz again. " +
              "It has 5 questions, and you need at least 4 correct answers to move to the next stage."
            )
          : (
              "You've finished this stage. " +
              "Now you'll take a short 5-question quiz. " +
              "You need at least 4 correct answers to move to the next stage."
            )
      )
    : (
        isRetryQuiz
          ? (
              "أصبحت جاهزًا لإعادة الاختبار. " +
              "يتكوّن من 5 أسئلة، وتحتاج إلى 4 إجابات صحيحة على الأقل للانتقال إلى المرحلة التالية."
            )
          : (
              "أنهيت تعلّم هذه المرحلة. " +
              "الآن لديك اختبار قصير من 5 أسئلة، وتحتاج إلى 4 إجابات صحيحة على الأقل للانتقال إلى المرحلة التالية."
            )
      );


/* =========================
   Output
========================= */

return [
  {
    json: {
      has_quiz_questions:
        true,

      is_retry_quiz:
        isRetryQuiz,

      quiz_target_id:
        firstQuestionId,

      quiz_question_ids:
        quizQuestionIds,

      quiz_total_questions:
        REQUIRED_QUIZ_QUESTIONS,

      session_row:
        updatedSession,

      response: {
        success:
          true,

        mode:
          "learning",

        action:
          isRetryQuiz
            ? "retry_quiz"
            : "quiz_start",

        reply:
          introReply,

        suggested_actions:
          [],

        current_level:
          currentLevel,

        current_micro_level:
          currentMicroLevel,

        quiz_total_questions:
          REQUIRED_QUIZ_QUESTIONS,
      },

      debug: {
        completed_valid:
          completedItemIds.length,

        previous_quiz_valid:
          previousQuizQuestionIds.length,

        used_valid:
          usedItemIds.length,

        candidate_pool:
          candidatePool.length,

        retry_alternatives:
          retryAlternativeIds.length,

        selected_quiz_ids:
          quizQuestionIds,
