    },
  },
];

/*
  Prepare Quiz Question

  يحوّل عنصر Chroma إلى سؤال امتحان للمستوى الفرعي،
  بدون إظهار الإجابة الصحيحة.

  عند السؤال الأول فقط:
  - يشرح أن الامتحان 5 أسئلة
  - النجاح يحتاج 4 من 5
  - يطلب من المستخدم الإجابة من الذاكرة
*/

const quizStart =
  $("Prepare Quiz Start").first().json ?? {};

const context =
  $("Build Agent Context").first().json ?? {};

const session = {
  ...(quizStart.session_row ?? {}),
};

const chromaResult =
  $input.first().json ?? {};


/* =========================
   Helpers
========================= */

function toText(value, fallback = "") {
  if (
    value === null ||
    value === undefined
  ) {
    return fallback;
  }

  if (Array.isArray(value)) {
    const firstValue =
      value.find(
        (item) =>
          item !== null &&
          item !== undefined &&
          String(item).trim()
      );

    return firstValue === undefined
      ? fallback
      : String(firstValue).trim();
  }

  const result =
    String(value).trim();

  return result || fallback;
}

function toNumber(value, fallback = 0) {
  const result =
    Number(value);

  return Number.isFinite(result)
    ? result
    : fallback;
}

function escapeRegex(value) {
  return String(value).replace(
    /[.*+?^${}()|[\]\\]/g,
    "\\$&"
  );
}


/* =========================
   Read Chroma Result
========================= */

function findMetadata(result) {
  if (
    result.document?.metadata &&
    typeof result.document.metadata === "object"
  ) {
    return result.document.metadata;
  }

  if (
    result.metadata &&
    typeof result.metadata === "object"
  ) {
    return result.metadata;
  }

  if (
    Array.isArray(result.metadatas) &&
    result.metadatas[0]
  ) {
    return result.metadatas[0];
  }

  return {};
}

function findContent(result) {
  return toText(
    result.document?.pageContent ??
    result.document?.content ??
    result.pageContent ??
    result.content ??
    result.text ??
    result.documents?.[0]
  );
}

function valueFromContent(
  content,
  labels
) {
  const source =
    toText(content);

  if (!source) {
    return "";
  }

  for (const label of labels) {
    const escapedLabel =
      escapeRegex(label);

    const pattern =
      new RegExp(
        `(?:^|\\n)\\s*${escapedLabel}\\s*[:：-]\\s*(.+?)(?=\\n|$)`,
        "i"
      );

    const match =
      source.match(pattern);

    if (match) {
      return toText(
        match[1]
      );
    }
  }

  return "";
}


/* =========================
   Extract Quiz Item
========================= */

const metadata =
  findMetadata(chromaResult);

const content =
  findContent(chromaResult);

const itemId =
  toText(
    metadata.item_id ??
    metadata.original_id ??
    metadata.source_id ??
    quizStart.quiz_target_id
  );

const sourceId =
  toText(
    metadata.source_id ??
    metadata.original_id ??
    itemId
  );

const levantine =
  toText(
    metadata.levantine ??
    valueFromContent(
      content,
      [
        "الشامية",
        "Levantine",
        "Levantine Arabic",
      ]
    )
  );

const msa =
  toText(
    metadata.msa ??
    valueFromContent(
      content,
      [
        "الفصحى",
        "MSA",
        "Modern Standard Arabic",
      ]
    )
  );

const english =
  toText(
    metadata.english ??
    valueFromContent(
      content,
      [
        "الإنجليزية",
        "English",
        "Meaning",
      ]
    )
  );

const topic =
  toText(
    metadata.topic ??
    valueFromContent(
      content,
      [
        "الموضوع",
        "Topic",
      ]
    )
  );


/* =========================
   Level Information
========================= */

const currentLevel =
  Math.max(
    1,
    toNumber(
      session.current_level ??
      context.current_level ??
      metadata.stage ??
      metadata.learning_level,
      1
    )
  );

const currentMicroLevel =
  Math.max(
    1,
    toNumber(
      session.current_micro_level ??
      context.current_micro_level ??
      metadata.micro_level,
      1
    )
  );


/* =========================
   Quiz Progress
========================= */

const questionIndex =
  Math.max(
    1,
    toNumber(
      session.quiz_question_index,
      1
    )
  );

const totalQuestions =
  Math.max(
    1,
    toNumber(
      session.quiz_total_questions,
      5
    )
  );

const isFirstQuestion =
  questionIndex === 1;


/* =========================
   Language
========================= */

const preferredLanguage =
  toText(
    quizStart.preferred_language ??
    quizStart.response?.preferred_language ??
    session.preferred_language ??
    context.preferred_language,
    "MSA"
  );

const isEnglish =
  preferredLanguage
    .toLowerCase() === "english";

const isPhrase =
  levantine
    .split(/\s+/)
    .filter(Boolean)
    .length > 1;


/* =========================
   Build Quiz Question
========================= */

let questionText;

if (!levantine) {
  questionText = isEnglish
    ? "The micro-level quiz question could not be loaded."
    : "تعذّر تحميل سؤال امتحان المستوى الفرعي.";
} else if (isEnglish) {
  questionText = isPhrase
    ? (
        `Micro-Level Quiz — Question ${questionIndex} of ${totalQuestions}\n` +
        `What does the phrase «${levantine}» mean in English?`
      )
    : (
        `Micro-Level Quiz — Question ${questionIndex} of ${totalQuestions}\n` +
        `What does the word «${levantine}» mean in English?`
      );
} else {
  questionText = isPhrase
    ? (
        `امتحان المستوى الفرعي — السؤال ${questionIndex} من ${totalQuestions}\n` +
        `ما معنى العبارة «${levantine}» بالفصحى؟`
      )
    : (
        `امتحان المستوى الفرعي — السؤال ${questionIndex} من ${totalQuestions}\n` +
        `ما معنى كلمة «${levantine}» بالفصحى؟`
      );
}


/* =========================
   First Question Intro
========================= */

let reply =
  questionText;

if (
  levantine &&
  isFirstQuestion
) {
  if (isEnglish) {
    reply =
      `Great work! You finished the learning part of this stage.\n` +
      `Now you'll take a short quiz with ${totalQuestions} questions.\n` +
      `You need at least 4 out of 5 correct answers to pass and move to the next stage.\n` +
      `Try to answer from memory.\n\n` +
      questionText;
  } else {
    reply =
      `أحسنت! أنهيت جزء التعلّم في هذه المرحلة ✅\n` +
      `الآن عندك اختبار قصير من ${totalQuestions} أسئلة.\n` +
      `تحتاج إلى 4 إجابات صحيحة من أصل 5 للنجاح والانتقال إلى المرحلة التالية.\n` +
      `حاول الإجابة من ذاكرتك.\n\n` +
      questionText;
  }
}


/* =========================
   Update Session
========================= */

const now =
  new Date().toISOString();

const updatedSession = {
  ...session,

  current_level:
    currentLevel,

  current_micro_level:
    currentMicroLevel,

  quiz_active:
    true,

  quiz_current_item_id:
    itemId,

  quiz_current_levantine:
    levantine,

  quiz_current_msa:
    msa,

  quiz_current_english:
    english,

  current_step:
    "quiz_question",

  last_agent_action:
    "quiz_question",

  last_agent_reason:
    "micro_level_quiz_question_loaded",

  updated_at:
    now,

  last_activity_at:
    now,
};


/* =========================
   Frontend Response
========================= */

const response = {
  success:
    Boolean(
      itemId &&
      levantine
    ),

  mode:
    "learning",

  action:
    "quiz_question",

  reply,

  suggested_actions:
    [],

  quiz_active:
    true,

  quiz_question_index:
    questionIndex,

  quiz_total_questions:
    totalQuestions,

  current_level:
    currentLevel,

  current_micro_level:
    currentMicroLevel,

  preferred_language:
    preferredLanguage,

  learning_session_id:
    toText(
      session.learning_session_id
    ),
};


/* =========================
   Output
========================= */

return [
  {
    json: {
      session_row:
        updatedSession,

      response,

      quiz_item: {
        item_id:
          itemId,

        source_id:
          sourceId,

        levantine,

        msa,

        english,

        topic,

        learning_level:
          currentLevel,

        micro_level:
          currentMicroLevel,
      },
    },
  },
];

parameters.text:
={{
