  })
}}

parameters.jsCode:
/*
  Prepare Quiz Answer Result

  المسؤوليات:
  - قراءة نتيجة Quiz Answer Evaluator
  - تقييم الإجابة الحالية
  - تحديث correct / wrong
  - تسجيل السؤال كمُجاب عليه
  - إضافة أخطاء الكويز إلى difficult_item_ids
  - إزالة العنصر من difficult_item_ids إذا كانت الإجابة صحيحة
  - زيادة quiz_question_index
  - تحديد السؤال التالي
  - حساب النتيجة النهائية
*/


/* =========================
   Read Nodes
========================= */

const context =
  $("Build Agent Context").first().json ?? {};

const session = {
  ...(context.session_row ?? {}),
};

const evaluatorInput =
  $input.first()?.json ?? {};


/* =========================
   Helpers
========================= */

function toText(value, fallback = "") {
  if (
    value === null ||
    value === undefined
  ) {
    return fallback;
  }

  const result =
    String(value).trim();

  return result || fallback;
}


function toNumber(value, fallback = 0) {
  const result =
    Number(value);

  return Number.isFinite(result)
    ? result
    : fallback;
}


function toBoolean(value, fallback = false) {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value === "number") {
    return value === 1;
  }

  const text =
    toText(value)
      .toLowerCase();

  if (
    [
      "true",
      "1",
      "yes",
      "correct",
    ].includes(text)
  ) {
    return true;
  }

  if (
    [
      "false",
      "0",
      "no",
      "incorrect",
    ].includes(text)
  ) {
    return false;
  }

  return fallback;
}


function parseList(value) {
  if (Array.isArray(value)) {
    return [
      ...new Set(
        value
          .map((item) => toText(item))
          .filter(Boolean)
      ),
    ];
  }

  const raw =
    toText(value);

  if (!raw) {
    return [];
  }

  try {
    const parsed =
      JSON.parse(raw);

    if (Array.isArray(parsed)) {
      return [
        ...new Set(
          parsed
            .map((item) => toText(item))
            .filter(Boolean)
        ),
      ];
    }
  } catch {
    // continue
  }

  return [
    ...new Set(
      raw
        .split(",")
        .map((item) => item.trim())
        .filter(Boolean)
    ),
  ];
}


function parseEvaluator(input) {
  let raw =
    input?.output ??
    input?.text ??
    input?.response ??
    input;

  if (
    raw &&
    typeof raw === "object"
  ) {
    return raw;
  }

  raw =
    toText(raw);

  if (!raw) {
    return {};
  }

  raw = raw
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/```$/i, "")
    .trim();

  try {
    return JSON.parse(raw);
  } catch {
    const firstBrace =
      raw.indexOf("{");

    const lastBrace =
      raw.lastIndexOf("}");

    if (
      firstBrace !== -1 &&
      lastBrace !== -1 &&
      lastBrace > firstBrace
    ) {
      try {
        return JSON.parse(
          raw.slice(
            firstBrace,
            lastBrace + 1
          )
        );
      } catch {
        return {};
      }
    }

    return {};
  }
}


function normalizeArabic(value) {
  return toText(value)
    .toLowerCase()
    .replace(/[ًٌٍَُِّْـ]/g, "")
    .replace(/[أإآ]/g, "ا")
    .replace(/ى/g, "ي")
    .replace(/ة/g, "ه")
    .replace(/[؟?!.,،؛:]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}


/* =========================
   Language
========================= */

const preferredLanguage =
  toText(
    context.preferred_language,
    "MSA"
  );

const isEnglish =
  preferredLanguage
    .toLowerCase() === "english";


/* =========================
   Evaluator Result
========================= */

const evaluation =
  parseEvaluator(
    evaluatorInput
  );


const isCorrect =
  toBoolean(
    evaluation.correct ??
    evaluation.is_correct ??
    evaluation.semantic_correct,
    false
  );


/* =========================
   Learner Answer
========================= */

const learnerAnswer =
  toText(
    context.user_message
  );

const normalizedAnswer =
  normalizeArabic(
    learnerAnswer
  );


/* =========================
   Don't Know Detection
========================= */

const dontKnowArabic = [
  "لا أعلم",
  "لا اعلم",
  "لا أعرف",
  "لا اعرف",
  "ما بعرف",
  "ما أعرف",
  "ما اعرف",
  "مش عارف",
  "مش عارفة",
  "مش عارفه",
  "لا أدري",
  "لا ادري",
  "مش متأكد",
  "مش متاكد",
  "مش متأكدة",
  "مش متاكده",
];


const dontKnowEnglish = [
  "i don't know",
  "i dont know",
  "don't know",
  "dont know",
  "not sure",
  "i'm not sure",
  "im not sure",
];


const learnerDoesNotKnow =
  dontKnowArabic.some(
    (phrase) =>
      normalizedAnswer ===
      normalizeArabic(phrase)
  ) ||
  dontKnowEnglish.some(
    (phrase) =>
      learnerAnswer
        .toLowerCase()
        .trim() === phrase
  );


const finalCorrect =
  learnerDoesNotKnow
    ? false
    : isCorrect;


/* =========================
   Correct Answer
========================= */

const canonicalAnswer =
  isEnglish
    ? toText(
        session.quiz_current_english ??
        evaluation.canonical_answer ??
        evaluation.correct_answer
      )
    : toText(
        session.quiz_current_msa ??
        evaluation.canonical_answer ??
        evaluation.correct_answer
      );


/* =========================
   Quiz State
========================= */

const quizQuestionIds =
  parseList(
    session.quiz_question_ids
  );


let answeredItemIds =
  parseList(
    session.quiz_answered_item_ids
  );


let difficultItemIds =
  parseList(
    session.difficult_item_ids
  );


const currentItemId =
  toText(
    session.quiz_current_item_id
  );


const currentQuestionIndex =
  Math.max(
    0,
    toNumber(
      session.quiz_question_index,
      0
    )
  );


const quizTotalQuestions =
  Math.max(
    1,
    toNumber(
      session.quiz_total_questions,
      quizQuestionIds.length || 5
    )
  );


/* =========================
   Register Current Answer
========================= */

if (
  currentItemId &&
  !answeredItemIds.includes(
    currentItemId
  )
) {
  answeredItemIds.push(
    currentItemId
  );
}


/* =========================
   Update Difficult Items
========================= */

/*
  إذا أخطأ المستخدم أو قال "لا أعلم":
  نضيف السؤال إلى difficult_item_ids.

  إذا أجاب بشكل صحيح:
  نحذفه من difficult_item_ids إن كان موجودًا.
*/

if (currentItemId) {
  if (finalCorrect) {
    difficultItemIds =
      difficultItemIds.filter(
        (id) =>
          id !== currentItemId
      );
  } else {
    if (
      !difficultItemIds.includes(
        currentItemId
      )
    ) {
      difficultItemIds.push(
        currentItemId
      );
    }
  }
}


/* =========================
   Update Score Counters
========================= */

let quizCorrectAnswers =
  Math.max(
    0,
    toNumber(
      session.quiz_correct_answers,
      0
    )
  );


let quizWrongAnswers =
  Math.max(
    0,
    toNumber(
      session.quiz_wrong_answers,
      0
    )
  );


if (finalCorrect) {
  quizCorrectAnswers += 1;
} else {
  quizWrongAnswers += 1;
}


/* =========================
   Next Question Index
========================= */

const nextQuestionIndex =
  currentQuestionIndex + 1;


const hasNextQuestion =
  nextQuestionIndex <
  quizTotalQuestions;


/* =========================
   Next Question ID
========================= */

const nextQuestionId =
  hasNextQuestion
    ? toText(
        quizQuestionIds[
          nextQuestionIndex
        ]
      )
    : "";


/* =========================
   Quiz Finished
========================= */

const quizFinished =
  !hasNextQuestion;


/* =========================
   Score Percentage
========================= */

const quizScore =
  Math.round(
    (
      quizCorrectAnswers /
      quizTotalQuestions
    ) * 100
  );


const quizPassed =
  quizFinished &&
  quizScore >= 80;


/* =========================
   Feedback
========================= */

let feedbackReply = "";


if (isEnglish) {
  if (finalCorrect) {
    feedbackReply =
      "Correct ✅";
  } else if (
    learnerDoesNotKnow
  ) {
    feedbackReply =
      `No problem. The correct meaning is: ${canonicalAnswer}.`;
  } else {
    feedbackReply =
      `Not quite. The correct meaning is: ${canonicalAnswer}.`;
  }
} else {
  if (finalCorrect) {
    feedbackReply =
      "إجابة صحيحة ✅";
  } else if (
    learnerDoesNotKnow
  ) {
    feedbackReply =
      `لا بأس، المعنى الصحيح هو: ${canonicalAnswer}.`;
  } else {
    feedbackReply =
      `الإجابة ليست صحيحة تمامًا. المعنى الصحيح هو: ${canonicalAnswer}.`;
  }
}


/* =========================
   Time
========================= */

const now =
  new Date().toISOString();


/* =========================
   Updated Session
========================= */

const updatedSession = {
  ...session,

  difficult_item_ids:
    JSON.stringify(
      difficultItemIds
    ),

  quiz_active:
    !quizFinished,

  quiz_question_index:
    nextQuestionIndex,

  quiz_total_questions:
    quizTotalQuestions,

  quiz_score:
    quizScore,

  quiz_correct_answers:
    quizCorrectAnswers,

  quiz_wrong_answers:
    quizWrongAnswers,

  quiz_question_ids:
    JSON.stringify(
      quizQuestionIds
    ),

  quiz_answered_item_ids:
    JSON.stringify(
      answeredItemIds
    ),

  quiz_passed:
    quizFinished
      ? quizPassed
      : false,

  current_step:
    hasNextQuestion
      ? "quiz_loading"
      : "quiz_completed",

  last_agent_action:
    hasNextQuestion
      ? "quiz_next_question"
      : "quiz_completed",

  last_agent_reason:
    learnerDoesNotKnow
      ? "quiz_answer_unknown"
      : finalCorrect
        ? "quiz_answer_correct"
        : "quiz_answer_incorrect",

  updated_at:
    now,

  last_activity_at:
    now,
};


/* =========================
   Completed At
========================= */

if (quizFinished) {
  updatedSession.quiz_completed_at =
    now;
}


/* =========================
   Output
========================= */

return [
  {
    json: {
      session_row:
        updatedSession,

      feedback_reply:
        feedbackReply,

      answer_correct:
        finalCorrect,

      learner_does_not_know:
        learnerDoesNotKnow,

      canonical_answer:
        canonicalAnswer,

      difficult_item_ids:
        difficultItemIds,

      current_question_index:
        currentQuestionIndex,

      next_question_index:
        nextQuestionIndex,

      quiz_total_questions:
        quizTotalQuestions,

      quiz_correct_answers:
        quizCorrectAnswers,

      quiz_wrong_answers:
        quizWrongAnswers,

      quiz_score:
        quizScore,

      quiz_passed:
        quizPassed,

      quiz_finished:
        quizFinished,

      has_next_question:
        hasNextQuestion,

      quiz_next_target_id:
        nextQuestionId,

      response: {
        success:
          true,

        mode:
          "learning",

        action:
          hasNextQuestion
            ? "quiz_next_question"
            : "quiz_completed",

        reply:
          feedbackReply,

        current_level:
          Math.max(
            1,
            toNumber(
              session.current_level,
              1
            )
          ),

        current_micro_level:
          Math.max(
            1,
            toNumber(
              session.current_micro_level,
              1
            )
          ),

        quiz_question_index:
          nextQuestionIndex,

        quiz_total_questions:
          quizTotalQuestions,

        quiz_score:
          quizScore,
      },
    },
  },
];

/*
  Prepare Next Quiz Question

  يحمّل السؤال التالي من Chroma،
  ويعرض نتيجة السؤال السابق،
  ثم يطرح سؤالًا جديدًا من امتحان المستوى الفرعي
  بدون كشف الإجابة الصحيحة.

  مهم:
  quiz_question_index داخل session هو ZERO-BASED:
  0 = السؤال الأول
  1 = السؤال الثاني
  2 = السؤال الثالث
  ...

  أما الرقم الظاهر للمستخدم فهو:
  quiz_question_index + 1
*/

const answerResult =
  $("Prepare Quiz Answer Result").first().json ?? {};

const context =
  $("Build Agent Context").first().json ?? {};

const session = {
  ...(answerResult.session_row ?? {}),
};

const chromaResult =
  $input.first().json ?? {};


/* =========================
   Helpers
========================= */

function toText(value, fallback = "") {
  if (
    value === null ||
    value === undefined
  ) {
    return fallback;
  }

  if (Array.isArray(value)) {
    const firstValue =
      value.find(
        (item) =>
          item !== null &&
          item !== undefined &&
          String(item).trim()
      );

    return firstValue === undefined
      ? fallback
      : String(firstValue).trim();
  }

  const result =
    String(value).trim();

  return result || fallback;
}

function toNumber(value, fallback = 0) {
  const result =
    Number(value);

  return Number.isFinite(result)
    ? result
    : fallback;
}

function escapeRegex(value) {
  return String(value).replace(
    /[.*+?^${}()|[\]\\]/g,
    "\\$&"
  );
}


/* =========================
   Read Chroma Result
========================= */

function findMetadata(result) {
  if (
    result.document?.metadata &&
    typeof result.document.metadata === "object"
  ) {
    return result.document.metadata;
  }

  if (
    result.metadata &&
    typeof result.metadata === "object"
  ) {
    return result.metadata;
  }

  if (
    Array.isArray(result.metadatas) &&
    result.metadatas[0]
  ) {
    return result.metadatas[0];
  }

  return {};
}

function findContent(result) {
  return toText(
    result.document?.pageContent ??
    result.document?.content ??
    result.pageContent ??
    result.content ??
    result.text ??
    result.documents?.[0]
  );
}

function valueFromContent(
  content,
  labels
) {
  const source =
    toText(content);

  if (!source) {
    return "";
  }

  for (const label of labels) {
    const escapedLabel =
      escapeRegex(label);

    const pattern =
      new RegExp(
        `(?:^|\\n)\\s*${escapedLabel}\\s*[:：-]\\s*(.+?)(?=\\n|$)`,
        "i"
      );

    const match =
      source.match(pattern);

    if (match) {
      return toText(
        match[1]
      );
    }
  }

  return "";
}


/* =========================
   Extract Next Quiz Item
========================= */

const metadata =
  findMetadata(chromaResult);

const content =
  findContent(chromaResult);

const itemId =
  toText(
    metadata.item_id ??
    metadata.original_id ??
    metadata.source_id ??
    answerResult.quiz_next_target_id ??
    session.quiz_current_item_id
  );

const sourceId =
  toText(
    metadata.source_id ??
    metadata.original_id ??
    itemId
  );

const levantine =
  toText(
    metadata.levantine ??
    valueFromContent(
      content,
      [
        "الشامية",
        "Levantine",
        "Levantine Arabic",
      ]
    )
  );

const msa =
  toText(
    metadata.msa ??
    valueFromContent(
      content,
      [
        "الفصحى",
        "MSA",
        "Modern Standard Arabic",
      ]
    )
  );

const english =
  toText(
    metadata.english ??
    valueFromContent(
      content,
      [
        "الإنجليزية",
        "English",
        "Meaning",
      ]
    )
  );

const topic =
  toText(
    metadata.topic ??
    valueFromContent(
      content,
      [
        "الموضوع",
        "Topic",
      ]
    )
  );


/* =========================
   Level Information
========================= */

const currentLevel =
  Math.max(
    1,
    toNumber(
      session.current_level ??
      context.current_level ??
      metadata.stage ??
      metadata.learning_level,
      1
    )
  );

const currentMicroLevel =
  Math.max(
    1,
    toNumber(
      session.current_micro_level ??
      context.current_micro_level ??
      metadata.micro_level,
      1
    )
  );


/* =========================
   Quiz Progress
========================= */

const totalQuestions =
  Math.max(
    1,
    toNumber(
      answerResult.quiz_total_questions ??
      session.quiz_total_questions,
      5
    )
  );

/*
  هذا هو الـindex الداخلي ZERO-BASED.

  Prepare Quiz Answer Result
  زاده أصلًا قبل الوصول إلى هذه العقدة.

  مثال:
  السؤال الأول انتهى
  → next_question_index = 1
  → هذا يعني السؤال الثاني.
*/
const questionIndex =
  Math.max(
    0,
    toNumber(
      answerResult.next_question_index ??
      session.quiz_question_index,
      1
    )
  );

/*
  هذا الرقم فقط للعرض للمستخدم.
*/
const questionNumber =
  questionIndex + 1;

const feedbackReply =
  toText(
    answerResult.feedback_reply
  );


/* =========================
   Language
========================= */

const preferredLanguage =
  toText(
    answerResult.preferred_language ??
    answerResult.response?.preferred_language ??
    session.preferred_language ??
    context.preferred_language,
    "MSA"
  );

const isEnglish =
  preferredLanguage
    .toLowerCase() === "english";

const isPhrase =
  levantine
    .split(/\s+/)
    .filter(Boolean)
    .length > 1;


/* =========================
   Build Next Question
========================= */

let questionText;

if (!levantine) {
  questionText =
    isEnglish
      ? "The next micro-level quiz question could not be loaded."
      : "تعذّر تحميل سؤال امتحان المستوى الفرعي التالي.";
} else if (isEnglish) {
  questionText =
    isPhrase
      ? (
          `Micro-Level Quiz — Question ${questionNumber} of ${totalQuestions}\n` +
          `What does the phrase «${levantine}» mean in English?`
        )
      : (
          `Micro-Level Quiz — Question ${questionNumber} of ${totalQuestions}\n` +
          `What does the word «${levantine}» mean in English?`
        );
} else {
  questionText =
    isPhrase
      ? (
          `امتحان المستوى الفرعي — السؤال ${questionNumber} من ${totalQuestions}\n` +
          `ما معنى العبارة «${levantine}» بالفصحى؟`
        )
      : (
          `امتحان المستوى الفرعي — السؤال ${questionNumber} من ${totalQuestions}\n` +
          `ما معنى كلمة «${levantine}» بالفصحى؟`
        );
}

const reply =
  feedbackReply
    ? `${feedbackReply}\n\n${questionText}`
    : questionText;


/* =========================
   Update Session
========================= */

const now =
  new Date().toISOString();

const updatedSession = {
  ...session,

  current_level:
    currentLevel,

  current_micro_level:
    currentMicroLevel,

  preferred_language:
    preferredLanguage,

  quiz_active:
    true,

  /*
    مهم:
    نخزن الـZERO-BASED index،
    مش الرقم الظاهر للمستخدم.
  */
  quiz_question_index:
    questionIndex,

  quiz_total_questions:
    totalQuestions,

  quiz_current_item_id:
    itemId,

  quiz_current_levantine:
    levantine,

  quiz_current_msa:
    msa,

  quiz_current_english:
    english,

  current_step:
    "quiz_question",

  last_agent_action:
    "quiz_next_question",

  last_agent_reason:
    "next_micro_level_quiz_question_loaded",

  updated_at:
    now,

  last_activity_at:
    now,
};


/* =========================
   Frontend Response
========================= */

const response = {
  success:
    Boolean(
      itemId &&
      levantine
    ),

  mode:
    "learning",

  action:
    "quiz_question",

  reply,

  suggested_actions:
    [],

  quiz_active:
    true,

  /*
    نخلي القيمة الداخلية كما هي.
    الرقم الظاهر موجود داخل reply.
  */
  quiz_question_index:
    questionIndex,

  quiz_question_number:
    questionNumber,

  quiz_total_questions:
    totalQuestions,

  quiz_score:
    toNumber(
      session.quiz_score,
      0
    ),

  quiz_correct_answers:
    toNumber(
      session.quiz_correct_answers,
      0
    ),

  quiz_wrong_answers:
    toNumber(
      session.quiz_wrong_answers,
      0
    ),

  current_level:
    currentLevel,

  current_micro_level:
    currentMicroLevel,

  preferred_language:
    preferredLanguage,

  learning_session_id:
    toText(
      session.learning_session_id
    ),
};


/* =========================
   Output
========================= */

return [
  {
    json: {
      session_row:
        updatedSession,

      response,

      quiz_item: {
        item_id:
          itemId,

        source_id:
          sourceId,

        levantine,

        msa,

        english,

        topic,

        learning_level:
          currentLevel,

        micro_level:
          currentMicroLevel,
      },

      quiz_question_index:
        questionIndex,

      quiz_question_number:
        questionNumber,
    },
  },
];

/*
  Prepare Quiz Final Result

  نظام الانتقال:
  - بعد النجاح في Micro Level 1 → Micro Level 2
  - بعد النجاح في Micro Level 2 → Micro Level 3
  - بعد النجاح في Micro Level 3 → Micro Level 4
  - بعد النجاح في Micro Level 4:
      Learning Level يزيد واحد
      Micro Level يعود إلى 1

  عند الرسوب:
  - يبقى المستخدم في نفس المستوى الرئيسي والفرعي
  - يوصى بالمراجعة
*/

const answerResult =
  $("Prepare Quiz Answer Result").first().json ?? {};

const context =
  $("Build Agent Context").first().json ?? {};

const session = {
  ...(answerResult.session_row ?? {}),
};


/* =========================
   Helpers
========================= */

function toText(value, fallback = "") {
  if (
    value === null ||
    value === undefined
  ) {
    return fallback;
  }

  const result =
    String(value).trim();

  return result || fallback;
}

function toNumber(value, fallback = 0) {
  const result =
    Number(value);

  return Number.isFinite(result)
    ? result
    : fallback;
}

function toBoolean(value, fallback = false) {
  if (typeof value === "boolean") {
    return value;
  }

  const normalized =
    toText(value)
      .toLowerCase();

  if (
    [
      "true",
      "1",
      "yes",
    ].includes(normalized)
  ) {
    return true;
  }

  if (
    [
      "false",
      "0",
      "no",
    ].includes(normalized)
  ) {
    return false;
  }

  return fallback;
}


/* =========================
   Language
========================= */

const preferredLanguage =
  toText(
    answerResult.preferred_language ??
    answerResult.response?.preferred_language ??
    session.preferred_language ??
    context.preferred_language,
    "MSA"
  );

const isEnglish =
  preferredLanguage
    .toLowerCase() === "english";


/* =========================
   Current Levels
========================= */

const currentLevel =
  Math.max(
    1,
    toNumber(
      session.current_level,
      1
    )
  );

const currentMicroLevel =
  Math.max(
    1,
    toNumber(
      session.current_micro_level,
      1
    )
  );

/*
  عدد المستويات الفرعية داخل كل مستوى رئيسي.
*/
const maxMicroLevel = 4;
const maxLearningLevel = 6;
/*
  هل المستخدم أنهى آخر مستوى فرعي؟
*/
const isLastMicroLevel =
  currentMicroLevel >=
  maxMicroLevel;


/* =========================
   Quiz Result
========================= */

const totalQuestions =
  Math.max(
    1,
    toNumber(
      answerResult.quiz_total_questions ??
      session.quiz_total_questions,
      5
    )
  );

const correctAnswers =
  Math.max(
    0,
    toNumber(
      answerResult.quiz_correct_answers ??
      session.quiz_correct_answers,
      0
    )
  );

const wrongAnswers =
  Math.max(
    0,
    toNumber(
      answerResult.quiz_wrong_answers ??
      session.quiz_wrong_answers,
      0
    )
  );

const calculatedScore =
  Math.round(
    (
      correctAnswers /
      totalQuestions
    ) *
    100
  );

const quizScore =
  toNumber(
    answerResult.quiz_score ??
    session.quiz_score,
    calculatedScore
  );

const passingPercentage =
  Math.max(
    0,
    toNumber(
      answerResult.passing_percentage,
      80
    )
  );

const quizPassed =
  toBoolean(
    answerResult.quiz_passed ??
    session.quiz_passed,
    quizScore >=
      passingPercentage
  );

const feedbackReply =
  toText(
    answerResult.feedback_reply
  );


/* =========================
   Calculate Next Levels
========================= */

const isLastLearningLevel =
  currentLevel >= maxLearningLevel;

/*
  انتهى المستوى الرئيسي الحالي
  عندما ينجح في Micro Level 4.
*/
const mainLevelCompleted =
  quizPassed &&
  isLastMicroLevel;

/*
  انتهى البرنامج كاملًا فقط إذا:
  Level 6 + Micro Level 4 + Passed
*/
const learningProgramCompleted =
  quizPassed &&
  isLastMicroLevel &&
  isLastLearningLevel;


/*
  لا نسمح أبدًا بإنشاء Level 7.
*/
const targetLevel =
  !quizPassed
    ? currentLevel
    : learningProgramCompleted
      ? maxLearningLevel
      : isLastMicroLevel
        ? currentLevel + 1
        : currentLevel;


/*
  عند الانتقال لمستوى رئيسي جديد:
  Micro Level يرجع إلى 1.

  عند إنهاء Level 6:
  نبقى مسجلين على 6 / 4 بدل إنشاء مستوى وهمي.
*/
const targetMicroLevel =
  !quizPassed
    ? currentMicroLevel
    : learningProgramCompleted
      ? currentMicroLevel
      : isLastMicroLevel
        ? 1
        : currentMicroLevel + 1;

/* =========================
   Final Reply
========================= */

let resultReply;
let suggestedActions;

if (quizPassed) {
  if (learningProgramCompleted) {
    resultReply =
      isEnglish
        ? (
            `The micro-level quiz is complete!\n` +
            `Your score is ${quizScore}%.\n` +
            `You answered ${correctAnswers} out of ${totalQuestions} questions correctly.\n\n` +
            `Congratulations! You completed Learning Level ${maxLearningLevel}, ` +
            `the highest learning level in Lehja. ` +
            `You are now ready for the final assessment.`
          )
        : (
            `انتهى امتحان المستوى الفرعي!\n` +
            `علامتك هي ${quizScore}%.\n` +
            `أجبت عن ${correctAnswers} من أصل ${totalQuestions} أسئلة بشكل صحيح.\n\n` +
            `مبارك! أنهيت المستوى الرئيسي ${maxLearningLevel}، ` +
            `وهو أعلى مستوى تعليمي في لهجة. ` +
            `أصبحت الآن جاهزًا للتقييم النهائي.`
          );

    suggestedActions =
      isEnglish
        ? ["Start final assessment"]
        : ["ابدأ التقييم النهائي"];
  } else if (isEnglish) {
    if (mainLevelCompleted) {
      resultReply =
        `The micro-level quiz is complete!\n` +
        `Your score is ${quizScore}%.\n` +
        `You answered ${correctAnswers} out of ${totalQuestions} questions correctly.\n\n` +
        `Congratulations! You completed Learning Level ${currentLevel}. ` +
        `You are now ready to begin Learning Level ${targetLevel}, ` +
        `Micro Level ${targetMicroLevel}.`;
    } else {
      resultReply =
        `The micro-level quiz is complete!\n` +
        `Your score is ${quizScore}%.\n` +
        `You answered ${correctAnswers} out of ${totalQuestions} questions correctly.\n\n` +
        `Congratulations! You passed Micro Level ${currentMicroLevel} ` +
        `within Learning Level ${currentLevel}. ` +
        `You are now ready to begin Micro Level ${targetMicroLevel}.`;
    }

    suggestedActions = [
      "Continue learning",
    ];
  } else {
    if (mainLevelCompleted) {
      resultReply =
        `انتهى امتحان المستوى الفرعي!\n` +
        `علامتك هي ${quizScore}%.\n` +
        `أجبت عن ${correctAnswers} من أصل ${totalQuestions} أسئلة بشكل صحيح.\n\n` +
        `مبارك! أنهيت المستوى الرئيسي ${currentLevel} بنجاح، ` +
        `وأصبحت جاهزًا لبدء المستوى الرئيسي ${targetLevel}، ` +
        `المستوى الفرعي ${targetMicroLevel}.`;
    } else {
      resultReply =
        `انتهى امتحان المستوى الفرعي!\n` +
        `علامتك هي ${quizScore}%.\n` +
        `أجبت عن ${correctAnswers} من أصل ${totalQuestions} أسئلة بشكل صحيح.\n\n` +
        `مبارك! نجحت في المستوى الفرعي ${currentMicroLevel} ` +
        `ضمن المستوى الرئيسي ${currentLevel}، ` +
        `وأصبحت جاهزًا لبدء المستوى الفرعي ${targetMicroLevel}.`;
    }

    suggestedActions = [
      "تابع التعلّم",
    ];
  }
} else {
  if (isEnglish) {
    resultReply =
      `The micro-level quiz is complete.\n` +
      `Your score is ${quizScore}%.\n` +
      `You answered ${correctAnswers} out of ${totalQuestions} questions correctly.\n\n` +
      `You need ${passingPercentage}% to pass Micro Level ${currentMicroLevel}. ` +
      `A short review will help before trying the quiz again.`;

    suggestedActions = [
      "Start review",
    ];
  } else {
    resultReply =
      `انتهى امتحان المستوى الفرعي.\n` +
      `علامتك هي ${quizScore}%.\n` +
      `أجبت عن ${correctAnswers} من أصل ${totalQuestions} أسئلة بشكل صحيح.\n\n` +
      `تحتاج إلى ${passingPercentage}% للنجاح في المستوى الفرعي ${currentMicroLevel}. ` +
      `مراجعة قصيرة ستساعدك قبل إعادة الامتحان.`;

    suggestedActions = [
      "ابدأ المراجعة",
    ];
  }
}

const reply =
  feedbackReply
    ? `${feedbackReply}\n\n${resultReply}`
    : resultReply;


/* =========================
   Update Session
========================= */

const now =
  new Date().toISOString();

let updatedSession;

if (quizPassed) {
  updatedSession = {
    ...session,

    current_level:
      targetLevel,

    current_micro_level:
      targetMicroLevel,

    current_step:
      learningProgramCompleted
        ? "learning_completed"
        : "awaiting_continue",

    words_completed:
      learningProgramCompleted
        ? Math.max(
            0,
            toNumber(
              session.words_total,
              20
            )
          )
        : 0,

    completed_item_ids:
      JSON.stringify([]),

    difficult_item_ids:
      JSON.stringify([]),

    current_item_id:
      "",

    current_source_id:
      "",

    current_levantine:
      "",

    current_msa:
      "",

    current_english:
      "",

    current_topic:
      "",

    consecutive_understood:
      0,

    confusion_count:
      0,

    example_count:
      0,

    review_active:
      false,

    review_recommended:
      false,

    quiz_active:
      false,

    quiz_passed:
      true,

    quiz_score:
      quizScore,

    quiz_correct_answers:
      correctAnswers,

    quiz_wrong_answers:
      wrongAnswers,

    quiz_question_index:
      0,

    quiz_question_ids:
      JSON.stringify([]),

    quiz_answered_item_ids:
      JSON.stringify([]),

    quiz_current_item_id:
      "",

    quiz_current_levantine:
      "",

    quiz_current_msa:
      "",

    quiz_current_english:
      "",

    quiz_completed_at:
      toText(
        session.quiz_completed_at,
        now
      ),

    last_agent_action:
      learningProgramCompleted
        ? "learning_program_completed"
        : mainLevelCompleted
          ? "learning_level_completed"
          : "micro_level_quiz_passed",

    last_agent_reason:
      learningProgramCompleted
        ? "highest_learning_level_completed"
        : mainLevelCompleted
          ? "last_micro_level_passed"
          : "micro_level_quiz_passed",

    updated_at:
      now,

    last_activity_at:
      now,
  };
} else {
  updatedSession = {
    ...session,

    current_level:
      currentLevel,

    current_micro_level:
      currentMicroLevel,

    current_step:
      "quiz_failed",

    quiz_active:
      false,

    quiz_passed:
      false,

    quiz_score:
      quizScore,

    quiz_correct_answers:
      correctAnswers,

    quiz_wrong_answers:
      wrongAnswers,

    quiz_completed_at:
      toText(
        session.quiz_completed_at,
        now
      ),

    review_active:
      false,

    review_recommended:
      true,

    last_agent_action:
      "micro_level_quiz_failed",

    last_agent_reason:
      "micro_level_quiz_score_below_passing",

    updated_at:
      now,

    last_activity_at:
      now,
  };
}


/* =========================
   Frontend Progress
========================= */

const frontendWordsCompleted =
  learningProgramCompleted
    ? Math.max(
        0,
        toNumber(
          updatedSession.words_completed,
          updatedSession.words_total ?? 20
        )
      )
    : quizPassed
      ? 0
      : Math.max(
        0,
        toNumber(
          updatedSession.words_completed,
          0
        )
      );

const frontendWordsTotal =
  Math.max(
    1,
    toNumber(
      updatedSession.words_total,
      20
    )
  );

const frontendWordsRemaining =
  Math.max(
    0,
    frontendWordsTotal -
    frontendWordsCompleted
  );


/* =========================
   Frontend Response
========================= */

const response = {
  success:
    true,

  mode:
    "learning",

  action:
    learningProgramCompleted
      ? "learning_program_completed"
      : quizPassed
        ? (
            mainLevelCompleted
              ? "learning_level_completed"
              : "quiz_passed"
          )
        : "quiz_failed",

  reply,

  suggested_actions:
    suggestedActions,

  quiz_active:
    false,

  quiz_finished:
    true,

  quiz_passed:
    quizPassed,

  quiz_score:
    quizScore,

  passing_percentage:
    passingPercentage,

  quiz_correct_answers:
    correctAnswers,

  quiz_wrong_answers:
    wrongAnswers,

  quiz_total_questions:
    totalQuestions,

  main_level_completed:
    mainLevelCompleted,

  learning_program_completed:
    learningProgramCompleted,

  completed_level:
    mainLevelCompleted
      ? currentLevel
      : null,

  completed_micro_level:
    currentMicroLevel,

  current_level:
    quizPassed
      ? targetLevel
      : currentLevel,

  current_micro_level:
    quizPassed
      ? targetMicroLevel
      : currentMicroLevel,

  words_completed:
    frontendWordsCompleted,

  words_total:
    frontendWordsTotal,

  words_remaining:
    frontendWordsRemaining,

  next_level:
    learningProgramCompleted
      ? null
      : mainLevelCompleted
        ? targetLevel
        : null,

  next_micro_level:
    learningProgramCompleted
      ? null
      : quizPassed
        ? targetMicroLevel
        : null,

  preferred_language:
    preferredLanguage,

  learning_session_id:
    toText(
      session.learning_session_id
    ),
};


/* =========================
   Output
========================= */

return [
  {
    json: {
      quiz_passed:
        quizPassed,

      quiz_score:
        quizScore,

      quiz_correct_answers:
        correctAnswers,

      quiz_wrong_answers:
        wrongAnswers,

      quiz_total_questions:
        totalQuestions,

      main_level_completed:
        mainLevelCompleted,

      learning_program_completed:
        learningProgramCompleted,

      completed_level:
        mainLevelCompleted
          ? currentLevel
          : null,

      completed_micro_level:
        currentMicroLevel,

      current_level:
        quizPassed
          ? targetLevel
          : currentLevel,

      current_micro_level:
        quizPassed
          ? targetMicroLevel
          : currentMicroLevel,

      words_completed:
        frontendWordsCompleted,

      words_total:
        frontendWordsTotal,

      words_remaining:
        frontendWordsRemaining,

      next_level:
        learningProgramCompleted
          ? null
          : mainLevelCompleted
            ? targetLevel
            : null,

      next_micro_level:
        learningProgramCompleted
          ? null
          : quizPassed
            ? targetMicroLevel
            : null,

      session_row:
        updatedSession,

      response,
    },
  },
];

/*
  Prepare Post-Test Start

  يبدأ الـPost-test بعد أن يقرر المستخدم إنهاء مرحلة التعلم.

  المسؤوليات:
  - قراءة حالة المستخدم الحالية
  - جمع العناصر التي ظهرت له أثناء التعلم
  - اختيار حتى 10 عناصر عشوائية للـPost-test
  - تجهيز حالة Post-test مستقلة عن Micro Quiz
  - تجهيز أول item_id ليتم جلبه من Chroma
*/


/* =========================
   Read Nodes
========================= */

const decision =
  $("Validate Agent Decision").first().json ?? {};

const context =
  $("Build Agent Context").first().json ?? {};

const session = {
  ...(context.session_row ?? {}),
};


/* =========================
   Helpers
========================= */

function toText(value, fallback = "") {
  if (
    value === null ||
    value === undefined
  ) {
    return fallback;
  }

  const result =
    String(value).trim();

  return result || fallback;
}


function toNumber(value, fallback = 0) {
  const result =
    Number(value);

  return Number.isFinite(result)
    ? result
    : fallback;
}


function parseList(value) {
  if (Array.isArray(value)) {
    return [
      ...new Set(
        value
          .map((item) => toText(item))
          .filter(Boolean)
      ),
    ];
  }

  const raw =
    toText(value);

  if (!raw) {
    return [];
  }

  try {
    const parsed =
      JSON.parse(raw);

    if (Array.isArray(parsed)) {
      return [
        ...new Set(
          parsed
            .map((item) => toText(item))
            .filter(Boolean)
        ),
      ];
    }
  } catch {
    // continue
  }

  return [
    ...new Set(
      raw
        .split(",")
        .map((item) => item.trim())
        .filter(Boolean)
    ),
  ];
}


function shuffle(array) {
  const copy =
    [...array];

  for (
    let i = copy.length - 1;
    i > 0;
    i--
  ) {
    const j =
      Math.floor(
        Math.random() *
        (i + 1)
      );

    [
      copy[i],
      copy[j],
    ] = [
      copy[j],
      copy[i],
    ];
  }

  return copy;
}


function validIds(value) {
  return parseList(value)
    .filter(
      (id) =>
        id &&
        !id.startsWith(
          "content-"
        )
    );
}


/* =========================
   Validate Action
========================= */

const action =
  toText(
    decision.action
  );


if (
  action !==
  "finish_learning"
) {
  throw new Error(
    `Prepare Post-Test Start expected finish_learning but received: ${action || "empty action"}`
  );
}


/* =========================
   Language
========================= */

const preferredLanguage =
  toText(
    context.preferred_language ??
    session.preferred_language,
    "MSA"
  );


const isEnglish =
  preferredLanguage
    .toLowerCase() ===
    "english";


/* =========================
   Current Learning State
========================= */

const currentLevel =
  Math.max(
    1,
    toNumber(
      context.current_level ??
      session.current_level,
      1
    )
  );


const currentMicroLevel =
  Math.max(
    1,
    toNumber(
      context.current_micro_level ??
      session.current_micro_level,
      1
    )
  );


/* =========================
   Learned Item Pool
========================= */

/*
  used_item_ids يتراكم خلال رحلة التعلم،
  لذلك هو الأنسب للـPost-test.

  نضيف completed_item_ids أيضًا كحماية إضافية.
*/

const usedItemIds =
  validIds(
    session.used_item_ids
  );


const completedItemIds =
  validIds(
    session.completed_item_ids
  );


const learnedItemIds = [
  ...new Set([
    ...usedItemIds,
    ...completedItemIds,
  ]),
];


/* =========================
   Post-Test Size
========================= */

const MAX_POST_TEST_QUESTIONS =
  10;

const MIN_POST_TEST_QUESTIONS =
  5;


const shuffledLearnedItems =
  shuffle(
    learnedItemIds
  );


const postTestQuestionIds =
  shuffledLearnedItems.slice(
    0,
    MAX_POST_TEST_QUESTIONS
  );


const postTestTotalQuestions =
  postTestQuestionIds.length;


const firstQuestionId =
  postTestQuestionIds[0] ??
  "";


const hasPostTest =
  postTestTotalQuestions >=
    MIN_POST_TEST_QUESTIONS &&
  Boolean(
    firstQuestionId
  );


/* =========================
   Time
========================= */

const now =
  new Date().toISOString();


/* =========================
   Not Enough Learned Items
========================= */

if (!hasPostTest) {

  const reply =
    isEnglish
      ? (
          `The final assessment cannot start yet. ` +
          `At least ${MIN_POST_TEST_QUESTIONS} learned items are required, ` +
          `but only ${postTestTotalQuestions} valid items are currently available.`
        )
      : (
          `لا يمكن بدء التقييم النهائي الآن. ` +
          `يجب أن تكون قد تعلّمت ${MIN_POST_TEST_QUESTIONS} عناصر على الأقل، ` +
          `بينما يوجد حاليًا ${postTestTotalQuestions} عناصر صالحة فقط.`
        );


  const unavailableSession = {
    ...session,

    post_test_active:
      false,

    post_test_question_index:
      0,

    post_test_total_questions:
      0,

    post_test_score:
      0,

    post_test_correct_answers:
      0,

    post_test_wrong_answers:
      0,

    post_test_question_ids:
      JSON.stringify([]),

    post_test_answered_item_ids:
      JSON.stringify([]),

    post_test_current_item_id:
      "",

    post_test_current_levantine:
      "",

    post_test_current_msa:
      "",

    post_test_current_english:
      "",

    post_test_passed:
      false,

    current_step:
      "post_test_unavailable",

    last_agent_action:
      "finish_learning",

    last_agent_reason:
      "not_enough_items_for_post_test",

    updated_at:
      now,

    last_activity_at:
      now,
  };


  return [
    {
      json: {
        has_post_test:
          false,

        post_test_target_id:
          "",

        post_test_question_ids:
          [],

        post_test_total_questions:
          0,

        session_row:
          unavailableSession,

        response: {
          success:
            false,

          mode:
            "learning",

          action:
            "post_test_unavailable",

          reply,

          suggested_actions:
            isEnglish
              ? [
                  "Continue learning",
                ]
              : [
                  "تابع التعلّم",
                ],

          current_level:
            currentLevel,

          current_micro_level:
            currentMicroLevel,

          preferred_language:
            preferredLanguage,

          learning_session_id:
            toText(
              session.learning_session_id
            ),
        },

        debug: {
          learned_valid_items:
            learnedItemIds.length,

          minimum_required:
            MIN_POST_TEST_QUESTIONS,

          maximum_questions:
            MAX_POST_TEST_QUESTIONS,
        },
      },
    },
  ];
}


/* =========================
   Start Post-Test
========================= */

const updatedSession = {
  ...session,

  current_level:
    currentLevel,

  current_micro_level:
    currentMicroLevel,

  post_test_active:
    true,

  /*
    السؤال الأول سيتم تحميله في العقدة التالية.
  */
  post_test_question_index:
    0,

  post_test_total_questions:
    postTestTotalQuestions,

  post_test_score:
    0,

  post_test_correct_answers:
    0,

  post_test_wrong_answers:
    0,

  post_test_question_ids:
    JSON.stringify(
      postTestQuestionIds
    ),

  post_test_answered_item_ids:
    JSON.stringify([]),

  post_test_current_item_id:
    "",

  post_test_current_levantine:
    "",

  post_test_current_msa:
    "",

  post_test_current_english:
    "",

  post_test_started_at:
    now,

  post_test_completed_at:
    "",

  post_test_passed:
    false,

  current_step:
    "post_test_loading",

  review_active:
    false,

  review_recommended:
    false,

  last_agent_action:
    "finish_learning",

  last_agent_reason:
    "learner_started_post_test",

  updated_at:
    now,

  last_activity_at:
    now,
};


/* =========================
   Intro
========================= */

const introReply =
  isEnglish
    ? (
        `You've reached the final assessment. ` +
        `It contains ${postTestTotalQuestions} questions based on material you learned during your session. ` +
        `Answer from memory as accurately as you can.`
      )
    : (
        `وصلت الآن إلى التقييم النهائي. ` +
        `يتكوّن من ${postTestTotalQuestions} أسئلة من المحتوى الذي تعلّمته خلال رحلتك. ` +
        `حاول الإجابة من ذاكرتك قدر الإمكان.`
      );


/* =========================
   Output
========================= */

return [
  {
    json: {
      has_post_test:
        true,

      post_test_target_id:
        firstQuestionId,

      post_test_question_ids:
        postTestQuestionIds,

      post_test_total_questions:
        postTestTotalQuestions,

      current_level:
        currentLevel,

      current_micro_level:
        currentMicroLevel,

      session_row:
        updatedSession,

      response: {
        success:
          true,

        mode:
          "learning",

        action:
          "post_test_start",

        reply:
          introReply,

        suggested_actions:
          [],

        post_test_active:
          true,

        post_test_total_questions:
          postTestTotalQuestions,

        current_level:
          currentLevel,

        current_micro_level:
          currentMicroLevel,

        preferred_language:
          preferredLanguage,

        learning_session_id:
          toText(
            session.learning_session_id
          ),
      },

      debug: {
        learned_valid_items:
          learnedItemIds.length,

        selected_post_test_ids:
          postTestQuestionIds,
      },
    },
  },
];

/*
  Prepare Post-Test Question

  يحوّل عنصر Chroma إلى أول سؤال في الـPost-test
  بدون إظهار الإجابة الصحيحة.
*/


/* =========================
   Read Nodes
========================= */

const postTestStart =
  $("Prepare Post-Test Start").first().json ?? {};

const session = {
  ...(postTestStart.session_row ?? {}),
};

const chromaResult =
  $input.first()?.json ?? {};


/* =========================
   Helpers
========================= */

function toText(value, fallback = "") {
  if (
    value === null ||
    value === undefined
  ) {
    return fallback;
  }

  if (Array.isArray(value)) {
    const firstValue =
      value.find(
        (item) =>
          item !== null &&
          item !== undefined &&
          String(item).trim()
      );

    return firstValue === undefined
      ? fallback
      : String(firstValue).trim();
  }

  const result =
    String(value).trim();

  return result || fallback;
}


function toNumber(value, fallback = 0) {
  const result =
    Number(value);

  return Number.isFinite(result)
    ? result
    : fallback;
}


function escapeRegex(value) {
  return String(value).replace(
    /[.*+?^${}()|[\]\\]/g,
    "\\$&"
  );
}


/* =========================
   Read Chroma Result
========================= */

function findMetadata(result) {
  if (
    result.document?.metadata &&
    typeof result.document.metadata === "object"
  ) {
    return result.document.metadata;
  }

  if (
    result.metadata &&
    typeof result.metadata === "object"
  ) {
    return result.metadata;
  }

  if (
    Array.isArray(result.metadatas) &&
    result.metadatas[0]
  ) {
    return result.metadatas[0];
  }

  return {};
}


function findContent(result) {
  return toText(
    result.document?.pageContent ??
    result.document?.content ??
    result.pageContent ??
    result.content ??
    result.text ??
    result.documents?.[0]
  );
}


function valueFromContent(
  content,
  labels
) {
  const source =
    toText(content);

  if (!source) {
    return "";
  }

  for (const label of labels) {
    const escapedLabel =
      escapeRegex(label);

    const pattern =
      new RegExp(
        `(?:^|\\n)\\s*${escapedLabel}\\s*[:：-]\\s*(.+?)(?=\\n|$)`,
        "i"
      );

    const match =
      source.match(pattern);

    if (match) {
      return toText(
        match[1]
      );
    }
  }

  return "";
}


/* =========================
   Extract Item
========================= */

const metadata =
  findMetadata(chromaResult);

const content =
  findContent(chromaResult);


const itemId =
  toText(
    metadata.item_id ??
    metadata.original_id ??
    metadata.source_id ??
    postTestStart.post_test_target_id
  );


const sourceId =
  toText(
    metadata.source_id ??
    metadata.original_id ??
    itemId
  );


const levantine =
  toText(
    metadata.levantine ??
    valueFromContent(
      content,
      [
        "الشامية",
        "Levantine",
        "Levantine Arabic",
      ]
    )
  );


const msa =
  toText(
    metadata.msa ??
    valueFromContent(
      content,
      [
        "الفصحى",
        "MSA",
        "Modern Standard Arabic",
      ]
    )
  );


const english =
  toText(
    metadata.english ??
    valueFromContent(
      content,
      [
        "الإنجليزية",
        "English",
        "Meaning",
      ]
    )
  );


const topic =
  toText(
    metadata.topic ??
    valueFromContent(
      content,
      [
        "الموضوع",
        "Topic",
      ]
    )
  );


/* =========================
   Post-Test Progress
========================= */

const questionIndex =
  1;


const totalQuestions =
  Math.max(
    1,
    toNumber(
      session.post_test_total_questions ??
      postTestStart.post_test_total_questions,
      10
    )
  );


/* =========================
   Language
========================= */

const preferredLanguage =
  toText(
    postTestStart.response?.preferred_language ??
    session.preferred_language,
    "MSA"
  );


const isEnglish =
  preferredLanguage
    .toLowerCase() ===
    "english";


const isPhrase =
  levantine
    .split(/\s+/)
    .filter(Boolean)
    .length > 1;


/* =========================
   Build Question
========================= */

let questionText;

if (!levantine) {
  questionText =
    isEnglish
      ? "The final assessment question could not be loaded."
      : "تعذّر تحميل سؤال التقييم النهائي.";
} else if (isEnglish) {
  questionText =
    isPhrase
      ? (
          `Final Assessment — Question ${questionIndex} of ${totalQuestions}\n` +
          `What does the phrase «${levantine}» mean in English?`
        )
      : (
          `Final Assessment — Question ${questionIndex} of ${totalQuestions}\n` +
          `What does the word «${levantine}» mean in English?`
        );
} else {
  questionText =
    isPhrase
      ? (
          `التقييم النهائي — السؤال ${questionIndex} من ${totalQuestions}\n` +
          `ما معنى العبارة «${levantine}» بالفصحى؟`
        )
      : (
          `التقييم النهائي — السؤال ${questionIndex} من ${totalQuestions}\n` +
          `ما معنى كلمة «${levantine}» بالفصحى؟`
        );
}


/* =========================
   Intro + First Question
========================= */

const intro =
  isEnglish
    ? (
        `You are now starting the final assessment. ` +
        `It contains ${totalQuestions} questions from material you learned. ` +
        `Answer from memory without reviewing previous explanations.`
      )
    : (
        `أنت الآن تبدأ التقييم النهائي. ` +
        `يتكوّن من ${totalQuestions} أسئلة من المحتوى الذي تعلّمته. ` +
        `حاول الإجابة من ذاكرتك دون الرجوع إلى الشروحات السابقة.`
      );


const reply =
  `${intro}\n\n${questionText}`;


/* =========================
   Update Session
========================= */

const now =
  new Date().toISOString();


const updatedSession = {
  ...session,

  post_test_active:
    true,

  post_test_question_index:
    questionIndex,

  post_test_current_item_id:
    itemId,

  post_test_current_levantine:
    levantine,

  post_test_current_msa:
    msa,

  post_test_current_english:
    english,

  current_step:
    "post_test_question",

  last_agent_action:
    "post_test_question",

  last_agent_reason:
    "post_test_first_question_loaded",

  updated_at:
    now,

  last_activity_at:
    now,
};


/* =========================
   Frontend Response
========================= */

const response = {
  success:
    Boolean(
      itemId &&
      levantine
    ),

  mode:
    "learning",

  action:
    "post_test_question",

  reply,

  suggested_actions:
    [],

  post_test_active:
    true,

  post_test_question_index:
    questionIndex,

  post_test_total_questions:
    totalQuestions,

  current_level:
    toNumber(
      session.current_level,
      1
    ),

  current_micro_level:
    toNumber(
      session.current_micro_level,
      1
    ),

  preferred_language:
    preferredLanguage,

  learning_session_id:
    toText(
      session.learning_session_id
    ),
};


/* =========================
   Output
========================= */

return [
  {
    json: {
      session_row:
        updatedSession,

      response,

      post_test_item: {
        item_id:
          itemId,

        source_id:
          sourceId,

        levantine,

        msa,

        english,

        topic,
      },
    },
  },
];

