parameters.jsCode:
/*
  Prepare Post-Test Answer Result

  المسؤوليات:
  - قراءة نتيجة Post-Test Answer Evaluator
  - تحديث عدد الإجابات الصحيحة والخاطئة
  - تسجيل السؤال كمجاب عليه
  - تحديد السؤال التالي
  - إنهاء الـPost-test عند آخر سؤال
  - عدم كشف الإجابة الصحيحة أثناء التقييم
*/


/* =========================
   Read Nodes
========================= */

const context =
  $("Build Agent Context").first().json ?? {};

const evaluatorInput =
  $input.first()?.json ?? {};

const session = {
  ...(context.session_row ?? {}),
};


/* =========================
   Helpers
========================= */

function toText(value, fallback = "") {
  if (
    value === null ||
    value === undefined
  ) {
    return fallback;
  }

  const result =
    String(value).trim();

  return result || fallback;
}


function toNumber(value, fallback = 0) {
  const result =
    Number(value);

  return Number.isFinite(result)
    ? result
    : fallback;
}


function toBoolean(value, fallback = false) {
  if (typeof value === "boolean") {
    return value;
  }

  const normalized =
    toText(value)
      .toLowerCase();

  if (
    [
      "true",
      "1",
      "yes",
    ].includes(normalized)
  ) {
    return true;
  }

  if (
    [
      "false",
      "0",
      "no",
    ].includes(normalized)
  ) {
    return false;
  }

  return fallback;
}


function parseList(value) {
  if (Array.isArray(value)) {
    return [
      ...new Set(
        value
          .map((item) => toText(item))
          .filter(Boolean)
      ),
    ];
  }

  const raw =
    toText(value);

  if (!raw) {
    return [];
  }

  try {
    const parsed =
      JSON.parse(raw);

    if (Array.isArray(parsed)) {
      return [
        ...new Set(
          parsed
            .map((item) => toText(item))
            .filter(Boolean)
        ),
      ];
    }
  } catch {
    // continue
  }

  return [
    ...new Set(
      raw
        .split(",")
        .map((item) => item.trim())
        .filter(Boolean)
    ),
  ];
}


function parseEvaluatorOutput(input) {
  let raw =
    input?.output ??
    input?.text ??
    input?.response ??
    input;

  if (
    raw &&
    typeof raw === "object" &&
    !Array.isArray(raw)
  ) {
    if (
      raw.is_correct !== undefined ||
      raw.reason_code
    ) {
      return raw;
    }
  }

  raw =
    toText(raw);

  if (!raw) {
    return {};
  }

  const cleaned =
    raw
      .replace(/^```json\s*/i, "")
      .replace(/^```\s*/i, "")
      .replace(/```$/i, "")
      .trim();

  try {
    return JSON.parse(cleaned);
  } catch {
    // نحاول استخراج JSON من النص.
  }

  const firstBrace =
    cleaned.indexOf("{");

  const lastBrace =
    cleaned.lastIndexOf("}");

  if (
    firstBrace !== -1 &&
    lastBrace > firstBrace
  ) {
    try {
      return JSON.parse(
        cleaned.slice(
          firstBrace,
          lastBrace + 1
        )
      );
    } catch {
      // fallback
    }
  }

  return {};
}


/* =========================
   Evaluator Result
========================= */

const evaluation =
  parseEvaluatorOutput(
    evaluatorInput
  );


const isCorrect =
  toBoolean(
    evaluation.is_correct,
    false
  );


const evaluationReason =
  toText(
    evaluation.reason_code,
    isCorrect
      ? "correct_answer"
      : "incorrect_answer"
  );


/* =========================
   Language
========================= */

const preferredLanguage =
  toText(
    context.preferred_language ??
    session.preferred_language,
    "MSA"
  );


const isEnglish =
  preferredLanguage
    .toLowerCase() ===
    "english";


/* =========================
   Current Post-Test State
========================= */

const questionIds =
  parseList(
    session.post_test_question_ids
  );


let answeredItemIds =
  parseList(
    session.post_test_answered_item_ids
  );


const currentItemId =
  toText(
    session.post_test_current_item_id
  );


const totalQuestions =
  Math.max(
    1,
    toNumber(
      session.post_test_total_questions,
      questionIds.length || 10
    )
  );


let correctAnswers =
  Math.max(
    0,
    toNumber(
      session.post_test_correct_answers,
      0
    )
  );


let wrongAnswers =
  Math.max(
    0,
    toNumber(
      session.post_test_wrong_answers,
      0
    )
  );


/* =========================
   Record Current Answer
========================= */

/*
  حماية من احتساب نفس السؤال مرتين
  لو وصل نفس الطلب أكثر من مرة.
*/

const alreadyAnswered =
  currentItemId &&
  answeredItemIds.includes(
    currentItemId
  );


if (
  currentItemId &&
  !alreadyAnswered
) {
  answeredItemIds.push(
    currentItemId
  );

  if (isCorrect) {
    correctAnswers += 1;
  } else {
    wrongAnswers += 1;
  }
}


/* =========================
   Calculate Progress
========================= */

const answeredCount =
  answeredItemIds.length;


const postTestScore =
  Math.round(
    (
      correctAnswers /
      totalQuestions
    ) *
    100
  );


/* =========================
   Find Next Question
========================= */

/*
  نبحث عن أول سؤال لم تتم الإجابة عنه.
  هذا أكثر أمانًا من الاعتماد فقط على +1.
*/

const answeredSet =
  new Set(
    answeredItemIds
  );


const nextQuestionId =
  questionIds.find(
    (id) =>
      !answeredSet.has(id)
  ) ?? "";


const nextQuestionPosition =
  nextQuestionId
    ? questionIds.indexOf(
        nextQuestionId
      )
    : -1;


const nextQuestionIndex =
  nextQuestionPosition >= 0
    ? nextQuestionPosition + 1
    : 0;


const hasNextQuestion =
  Boolean(
    nextQuestionId
  ) &&
  answeredCount <
    totalQuestions;


const postTestFinished =
  !hasNextQuestion ||
  answeredCount >=
    totalQuestions;


/* =========================
   Time
========================= */

const now =
  new Date().toISOString();


/* =========================
   Update Session
========================= */

const updatedSession = {
  ...session,

  post_test_active:
    !postTestFinished,

  post_test_correct_answers:
    correctAnswers,

  post_test_wrong_answers:
    wrongAnswers,

  post_test_score:
    postTestScore,

  post_test_answered_item_ids:
    JSON.stringify(
      answeredItemIds
    ),

  /*
    إذا فيه سؤال ثاني، نخزّن رقمه.
    إذا انتهى الاختبار نخليه 0.
  */
  post_test_question_index:
    postTestFinished
      ? 0
      : nextQuestionIndex,

  /*
    نمسح السؤال الحالي.
    عقدة السؤال التالي ستضع العنصر الجديد.
  */
  post_test_current_item_id:
    "",

  post_test_current_levantine:
    "",

  post_test_current_msa:
    "",

  post_test_current_english:
    "",

  post_test_completed_at:
    postTestFinished
      ? now
      : toText(
          session.post_test_completed_at
        ),

  current_step:
    postTestFinished
      ? "post_test_completed"
      : "post_test_loading",

  last_agent_action:
    postTestFinished
      ? "post_test_completed"
      : "post_test_answer",

  last_agent_reason:
    postTestFinished
      ? "post_test_all_questions_answered"
      : evaluationReason,

  updated_at:
    now,

  last_activity_at:
    now,
};


/* =========================
   Learner Response
========================= */

/*
  أثناء الاختبار لا نخبر المستخدم
  إذا كانت إجابته صحيحة أو خاطئة،
  حتى لا نعطيه معلومات تساعده
  في بقية الـPost-test.
*/

let reply;

if (postTestFinished) {
  reply =
    isEnglish
      ? (
          `The final assessment is complete.\n` +
          `Your score is ${postTestScore}%.\n` +
          `You answered ${correctAnswers} out of ${totalQuestions} questions correctly.`
        )
      : (
          `انتهى التقييم النهائي.\n` +
          `علامتك هي ${postTestScore}%.\n` +
          `أجبت عن ${correctAnswers} من أصل ${totalQuestions} أسئلة بشكل صحيح.`
        );
} else {
  reply =
    isEnglish
      ? "Your answer has been recorded."
      : "تم تسجيل إجابتك.";
}


/* =========================
   Response
========================= */

const response = {
  success:
    true,

  mode:
    "learning",

  action:
    postTestFinished
      ? "post_test_completed"
      : "post_test_answer_recorded",

  reply,

  suggested_actions:
    [],

  post_test_active:
    !postTestFinished,

  post_test_finished:
    postTestFinished,

  post_test_score:
    postTestScore,

  post_test_correct_answers:
    correctAnswers,

  post_test_wrong_answers:
    wrongAnswers,

  post_test_total_questions:
    totalQuestions,

  post_test_answered_questions:
    answeredCount,

  preferred_language:
    preferredLanguage,

  learning_session_id:
    toText(
      session.learning_session_id
    ),
};


/* =========================
   Output
========================= */

return [
  {
    json: {
      is_correct:
        isCorrect,

      evaluation_reason:
        evaluationReason,

      post_test_finished:
        postTestFinished,

      has_next_post_test_question:
        hasNextQuestion,

      post_test_next_target_id:
        nextQuestionId,

      post_test_next_question_index:
        nextQuestionIndex,

      post_test_score:
        postTestScore,

      post_test_correct_answers:
        correctAnswers,

      post_test_wrong_answers:
        wrongAnswers,

      post_test_total_questions:
        totalQuestions,

      post_test_answered_questions:
        answeredCount,

      session_row:
        updatedSession,

      response,
    },
  },
];

/*
  Prepare Next Post-Test Question

  يحمّل السؤال التالي من Chroma
  ويجهّزه للـPost-test بدون كشف
  إذا كانت الإجابة السابقة صحيحة أو خاطئة.
*/


/* =========================
   Read Nodes
========================= */

const answerResult =
  $("Prepare Post-Test Answer Result").first().json ?? {};

const session = {
  ...(answerResult.session_row ?? {}),
};

const chromaResult =
  $input.first()?.json ?? {};


/* =========================
   Helpers
========================= */

function toText(value, fallback = "") {
  if (
    value === null ||
    value === undefined
  ) {
    return fallback;
  }

  if (Array.isArray(value)) {
    const firstValue =
      value.find(
        (item) =>
          item !== null &&
          item !== undefined &&
          String(item).trim()
      );

    return firstValue === undefined
      ? fallback
      : String(firstValue).trim();
  }

  const result =
    String(value).trim();

  return result || fallback;
}


function toNumber(value, fallback = 0) {
  const result =
    Number(value);

  return Number.isFinite(result)
    ? result
    : fallback;
}


function escapeRegex(value) {
  return String(value).replace(
    /[.*+?^${}()|[\]\\]/g,
    "\\$&"
  );
}


/* =========================
   Read Chroma Result
========================= */

function findMetadata(result) {
  if (
    result.document?.metadata &&
    typeof result.document.metadata === "object"
  ) {
    return result.document.metadata;
  }

  if (
    result.metadata &&
    typeof result.metadata === "object"
  ) {
    return result.metadata;
  }

  if (
    Array.isArray(result.metadatas) &&
    result.metadatas[0]
  ) {
    return result.metadatas[0];
  }

  return {};
}


function findContent(result) {
  return toText(
    result.document?.pageContent ??
    result.document?.content ??
    result.pageContent ??
    result.content ??
    result.text ??
    result.documents?.[0]
  );
}


function valueFromContent(
  content,
  labels
) {
  const source =
    toText(content);

  if (!source) {
    return "";
  }

  for (const label of labels) {
    const escapedLabel =
      escapeRegex(label);

    const pattern =
      new RegExp(
        `(?:^|\\n)\\s*${escapedLabel}\\s*[:：-]\\s*(.+?)(?=\\n|$)`,
        "i"
      );

    const match =
      source.match(pattern);

    if (match) {
      return toText(
        match[1]
      );
    }
  }

  return "";
}


/* =========================
   Extract Item
========================= */

const metadata =
  findMetadata(chromaResult);

const content =
  findContent(chromaResult);


const itemId =
  toText(
    metadata.item_id ??
    metadata.original_id ??
    metadata.source_id ??
    answerResult.post_test_next_target_id
  );


const sourceId =
  toText(
    metadata.source_id ??
    metadata.original_id ??
    itemId
  );


const levantine =
  toText(
    metadata.levantine ??
    valueFromContent(
      content,
      [
        "الشامية",
        "Levantine",
        "Levantine Arabic",
      ]
    )
  );


const msa =
  toText(
    metadata.msa ??
    valueFromContent(
      content,
      [
        "الفصحى",
        "MSA",
        "Modern Standard Arabic",
      ]
    )
  );


const english =
  toText(
    metadata.english ??
    valueFromContent(
      content,
      [
        "الإنجليزية",
        "English",
        "Meaning",
      ]
    )
  );


const topic =
  toText(
    metadata.topic ??
    valueFromContent(
      content,
      [
        "الموضوع",
        "Topic",
      ]
    )
  );


/* =========================
   Post-Test Progress
========================= */

const questionIndex =
  Math.max(
    1,
    toNumber(
      answerResult.post_test_next_question_index,
      session.post_test_question_index || 2
    )
  );


const totalQuestions =
  Math.max(
    1,
    toNumber(
      session.post_test_total_questions ??
      answerResult.post_test_total_questions,
      10
    )
  );


/* =========================
   Language
========================= */

const preferredLanguage =
  toText(
    answerResult.preferred_language ??
    session.preferred_language ??
    $("Build Agent Context").first().json.preferred_language,
    "MSA"
  );


const isEnglish =
  preferredLanguage
    .toLowerCase() ===
    "english";


const isPhrase =
  levantine
    .split(/\s+/)
    .filter(Boolean)
    .length > 1;


/* =========================
   Build Question
========================= */

let questionText;

if (!levantine) {
  questionText =
    isEnglish
      ? "The next final assessment question could not be loaded."
      : "تعذّر تحميل سؤال التقييم النهائي التالي.";
} else if (isEnglish) {
  questionText =
    isPhrase
      ? (
          `Final Assessment — Question ${questionIndex} of ${totalQuestions}\n` +
          `What does the phrase «${levantine}» mean in English?`
        )
      : (
          `Final Assessment — Question ${questionIndex} of ${totalQuestions}\n` +
          `What does the word «${levantine}» mean in English?`
        );
} else {
  questionText =
    isPhrase
      ? (
          `التقييم النهائي — السؤال ${questionIndex} من ${totalQuestions}\n` +
          `ما معنى العبارة «${levantine}» بالفصحى؟`
        )
      : (
          `التقييم النهائي — السؤال ${questionIndex} من ${totalQuestions}\n` +
          `ما معنى كلمة «${levantine}» بالفصحى؟`
        );
}


/* =========================
   Response Text
========================= */

/*
  لا نخبر المستخدم إن كانت الإجابة السابقة
  صحيحة أو خاطئة أثناء الـPost-test.
*/

const reply =
  isEnglish
    ? (
        `Your answer has been recorded.\n\n` +
        questionText
      )
    : (
        `تم تسجيل إجابتك.\n\n` +
        questionText
      );


/* =========================
   Update Session
========================= */

const now =
  new Date().toISOString();


const updatedSession = {
  ...session,

  post_test_active:
    true,

  post_test_question_index:
    questionIndex,

  post_test_current_item_id:
    itemId,

  post_test_current_levantine:
    levantine,

  post_test_current_msa:
    msa,

  post_test_current_english:
    english,

  current_step:
    "post_test_question",

  last_agent_action:
    "post_test_next_question",

  last_agent_reason:
    "next_post_test_question_loaded",

  updated_at:
    now,

  last_activity_at:
    now,
};


/* =========================
   Frontend Response
========================= */

const response = {
  success:
    Boolean(
      itemId &&
      levantine
    ),

  mode:
    "learning",

  action:
    "post_test_question",

  reply,

  suggested_actions:
    [],

  post_test_active:
    true,

  post_test_question_index:
    questionIndex,

  post_test_total_questions:
    totalQuestions,

  post_test_score:
    toNumber(
      session.post_test_score,
      0
    ),

  post_test_correct_answers:
    toNumber(
      session.post_test_correct_answers,
      0
    ),

  post_test_wrong_answers:
    toNumber(
      session.post_test_wrong_answers,
      0
    ),

  current_level:
    toNumber(
      session.current_level,
      1
    ),

  current_micro_level:
    toNumber(
      session.current_micro_level,
      1
    ),

  preferred_language:
    preferredLanguage,

  learning_session_id:
    toText(
      session.learning_session_id
    ),
};


/* =========================
   Output
========================= */

return [
  {
    json: {
      session_row:
        updatedSession,

      response,

      post_test_item: {
        item_id:
          itemId,

        source_id:
          sourceId,

        levantine,

        msa,

        english,

        topic,
      },
    },
  },
];

