parameters.jsCode:
/*
  Prepare Baseline Start

  المسؤوليات:
  - يبدأ Baseline Test بعد ضغط:
      Start assessment
      ابدأ التقييم
  - يأخذ العناصر القادمة من Chroma من نفس Learning Level
  - يختار 10 عناصر عشوائية مختلفة
  - يجهز حالة Baseline مستقلة
  - إذا كان Baseline بدأ مسبقًا:
      لا يعيد إنشاء الاختبار
      لا يختار أسئلة جديدة
      بل يكمل نفس الـBaseline بأمان
*/


/* =========================
   Read Context
========================= */

const context =
  $("Build Agent Context").first().json ?? {};

const session = {
  ...(context.session_row ?? {}),
};

const rows =
  $input.all();


/* =========================
   Helpers
========================= */

function toText(value, fallback = "") {
  if (
    value === null ||
    value === undefined
  ) {
    return fallback;
  }

  const result =
    String(value).trim();

  return result || fallback;
}


function toNumber(value, fallback = 0) {
  const result =
    Number(value);

  return Number.isFinite(result)
    ? result
    : fallback;
}


function toBoolean(value) {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value === "number") {
    return value !== 0;
  }

  if (typeof value === "string") {
    return [
      "true",
      "1",
      "yes",
      "active",
      "started",
    ].includes(
      value
        .trim()
        .toLowerCase()
    );
  }

  return false;
}


function parseArray(value) {
  if (Array.isArray(value)) {
    return value;
  }

  if (
    value === null ||
    value === undefined ||
    value === ""
  ) {
    return [];
  }

  if (typeof value === "string") {
    try {
      const parsed =
        JSON.parse(value);

      return Array.isArray(parsed)
        ? parsed
        : [];
    } catch {
      return [];
    }
  }

  return [];
}


function shuffle(array) {
  const copy =
    [...array];

  for (
    let i = copy.length - 1;
    i > 0;
    i--
  ) {
    const j =
      Math.floor(
        Math.random() *
        (i + 1)
      );

    [
      copy[i],
      copy[j],
    ] = [
      copy[j],
      copy[i],
    ];
  }

  return copy;
}


function findMetadata(value) {
  const json =
    value?.json ??
    value ??
    {};

  if (
    json.document?.metadata &&
    typeof json.document.metadata === "object"
  ) {
    return json.document.metadata;
  }

  if (
    json.metadata &&
    typeof json.metadata === "object"
  ) {
    return json.metadata;
  }

  if (
    Array.isArray(json.metadatas) &&
    json.metadatas[0] &&
    typeof json.metadatas[0] === "object"
  ) {
    return json.metadatas[0];
  }

  return {};
}


function getItemId(value) {
  const json =
    value?.json ??
    value ??
    {};

  const metadata =
    findMetadata(value);

  return toText(
    metadata.item_id ??
    metadata.original_id ??
    metadata.source_id ??
    json.item_id ??
    json.original_id ??
    json.source_id ??
    json.id
  );
}


/* =========================
   Basic Values
========================= */

const now =
  new Date().toISOString();


const currentStep =
  toText(
    session.current_step
  );


const preferredLanguage =
  toText(
    context.preferred_language ??
    session.preferred_language,
    "MSA"
  );


const isEnglish =
  preferredLanguage
    .toLowerCase() ===
    "english";


const currentLevel =
  Math.max(
    1,
    toNumber(
      context.current_level ??
      session.current_level,
      1
    )
  );


/* =========================
   Validate User Message
========================= */

const userMessage =
  toText(
    context.user_message
  )
    .toLowerCase();


const startMessages = [
  "start assessment",
  "ابدأ التقييم",
  "ابدا التقييم",
];


const validStart =
  startMessages.some(
    (message) =>
      userMessage ===
      message.toLowerCase()
  );


if (!validStart) {
  throw new Error(
    `Prepare Baseline Start expected Start assessment / ابدأ التقييم but received: ${context.user_message || "empty"}`
  );
}


/* =========================
   Resume Existing Baseline
========================= */

/*
  مهم جدًا:

  إذا ضغط المستخدم Start assessment،
  لكن الـBaseline كان قد بدأ مسبقًا
  وأصبحت الحالة:

  baseline_loading
  أو
  baseline_question

  فلا نعمل Error
  ولا نختار 10 أسئلة جديدة.

  نستخدم نفس baseline_question_ids
  ونكمل نفس الاختبار.
*/

const baselineAlreadyActive =
  toBoolean(
    session.baseline_active
  );


const resumableSteps = [
  "baseline_loading",
  "baseline_question",
];


if (
  baselineAlreadyActive &&
  resumableSteps.includes(
    currentStep
  )
) {

  const existingQuestionIds =
    [
      ...new Set(
        parseArray(
          session.baseline_question_ids
        )
          .map(
            (id) =>
              toText(id)
          )
          .filter(Boolean)
      ),
    ];


  const existingIndex =
    Math.max(
      0,
      toNumber(
        session.baseline_question_index,
        0
      )
    );


  const existingCurrentItemId =
    toText(
      session.baseline_current_item_id
    );


  const resumeTargetId =
    existingCurrentItemId ||
    existingQuestionIds[
      existingIndex
    ] ||
    existingQuestionIds[0] ||
    "";


  if (!resumeTargetId) {
    throw new Error(
      "Baseline is marked as active, but no valid baseline question ID was found."
    );
  }


  const resumedSession = {
    ...session,

    current_level:
      currentLevel,

    baseline_active:
      true,

    updated_at:
      now,

    last_activity_at:
      now,

    last_agent_action:
      "baseline_resume",

    last_agent_reason:
      "existing_baseline_resumed",
  };


  const reply =
    isEnglish
      ? "Your assessment is already in progress. Continuing from your current question."
      : "التقييم قيد التقدّم بالفعل. سنكمل من السؤال الحالي.";


  return [
    {
      json: {
        has_baseline:
          true,

        baseline_resumed:
          true,

        baseline_target_id:
          resumeTargetId,

        baseline_question_ids:
          existingQuestionIds,

        baseline_total_questions:
          Math.max(
            1,
            toNumber(
              session.baseline_total_questions,
              existingQuestionIds.length || 10
            )
          ),

        current_level:
          currentLevel,

        session_row:
          resumedSession,

        response: {
          success:
            true,

          mode:
            "learning",

          action:
            "baseline_resume",

          reply,

          suggested_actions:
            [],

          baseline_active:
            true,

          baseline_resumed:
            true,

          baseline_total_questions:
            Math.max(
              1,
              toNumber(
                session.baseline_total_questions,
                existingQuestionIds.length || 10
              )
            ),

          current_level:
            currentLevel,

          preferred_language:
            preferredLanguage,

          learning_session_id:
            toText(
              session.learning_session_id
            ),
        },

        debug: {
          resumed:
            true,

          previous_current_step:
            currentStep,

          baseline_question_index:
            existingIndex,

          baseline_target_id:
            resumeTargetId,

          existing_question_ids:
            existingQuestionIds,
        },
      },
    },
  ];
}


/* =========================
   Validate New Baseline State
========================= */

/*
  Baseline جديد يُسمح ببدئه فقط عندما تكون الحالة:
  baseline_intro

  ونسمح بالحالة الفارغة فقط كحماية لمستخدم جديد
  إذا لم يكن Baseline نشطًا أصلًا.
*/

const canStartNewBaseline =
  currentStep ===
    "baseline_intro" ||
  (
    !currentStep &&
    !baselineAlreadyActive
  );


if (!canStartNewBaseline) {
  throw new Error(
    `Prepare Baseline Start cannot start a new baseline from current_step=${currentStep || "empty"}`
  );
}


/* =========================
   Build Chroma Pool
========================= */

const poolIds = [
  ...new Set(
    rows
      .map(
        (item) =>
          getItemId(item)
      )
      .filter(
        (id) =>
          id &&
          !id.startsWith(
            "content-"
          )
      )
  ),
];


/* =========================
   Select 10 Questions
========================= */

const BASELINE_TOTAL =
  10;


const shuffledPool =
  shuffle(
    poolIds
  );


const baselineQuestionIds =
  shuffledPool.slice(
    0,
    BASELINE_TOTAL
  );


const baselineTotalQuestions =
  baselineQuestionIds.length;


const firstQuestionId =
  baselineQuestionIds[0] ??
  "";


const hasEnoughQuestions =
  baselineTotalQuestions ===
    BASELINE_TOTAL &&
  Boolean(
    firstQuestionId
  );


/* =========================
   Not Enough Questions
========================= */

if (!hasEnoughQuestions) {

  const reply =
    isEnglish
      ? (
          `The assessment could not start because only ${baselineTotalQuestions} valid questions were available for your current level.`
        )
      : (
          `تعذّر بدء التقييم لأن عدد الأسئلة الصالحة المتاحة لمستواك الحالي هو ${baselineTotalQuestions} فقط.`
        );


  const unavailableSession = {
    ...session,

    current_level:
      currentLevel,

    baseline_active:
      false,

    baseline_question_index:
      0,

    baseline_total_questions:
      BASELINE_TOTAL,

    baseline_score:
      0,

    baseline_correct_answers:
      0,

    baseline_wrong_answers:
      0,

    baseline_question_ids:
      JSON.stringify([]),

    baseline_answered_item_ids:
      JSON.stringify([]),

    baseline_current_item_id:
      "",

    baseline_current_levantine:
      "",

    baseline_current_msa:
      "",

    baseline_current_english:
      "",

    baseline_started_at:
      null,

    baseline_completed_at:
      null,

    current_step:
      "baseline_intro",

    last_agent_action:
      "baseline_unavailable",

    last_agent_reason:
      "not_enough_baseline_questions",

    updated_at:
      now,

    last_activity_at:
      now,
  };


  return [
    {
      json: {
        has_baseline:
          false,

        baseline_target_id:
          "",

        baseline_question_ids:
          [],

        baseline_total_questions:
          BASELINE_TOTAL,

        current_level:
          currentLevel,

        session_row:
          unavailableSession,

        response: {
          success:
            false,

          mode:
            "learning",

          action:
            "baseline_unavailable",

          reply,

          suggested_actions:
            [],

          current_level:
            currentLevel,

          preferred_language:
            preferredLanguage,

          learning_session_id:
            toText(
              session.learning_session_id
            ),
        },

        debug: {
          chroma_results:
            rows.length,

          valid_pool_ids:
            poolIds.length,

          required_questions:
            BASELINE_TOTAL,
        },
      },
    },
  ];
}


/* =========================
   Start New Baseline
========================= */

const updatedSession = {
  ...session,

  current_level:
    currentLevel,

  baseline_active:
    true,

  /*
    Zero-based index:
    0 = first question
  */
  baseline_question_index:
    0,

  baseline_total_questions:
    BASELINE_TOTAL,

  baseline_score:
    0,

  baseline_correct_answers:
    0,

  baseline_wrong_answers:
    0,

  baseline_question_ids:
    JSON.stringify(
      baselineQuestionIds
    ),

  baseline_answered_item_ids:
    JSON.stringify([]),

  baseline_current_item_id:
    "",

  baseline_current_levantine:
    "",

  baseline_current_msa:
    "",

  baseline_current_english:
    "",

  baseline_started_at:
    now,

  baseline_completed_at:
    null,

  current_step:
    "baseline_loading",

  review_active:
    false,

  review_recommended:
    false,

  last_agent_action:
    "baseline_start",

  last_agent_reason:
    "learner_started_baseline_assessment",

  updated_at:
    now,

  last_activity_at:
    now,
};


/* =========================
   Intro
========================= */

const introReply =
  isEnglish
    ? (
        `The assessment is starting now. ` +
        `It contains ${BASELINE_TOTAL} questions from your current level. ` +
        `Answer from memory as accurately as you can.`
      )
    : (
        `سيبدأ التقييم الآن. ` +
        `يتكوّن من ${BASELINE_TOTAL} أسئلة من مستواك الحالي. ` +
        `أجب من ذاكرتك قدر الإمكان.`
      );


/* =========================
   Output
========================= */

return [
  {
    json: {
      has_baseline:
        true,

      baseline_resumed:
        false,

      baseline_target_id:
        firstQuestionId,

      baseline_question_ids:
        baselineQuestionIds,

      baseline_total_questions:
        BASELINE_TOTAL,

      current_level:
        currentLevel,

      session_row:
        updatedSession,

      response: {
        success:
          true,

        mode:
          "learning",

        action:
          "baseline_start",

        reply:
          introReply,

        suggested_actions:
          [],

        baseline_active:
          true,

        baseline_resumed:
          false,

        baseline_total_questions:
          BASELINE_TOTAL,

        current_level:
          currentLevel,

        preferred_language:
          preferredLanguage,

        learning_session_id:
          toText(
            session.learning_session_id
          ),
      },

      debug: {
        resumed:
          false,

        chroma_results:
          rows.length,

        valid_pool_ids:
          poolIds.length,

        selected_baseline_ids:
          baselineQuestionIds,
      },
    },
  },
];

/*
  Prepare Baseline Question

  يحوّل عنصر Chroma إلى أول سؤال في الـBaseline Test
  بدون إظهار الإجابة الصحيحة.
*/


/* =========================
   Read Nodes
========================= */

const baselineStart =
  $("Prepare Baseline Start").first().json ?? {};

const session = {
  ...(baselineStart.session_row ?? {}),
};

const chromaResult =
  $input.first()?.json ?? {};


/* =========================
   Helpers
========================= */

function toText(value, fallback = "") {
  if (
    value === null ||
    value === undefined
  ) {
    return fallback;
  }

  if (Array.isArray(value)) {
    const firstValue =
      value.find(
        (item) =>
          item !== null &&
          item !== undefined &&
          String(item).trim()
      );

    return firstValue === undefined
      ? fallback
      : String(firstValue).trim();
  }

  const result =
    String(value).trim();

  return result || fallback;
}


function toNumber(value, fallback = 0) {
  const result =
    Number(value);

  return Number.isFinite(result)
    ? result
    : fallback;
}


function escapeRegex(value) {
  return String(value).replace(
    /[.*+?^${}()|[\]\\]/g,
    "\\$&"
  );
}


/* =========================
   Read Chroma Result
========================= */

function findMetadata(result) {
  if (
    result.document?.metadata &&
    typeof result.document.metadata === "object"
  ) {
    return result.document.metadata;
  }

  if (
    result.metadata &&
    typeof result.metadata === "object"
  ) {
    return result.metadata;
  }

  if (
    Array.isArray(result.metadatas) &&
    result.metadatas[0]
  ) {
    return result.metadatas[0];
  }

  return {};
}


function findContent(result) {
  return toText(
    result.document?.pageContent ??
    result.document?.content ??
    result.pageContent ??
    result.content ??
    result.text ??
    result.documents?.[0]
  );
}


function valueFromContent(
  content,
  labels
) {
  const source =
    toText(content);

  if (!source) {
    return "";
  }

  for (const label of labels) {
    const escapedLabel =
      escapeRegex(label);

    const pattern =
      new RegExp(
        `(?:^|\\n)\\s*${escapedLabel}\\s*[:：-]\\s*(.+?)(?=\\n|$)`,
        "i"
      );

    const match =
      source.match(pattern);

    if (match) {
      return toText(
        match[1]
      );
    }
  }

  return "";
}


/* =========================
   Extract Item
========================= */

const metadata =
  findMetadata(chromaResult);

const content =
  findContent(chromaResult);


const itemId =
  toText(
    metadata.item_id ??
    metadata.original_id ??
    metadata.source_id ??
    baselineStart.baseline_target_id
  );


const sourceId =
  toText(
    metadata.source_id ??
    metadata.original_id ??
    itemId
  );


const levantine =
  toText(
    metadata.levantine ??
    valueFromContent(
      content,
      [
        "الشامية",
        "Levantine",
        "Levantine Arabic",
      ]
    )
  );


const msa =
  toText(
    metadata.msa ??
    valueFromContent(
      content,
      [
        "الفصحى",
        "MSA",
        "Modern Standard Arabic",
      ]
    )
  );


const english =
  toText(
    metadata.english ??
    valueFromContent(
      content,
      [
        "الإنجليزية",
        "English",
        "Meaning",
      ]
    )
  );


const topic =
  toText(
    metadata.topic ??
    valueFromContent(
      content,
      [
        "الموضوع",
        "Topic",
      ]
    )
  );


/* =========================
   Baseline Progress
========================= */

const questionIndex =
  1;


const totalQuestions =
  Math.max(
    1,
    toNumber(
      session.baseline_total_questions ??
      baselineStart.baseline_total_questions,
      10
    )
  );


/* =========================
   Language
========================= */

const preferredLanguage =
  toText(
    baselineStart.response?.preferred_language ??
    session.preferred_language,
    "MSA"
  );


const isEnglish =
  preferredLanguage
    .toLowerCase() ===
    "english";


const isPhrase =
  levantine
    .split(/\s+/)
    .filter(Boolean)
    .length > 1;


/* =========================
   Build Question
========================= */

let questionText;

if (!levantine) {
  questionText =
    isEnglish
      ? "The assessment question could not be loaded."
      : "تعذّر تحميل سؤال التقييم.";
} else if (isEnglish) {
  questionText =
    isPhrase
      ? (
          `Baseline Assessment — Question ${questionIndex} of ${totalQuestions}\n` +
          `What does the phrase «${levantine}» mean in English?`
        )
      : (
          `Baseline Assessment — Question ${questionIndex} of ${totalQuestions}\n` +
          `What does the word «${levantine}» mean in English?`
        );
} else {
  questionText =
    isPhrase
      ? (
          `التقييم القبلي للمستوى — السؤال ${questionIndex} من ${totalQuestions}\n` +
          `ما معنى العبارة «${levantine}» بالفصحى؟`
        )
      : (
          `التقييم القبلي للمستوى — السؤال ${questionIndex} من ${totalQuestions}\n` +
          `ما معنى كلمة «${levantine}» بالفصحى؟`
        );
}


/* =========================
   Intro + First Question
========================= */

const intro =
  isEnglish
    ? (
        `You are now starting the 10-question assessment for your current level. ` +
        `There is no pass or fail. ` +
        `Answer from memory so we can compare your knowledge before and after learning.`
      )
    : (
        `أنت الآن تبدأ التقييم المكوّن من 10 أسئلة لمستواك الحالي. ` +
        `لا يوجد نجاح أو رسوب في هذا التقييم. ` +
        `أجب من ذاكرتك حتى نتمكن من مقارنة معرفتك قبل التعلّم وبعده.`
      );


const reply =
  `${intro}\n\n${questionText}`;


/* =========================
   Update Session
========================= */

const now =
  new Date().toISOString();


const updatedSession = {
  ...session,

  baseline_active:
    true,

  baseline_question_index:
    questionIndex,

  baseline_current_item_id:
    itemId,

  baseline_current_levantine:
    levantine,

  baseline_current_msa:
    msa,

  baseline_current_english:
    english,

  current_step:
    "baseline_question",

  last_agent_action:
    "baseline_question",

  last_agent_reason:
    "baseline_first_question_loaded",

  updated_at:
    now,

  last_activity_at:
    now,
};


/* =========================
   Frontend Response
========================= */

const response = {
  success:
    Boolean(
      itemId &&
      levantine
    ),

  mode:
    "learning",

  action:
    "baseline_question",

  reply,

  suggested_actions:
    [],

  baseline_active:
    true,

  baseline_question_index:
    questionIndex,

  baseline_total_questions:
    totalQuestions,

  current_level:
    toNumber(
      session.current_level,
      1
    ),

  current_micro_level:
    toNumber(
      session.current_micro_level,
      1
    ),

  preferred_language:
    preferredLanguage,

  learning_session_id:
    toText(
      session.learning_session_id
    ),
};


/* =========================
   Output
========================= */

return [
  {
    json: {
      session_row:
        updatedSession,

      response,

      baseline_item: {
        item_id:
          itemId,

        source_id:
          sourceId,

        levantine,

        msa,

        english,

        topic,
      },
    },
  },
];

