parameters.jsCode:
/*
  Prepare Baseline Answer Result

  المسؤوليات:
  - قراءة نتيجة Baseline Answer Evaluator
  - تحديث عدد الإجابات الصحيحة والخاطئة
  - تسجيل السؤال كمجاب عليه
  - تحديد السؤال التالي
  - إنهاء الـBaseline بعد السؤال العاشر
  - عدم كشف الإجابة الصحيحة أثناء التقييم
  - بعد انتهاء الـBaseline:
      عرض النتيجة
      شرح Learning Mode
      تجهيز المستخدم لبدء التعلم
*/


/* =========================
   Read Nodes
========================= */

const context =
  $("Build Agent Context").first().json ?? {};

const evaluatorInput =
  $input.first()?.json ?? {};

const session = {
  ...(context.session_row ?? {}),
};


/* =========================
   Helpers
========================= */

function toText(value, fallback = "") {
  if (
    value === null ||
    value === undefined
  ) {
    return fallback;
  }

  const result =
    String(value).trim();

  return result || fallback;
}


function toNumber(value, fallback = 0) {
  const result =
    Number(value);

  return Number.isFinite(result)
    ? result
    : fallback;
}


function toBoolean(value, fallback = false) {
  if (typeof value === "boolean") {
    return value;
  }

  const normalized =
    toText(value)
      .toLowerCase();

  if (
    [
      "true",
      "1",
      "yes",
    ].includes(normalized)
  ) {
    return true;
  }

  if (
    [
      "false",
      "0",
      "no",
    ].includes(normalized)
  ) {
    return false;
  }

  return fallback;
}


function parseList(value) {
  if (Array.isArray(value)) {
    return [
      ...new Set(
        value
          .map((item) => toText(item))
          .filter(Boolean)
      ),
    ];
  }

  const raw =
    toText(value);

  if (!raw) {
    return [];
  }

  try {
    const parsed =
      JSON.parse(raw);

    if (Array.isArray(parsed)) {
      return [
        ...new Set(
          parsed
            .map((item) => toText(item))
            .filter(Boolean)
        ),
      ];
    }
  } catch {
    // continue
  }

  return [
    ...new Set(
      raw
        .split(",")
        .map((item) => item.trim())
        .filter(Boolean)
    ),
  ];
}


function parseEvaluatorOutput(input) {
  let raw =
    input?.output ??
    input?.text ??
    input?.response ??
    input;

  if (
    raw &&
    typeof raw === "object" &&
    !Array.isArray(raw)
  ) {
    if (
      raw.is_correct !== undefined ||
      raw.reason_code
    ) {
      return raw;
    }
  }

  raw =
    toText(raw);

  if (!raw) {
    return {};
  }

  const cleaned =
    raw
      .replace(/^```json\s*/i, "")
      .replace(/^```\s*/i, "")
      .replace(/```$/i, "")
      .trim();

  try {
    return JSON.parse(cleaned);
  } catch {
    // try extracting JSON
  }

  const firstBrace =
    cleaned.indexOf("{");

  const lastBrace =
    cleaned.lastIndexOf("}");

  if (
    firstBrace !== -1 &&
    lastBrace > firstBrace
  ) {
    try {
      return JSON.parse(
        cleaned.slice(
          firstBrace,
          lastBrace + 1
        )
      );
    } catch {
      // fallback
    }
  }

  return {};
}


/* =========================
   Evaluator Result
========================= */

const evaluation =
  parseEvaluatorOutput(
    evaluatorInput
  );


const isCorrect =
  toBoolean(
    evaluation.is_correct,
    false
  );


const evaluationReason =
  toText(
    evaluation.reason_code,
    isCorrect
      ? "correct_answer"
      : "incorrect_answer"
  );


/* =========================
   Language
========================= */

const preferredLanguage =
  toText(
    context.preferred_language ??
    session.preferred_language,
    "MSA"
  );


const isEnglish =
  preferredLanguage
    .toLowerCase() ===
    "english";


/* =========================
   Current Baseline State
========================= */

const questionIds =
  parseList(
    session.baseline_question_ids
  );


let answeredItemIds =
  parseList(
    session.baseline_answered_item_ids
  );


const currentItemId =
  toText(
    session.baseline_current_item_id
  );


const totalQuestions =
  Math.max(
    1,
    toNumber(
      session.baseline_total_questions,
      questionIds.length || 10
    )
  );


let correctAnswers =
  Math.max(
    0,
    toNumber(
      session.baseline_correct_answers,
      0
    )
  );


let wrongAnswers =
  Math.max(
    0,
    toNumber(
      session.baseline_wrong_answers,
      0
    )
  );


/* =========================
   Record Current Answer
========================= */

const alreadyAnswered =
  currentItemId &&
  answeredItemIds.includes(
    currentItemId
  );


if (
  currentItemId &&
  !alreadyAnswered
) {
  answeredItemIds.push(
    currentItemId
  );

  if (isCorrect) {
    correctAnswers += 1;
  } else {
    wrongAnswers += 1;
  }
}


/* =========================
   Calculate Progress
========================= */

const answeredCount =
  answeredItemIds.length;


const baselineScore =
  Math.round(
    (
      correctAnswers /
      totalQuestions
    ) *
    100
  );


/* =========================
   Find Next Question
========================= */

const answeredSet =
  new Set(
    answeredItemIds
  );


const nextQuestionId =
  questionIds.find(
    (id) =>
      !answeredSet.has(id)
  ) ?? "";


const nextQuestionPosition =
  nextQuestionId
    ? questionIds.indexOf(
        nextQuestionId
      )
    : -1;


const nextQuestionIndex =
  nextQuestionPosition >= 0
    ? nextQuestionPosition + 1
    : 0;


const hasNextQuestion =
  Boolean(
    nextQuestionId
  ) &&
  answeredCount <
    totalQuestions;


const baselineFinished =
  !hasNextQuestion ||
  answeredCount >=
    totalQuestions;


/* =========================
   Time
========================= */

const now =
  new Date().toISOString();


/* =========================
   Update Session
========================= */

const updatedSession = {
  ...session,

  baseline_active:
    !baselineFinished,

  baseline_correct_answers:
    correctAnswers,

  baseline_wrong_answers:
    wrongAnswers,

  baseline_score:
    baselineScore,

  baseline_answered_item_ids:
    JSON.stringify(
      answeredItemIds
    ),

  baseline_question_index:
    baselineFinished
      ? 0
      : nextQuestionIndex,

  baseline_current_item_id:
    "",

  baseline_current_levantine:
    "",

  baseline_current_msa:
    "",

  baseline_current_english:
    "",

  baseline_completed_at:
    baselineFinished
      ? now
      : (
          session.baseline_completed_at ??
          null
        ),

  /*
    بعد انتهاء الـBaseline
    يصبح المستخدم جاهزًا لبدء التعلم.
  */
  current_step:
    baselineFinished
      ? "awaiting_start"
      : "baseline_loading",

  last_agent_action:
    baselineFinished
      ? "baseline_completed"
      : "baseline_answer",

  last_agent_reason:
    baselineFinished
      ? "baseline_completed_ready_for_learning"
      : evaluationReason,

  updated_at:
    now,

  last_activity_at:
    now,
};


/* =========================
   Learner Response
========================= */

let reply;
let suggestedActions;


if (baselineFinished) {

  if (isEnglish) {
    reply =
      `Your baseline assessment is complete.\n` +
      `Your score is ${baselineScore}%.\n` +
      `You answered ${correctAnswers} out of ${totalQuestions} questions correctly.\n\n` +

      `This result will be used to compare your knowledge before and after learning.\n\n` +

      `Here's how Learning Mode works:\n` +
      `In each stage, you'll learn 20 Levantine Arabic words or expressions. ` +
      `After completing them, you'll take a short quiz with 5 questions. ` +
      `You need at least 4 correct answers out of 5 to move to the next stage.\n\n` +

      `If you don't pass, you'll review the items that need more practice and then try the quiz again.\n\n` +

      `When you decide to finish your overall learning experience, type “I am done learning” to start the final assessment.\n\n` +

      `Ready to start learning?`;

    suggestedActions = [
      "Let's start",
    ];

  } else {

    reply =
      `انتهى التقييم القبلي للمستوى.\n` +
      `علامتك هي ${baselineScore}%.\n` +
      `أجبت عن ${correctAnswers} من أصل ${totalQuestions} أسئلة بشكل صحيح.\n\n` +

      `ستُستخدم هذه النتيجة لمقارنة معرفتك قبل التعلّم وبعده.\n\n` +

      `طريقة وضع التعلّم بسيطة:\n` +
      `في كل مرحلة ستتعلّم 20 كلمة أو عبارة من اللهجة الشامية. ` +
      `بعد إكمالها، ستجيب عن اختبار قصير من 5 أسئلة. ` +
      `تحتاج إلى 4 إجابات صحيحة من أصل 5 للانتقال إلى المرحلة التالية.\n\n` +

      `إذا لم تجتز الاختبار، ستراجع العناصر التي تحتاج إلى تدريب ثم تحاول مرة أخرى.\n\n` +

      `وعندما تقرر إنهاء تجربة التعلّم، اكتب «أنهيت التعلّم» لبدء التقييم النهائي.\n\n` +

      `هل أنت مستعد لبدء التعلّم؟`;

    suggestedActions = [
      "يلا نبدأ",
    ];
  }

} else {

  reply =
    isEnglish
      ? "Your answer has been recorded."
      : "تم تسجيل إجابتك.";

  suggestedActions = [];
}


/* =========================
   Response
========================= */

const response = {
  success:
    true,

  mode:
    "learning",

  action:
    baselineFinished
      ? "baseline_completed"
      : "baseline_answer_recorded",

  reply,

  suggested_actions:
    suggestedActions,

  baseline_active:
    !baselineFinished,

  baseline_finished:
    baselineFinished,

  baseline_score:
    baselineScore,

  baseline_correct_answers:
    correctAnswers,

  baseline_wrong_answers:
    wrongAnswers,

  baseline_total_questions:
    totalQuestions,

  baseline_answered_questions:
    answeredCount,

  current_level:
    Math.max(
      1,
      toNumber(
        session.current_level,
        1
      )
    ),

  current_micro_level:
    Math.max(
      1,
      toNumber(
        session.current_micro_level,
        1
      )
    ),

  words_completed:
    Math.max(
      0,
      toNumber(
        session.words_completed,
        0
      )
    ),

  words_total:
    Math.max(
      1,
      toNumber(
        session.words_total,
        20
      )
    ),

  preferred_language:
    preferredLanguage,

  learning_session_id:
    toText(
      session.learning_session_id
    ),
};


/* =========================
   Output
========================= */

return [
  {
    json: {
      is_correct:
        isCorrect,

      evaluation_reason:
        evaluationReason,

      baseline_finished:
        baselineFinished,

      has_next_baseline_question:
        hasNextQuestion,

      baseline_next_target_id:
        nextQuestionId,

      baseline_next_question_index:
        nextQuestionIndex,

      baseline_score:
        baselineScore,

      baseline_correct_answers:
        correctAnswers,

      baseline_wrong_answers:
        wrongAnswers,

      baseline_total_questions:
        totalQuestions,

      baseline_answered_questions:
        answeredCount,

      session_row:
        updatedSession,

      response,
    },
  },
];

/*
  Prepare Next Baseline Question

  يحمّل السؤال التالي من Chroma
  ويجهّزه للـBaseline Assessment بدون كشف
  إذا كانت الإجابة السابقة صحيحة أو خاطئة.
*/


/* =========================
   Read Nodes
========================= */

const answerResult =
  $("Prepare Baseline Answer Result").first().json ?? {};

const session = {
  ...(answerResult.session_row ?? {}),
};

const chromaResult =
  $input.first()?.json ?? {};


/* =========================
   Helpers
========================= */

function toText(value, fallback = "") {
  if (
    value === null ||
    value === undefined
  ) {
    return fallback;
  }

  if (Array.isArray(value)) {
    const firstValue =
      value.find(
        (item) =>
          item !== null &&
          item !== undefined &&
          String(item).trim()
      );

    return firstValue === undefined
      ? fallback
      : String(firstValue).trim();
  }

  const result =
    String(value).trim();

  return result || fallback;
}


function toNumber(value, fallback = 0) {
  const result =
    Number(value);

  return Number.isFinite(result)
    ? result
    : fallback;
}


function escapeRegex(value) {
  return String(value).replace(
    /[.*+?^${}()|[\]\\]/g,
    "\\$&"
  );
}


/* =========================
   Read Chroma Result
========================= */

function findMetadata(result) {
  if (
    result.document?.metadata &&
    typeof result.document.metadata === "object"
  ) {
    return result.document.metadata;
  }

  if (
    result.metadata &&
    typeof result.metadata === "object"
  ) {
    return result.metadata;
  }

  if (
    Array.isArray(result.metadatas) &&
    result.metadatas[0]
  ) {
    return result.metadatas[0];
  }

  return {};
}


function findContent(result) {
  return toText(
    result.document?.pageContent ??
    result.document?.content ??
    result.pageContent ??
    result.content ??
    result.text ??
    result.documents?.[0]
  );
}


function valueFromContent(
  content,
  labels
) {
  const source =
    toText(content);

  if (!source) {
    return "";
  }

  for (const label of labels) {
    const escapedLabel =
      escapeRegex(label);

    const pattern =
      new RegExp(
        `(?:^|\\n)\\s*${escapedLabel}\\s*[:：-]\\s*(.+?)(?=\\n|$)`,
        "i"
      );

    const match =
      source.match(pattern);

    if (match) {
      return toText(
        match[1]
      );
    }
  }

  return "";
}


/* =========================
   Extract Item
========================= */

const metadata =
  findMetadata(chromaResult);

const content =
  findContent(chromaResult);


const itemId =
  toText(
    metadata.item_id ??
    metadata.original_id ??
    metadata.source_id ??
    answerResult.baseline_next_target_id
  );


const sourceId =
  toText(
    metadata.source_id ??
    metadata.original_id ??
    itemId
  );


const levantine =
  toText(
    metadata.levantine ??
    valueFromContent(
      content,
      [
        "الشامية",
        "Levantine",
        "Levantine Arabic",
      ]
    )
  );


const msa =
  toText(
    metadata.msa ??
    valueFromContent(
      content,
      [
        "الفصحى",
        "MSA",
        "Modern Standard Arabic",
      ]
    )
  );


const english =
  toText(
    metadata.english ??
    valueFromContent(
      content,
      [
        "الإنجليزية",
        "English",
        "Meaning",
      ]
    )
  );


const topic =
  toText(
    metadata.topic ??
    valueFromContent(
      content,
      [
        "الموضوع",
        "Topic",
      ]
    )
  );


/* =========================
   Baseline Progress
========================= */

const questionIndex =
  Math.max(
    1,
    toNumber(
      answerResult.baseline_next_question_index,
      session.baseline_question_index || 2
    )
  );


const totalQuestions =
  Math.max(
    1,
    toNumber(
      session.baseline_total_questions ??
      answerResult.baseline_total_questions,
      10
    )
  );


/* =========================
   Language
========================= */

const preferredLanguage =
  toText(
    answerResult.preferred_language ??
    session.preferred_language ??
    $("Build Agent Context").first().json.preferred_language,
    "MSA"
  );


const isEnglish =
  preferredLanguage
    .toLowerCase() ===
    "english";


const isPhrase =
  levantine
    .split(/\s+/)
    .filter(Boolean)
    .length > 1;


/* =========================
   Build Question
========================= */

let questionText;

if (!levantine) {
  questionText =
    isEnglish
      ? "The next baseline assessment question could not be loaded."
      : "تعذّر تحميل سؤال التقييم القبلي التالي.";
} else if (isEnglish) {
  questionText =
    isPhrase
      ? (
          `Baseline Assessment — Question ${questionIndex} of ${totalQuestions}\n` +
          `What does the phrase «${levantine}» mean in English?`
        )
      : (
          `Baseline Assessment — Question ${questionIndex} of ${totalQuestions}\n` +
          `What does the word «${levantine}» mean in English?`
        );
} else {
  questionText =
    isPhrase
      ? (
          `التقييم القبلي للمستوى — السؤال ${questionIndex} من ${totalQuestions}\n` +
          `ما معنى العبارة «${levantine}» بالفصحى؟`
        )
      : (
          `التقييم القبلي للمستوى — السؤال ${questionIndex} من ${totalQuestions}\n` +
          `ما معنى كلمة «${levantine}» بالفصحى؟`
        );
}


/* =========================
   Response Text
========================= */

/*
  أثناء الـBaseline لا نكشف
  إذا كانت الإجابة السابقة صحيحة أو خاطئة.
*/

const reply =
  isEnglish
    ? (
        `Your answer has been recorded.\n\n` +
        questionText
      )
    : (
        `تم تسجيل إجابتك.\n\n` +
        questionText
      );


/* =========================
   Update Session
========================= */

const now =
  new Date().toISOString();


const updatedSession = {
  ...session,

  baseline_active:
    true,

  baseline_question_index:
    questionIndex,

  baseline_current_item_id:
    itemId,

  baseline_current_levantine:
    levantine,

  baseline_current_msa:
    msa,

  baseline_current_english:
    english,

  current_step:
    "baseline_question",

  last_agent_action:
    "baseline_next_question",

  last_agent_reason:
    "next_baseline_question_loaded",

  updated_at:
    now,

  last_activity_at:
    now,
};


/* =========================
   Frontend Response
========================= */

const response = {
  success:
    Boolean(
      itemId &&
      levantine
    ),

  mode:
    "learning",

  action:
    "baseline_question",

  reply,

  suggested_actions:
    [],

  baseline_active:
    true,

  baseline_question_index:
    questionIndex,

  baseline_total_questions:
    totalQuestions,

  baseline_score:
    toNumber(
      session.baseline_score,
      0
    ),

  baseline_correct_answers:
    toNumber(
      session.baseline_correct_answers,
      0
    ),

  baseline_wrong_answers:
    toNumber(
      session.baseline_wrong_answers,
      0
    ),

  current_level:
    toNumber(
      session.current_level,
      1
    ),

  current_micro_level:
    toNumber(
      session.current_micro_level,
      1
    ),

  preferred_language:
    preferredLanguage,

  learning_session_id:
    toText(
      session.learning_session_id
    ),
};


/* =========================
   Output
========================= */

return [
  {
    json: {
      session_row:
        updatedSession,

      response,

      baseline_item: {
        item_id:
          itemId,

        source_id:
          sourceId,

        levantine,

        msa,

        english,

        topic,
      },
    },
  },
];
